/**
 * Форматер произвольных выражений SDBL (фаза 6.10).
 *
 * Конструктор 1С переотрисовывает произвольные выражения (условия ГДЕ/ИМЕЮЩИЕ,
 * условия соединений ПО, поля выборки) в собственном каноническом виде: дерево
 * булевых операторов (ИЛИ < И < НЕ) и оператора ВЫБОР раскладывается по строкам
 * с фиксированными отступами и скобками; ЛИСТЬЯ (сравнения, вызовы функций,
 * арифметика, МЕЖДУ a И b, ЕСТЬ [НЕ] NULL, ПОДОБНО … СПЕЦСИМВОЛ …) сохраняются
 * ДОСЛОВНО срезом исходной строки по позициям токенов.
 *
 * Самодостаточный модуль: переиспользует `tokenize` из sdblLexer (без правок
 * лексера). Распознаёт не-ключевые слова ИЛИ/НЕ/ВЫБОР/КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ/ЕСТЬ
 * по `.value.toUpperCase()`.
 */
import { tokenize, type Token } from './sdblLexer';
import { FUNCTION_CATALOG, type FunctionGroup, type FunctionLeaf } from './functionCatalog';

export type ExprSlot = 'where' | 'having' | 'join' | 'select';

const TAB = '\t';

/**
 * Хук канонического ре-рендера ИНЛАЙН-подзапроса членства (`Поле В (ВЫБРАТЬ … ИЗ …)`).
 * Реализация живёт в генераторе (parseDocument + renderConditionSubquery) — импортировать
 * её сюда нельзя (циклическая зависимость), поэтому генератор регистрирует её через
 * `setInlineSubqueryReflow`. Принимает текст листа и целевой отступ строки `(ВЫБРАТЬ`,
 * возвращает массив строк или null (если лист не распознан как инлайн-членство).
 */
let inlineSubqueryReflow: ((text: string, subBase: number) => string[] | null) | null = null;
export function setInlineSubqueryReflow(fn: (text: string, subBase: number) => string[] | null): void {
  inlineSubqueryReflow = fn;
}

// --- Нормализация регистра ключевых слов в листьях (фаза 6.12) ---------------
//
// Конструктор 1С приводит к ВЕРХНЕМУ регистру РАСПОЗНАННЫЕ имена функций,
// операторов, литералы и имена примитивных типов внутри произвольных выражений,
// сохраняя при этом регистр идентификаторов (поля, псевдонимы, параметры &X,
// сегменты пути после точки, ссылки на типы метаданных вида Справочник.Имя).

/** Слова-имена функций/операторов из каталога (только буквенные ярлыки). */
const FUNCTION_WORDS: Set<string> = (() => {
  const acc: string[] = [];
  const walk = (n: FunctionGroup | FunctionLeaf): void => {
    if ('children' in n) n.children.forEach(walk);
    else acc.push(n.label);
  };
  walk(FUNCTION_CATALOG);
  const wordRe = /^[A-Za-zА-Яа-яЁё][A-Za-zА-Яа-яЁё0-9]*$/u;
  return new Set(acc.filter((l) => wordRe.test(l)).map((l) => l.toUpperCase()));
})();

/** Литералы-ключевые слова: всегда верхний регистр (вне пути/параметра). */
const LITERAL_WORDS = new Set(['НЕОПРЕДЕЛЕНО', 'ИСТИНА', 'ЛОЖЬ', 'NULL']);

/** Агрегатные функции — вызов `ИМЯ(…)` без пробела перед скобкой. */
const AGGREGATE_WORDS = new Set(['СУММА', 'КОЛИЧЕСТВО', 'МАКСИМУМ', 'МИНИМУМ', 'СРЕДНЕЕ']);

/**
 * Функции-вызовы, у которых конструктор 1С УБИРАЕТ пробел перед открывающей скобкой
 * (`ЗНАЧЕНИЕ (…)` → `ЗНАЧЕНИЕ(…)`), в отличие от булевых/группирующих скобок (`И (…)`,
 * `НЕ (a, b) В …`). `ЗНАЧЕНИЕ` — однозначно вызов перечислимого литерала, пробела
 * перед скобкой у него не бывает (фаза 6.16).
 */
const CALL_NOSPACE_WORDS = new Set(['ЗНАЧЕНИЕ']);

/** Примитивные типы: верхний регистр в позиции типа (ВЫРАЗИТЬ … КАК <Тип>, ТИП(<Тип>)). */
const PRIMITIVE_TYPE_WORDS = new Set(['СТРОКА', 'ЧИСЛО', 'ДАТА', 'БУЛЕВО']);

/**
 * Литералы периода (гранулярность) в позиции аргумента `<Период>` функций дат
 * (НАЧАЛОПЕРИОДА, КОНЕЦПЕРИОДА, ДОБАВИТЬКДАТЕ, РАЗНОСТЬДАТ): конструктор 1С приводит
 * их к ВЕРХНЕМУ регистру (`…, День)` → `…, ДЕНЬ)`). Распознаются как голый токен-слово
 * в позиции аргумента (после `,` или `(`), НЕ как `.`-квалифицированное поле и НЕ как
 * имя функции (за словом не следует `(`).
 */
const PERIOD_WORDS = new Set([
  'ГОД', 'ПОЛУГОДИЕ', 'КВАРТАЛ', 'МЕСЯЦ', 'ДЕКАДА', 'НЕДЕЛЯ', 'ДЕНЬ', 'ЧАС', 'МИНУТА', 'СЕКУНДА',
]);

/** Функции дат, принимающие аргумент `<Период>` (гранулярность). */
const PERIOD_FUNCTIONS = new Set(['НАЧАЛОПЕРИОДА', 'КОНЕЦПЕРИОДА', 'ДОБАВИТЬКДАТЕ', 'РАЗНОСТЬДАТ']);

function tokUpper(t: Token): string {
  return (t.text ?? t.value).toUpperCase();
}

// --- Нормализация пробелов в листьях (фаза 6.12, класс C-misc) ----------------
//
// Конструктор 1С нормализует пробелы между токенами произвольного выражения,
// сохраняя при этом содержимое строковых ("…") и датовых ('…') литералов дословно.
// Доказанные на корпусе оракула правила (нулевая регрессия на принятых файлах):
//   1) одиночный пробел вокруг бинарных операторов сравнения  = <> < > <= >=
//      (`a =b` → `a = b`, `X.Поле=Y` → `X.Поле = Y`);
//   2) одиночный пробел после запятой (`f(a,  b)` → `f(a, b)`, `(1,1,1)` → `(1, 1, 1)`);
//   3) схлопывание серий из 2+ пробелов в один (`ЕСТЬNULL(X,  "")` → `…, "")`).
// Нормализация применяется ТОЛЬКО к пробельным промежуткам между токенами и
// ТОЛЬКО если промежуток не содержит перевода строки (многострочные выражения
// сохраняют свою структуру). Литералы не затрагиваются: их внутренние пробелы —
// часть текста токена, а лексер выдаёт литерал одним токеном.

/** Операторы сравнения (пунктуация), вокруг которых конструктор ставит ровно один пробел. */
const COMPARISON_PUNCT = new Set(['=', '<>', '<', '>', '<=', '>=']);

// Слова, после которых `-` — УНАРНЫЙ (начинает выражение-операнд), а не бинарное
// вычитание. Конструктор 1С печатает унарный минус БЕЗ пробела после него
// (`ИНАЧЕ -Поле`, `ТОГДА -1`), тогда как бинарный минус сохраняет пробелы (`a - b`).
// Это зарезервированные ключевые слова/операторы 1С — именами полей быть не могут,
// поэтому слово в этом множестве однозначно означает позицию начала операнда.
const UNARY_MINUS_PREV_WORDS = new Set([
  'ИНАЧЕ', 'ТОГДА', 'КОГДА', 'ВЫБОР', 'И', 'ИЛИ', 'НЕ', 'МЕЖДУ', 'В',
  'ПОДОБНО', 'ЕСТЬ', 'КАК', 'ГДЕ', 'ИМЕЮЩИЕ', 'СПЕЦСИМВОЛ', 'ИЕРАРХИИ',
]);

/**
 * Сплющивает лист в ОДНУ строку: конструктор 1С печатает листовое подвыражение
 * (значение после ТОГДА/ИНАЧЕ, операнд условия КОГДА, сравнение/вызов) на одной
 * строке вне зависимости от того, как разработчик разбил его в исходнике. Любая
 * серия пробельных символов МЕЖДУ токенами (включая переводы строк и табы)
 * схлопывается в один пробел; содержимое строковых ("…") и датовых ('…') литералов
 * сохраняется дословно (лексер выдаёт литерал одним токеном, промежутки правятся
 * только между токенами). Возвращает исходник без изменений, если он не
 * токенизируется.
 */
/**
 * Содержит ли лист вложенный подзапрос (ключевое слово ВЫБРАТЬ среди токенов).
 * Подзапрос в `В (ВЫБРАТЬ …)` конструктор раскладывает по строкам как полноценный
 * запрос — такой лист нельзя сплющивать в одну строку.
 */
export function leafHasSubquery(raw: string): boolean {
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return false;
  }
  return toks.some((t) => (t.type === 'keyword' || t.type === 'ident') && t.value.toUpperCase() === 'ВЫБРАТЬ');
}

/**
 * Содержит ли лист вложенный ВЫБОР…КОНЕЦ (`ВЫБОР… КОНЕЦ <op> …` как значение-слот).
 * Такой CASE конструктор раскладывает построчно (reindentLeafCase) — лист сплющивать
 * нельзя, иначе схлопнется в одну строку (фаза 6.15.21).
 */
export function leafHasCase(raw: string): boolean {
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return false;
  }
  return toks.some((t) => (t.type === 'keyword' || t.type === 'ident') && t.value.toUpperCase() === 'ВЫБОР');
}

/**
 * Квирк конструктора 1С: предикат `ЕСТЬ НЕ NULL` ВСЕГДА печатается с ОДНИМ лишним
 * пробелом после `NULL`. На конце строки это даёт хвостовой пробел (`… ЕСТЬ НЕ NULL `),
 * а перед псевдонимом — двойной пробел (`… ЕСТЬ НЕ NULL  КАК Алиас`). Форма без `НЕ`
 * (`ЕСТЬ NULL`) лишнего пробела НЕ получает. Подтверждено по ВСЕМУ golden-корпусу:
 * `ЕСТЬ НЕ NULL` на конце строки — 562/562 с хвостовым пробелом (0 без); `ЕСТЬ НЕ NULL
 * КАК` — 19/19 с двойным пробелом (0 с одинарным); `ЕСТЬ NULL` (без `НЕ`) — 2727/2727
 * без хвостового пробела, 86/86 с одинарным пробелом перед `КАК`.
 *
 * Применяется построчно (квирк действует на каждую строку листа/ветки, а не только на
 * финальную) и идемпотентно (если пробел уже стоит — строка не меняется). Работает в
 * булевых слотах (ГДЕ/ИМЕЮЩИЕ/КОГДА/ИНАЧЕ) и в слоте выборки (`… ЕСТЬ НЕ NULL КАК …`).
 */
const EST_NE_NULL_EOL_RE = /(^|[^\p{L}\p{N}_])ЕСТЬ\s+НЕ\s+NULL$/u;
const EST_NE_NULL_KAK_RE = /((?:^|[^\p{L}\p{N}_])ЕСТЬ\s+НЕ\s+NULL) (КАК[\s(])/gu;
// `… ЕСТЬ НЕ NULL )` перед ЗАКРЫВАЮЩЕЙ скобкой группы — тот же квирк: один лишний
// пробел после NULL сохраняется (`(Поле ЕСТЬ НЕ NULL )`). Фаза 6.16.76, корпус.
const EST_NE_NULL_PAREN_RE = /((?:^|[^\p{L}\p{N}_])ЕСТЬ\s+НЕ\s+NULL)\)/gu;
function appendIsNotNullToLine(line: string): string {
  // `… ЕСТЬ НЕ NULL КАК Алиас` → один лишний пробел перед `КАК` (двойной пробел).
  let out = line.replace(EST_NE_NULL_KAK_RE, '$1  $2');
  // `… ЕСТЬ НЕ NULL)` → один пробел перед закрывающей скобкой (`ЕСТЬ НЕ NULL )`).
  out = out.replace(EST_NE_NULL_PAREN_RE, '$1 )');
  // `… ЕСТЬ НЕ NULL` на конце строки → один хвостовой пробел.
  return EST_NE_NULL_EOL_RE.test(out) ? out + ' ' : out;
}
export function appendIsNotNullTrailingSpace(text: string): string {
  return text.includes('\n')
    ? text.split('\n').map(appendIsNotNullToLine).join('\n')
    : appendIsNotNullToLine(text);
}

/**
 * Квирк конструктора 1С (фаза 6.15.12, paren-only): «голый» вызов-приведение
 * `ВЫРАЗИТЬ(…)`, стоящий ЦЕЛИКОМ операндом сравнения (`ВЫРАЗИТЬ(…) cmp X` или
 * `X cmp ВЫРАЗИТЬ(…)`), конструктор печатает в скобках: `(ВЫРАЗИТЬ(…)) cmp X`.
 * Правило УЗКОЕ — подтверждено MCP-пробами:
 *   - `ВЫРАЗИТЬ(…).Поле <> …` (доступ к полю после приведения) — НЕ оборачивается;
 *   - `ТИПЗНАЧЕНИЯ(…) = ТИП(…)` и обычные вызовы функций — НЕ оборачиваются;
 *   - оборачивается ТОЛЬКО операнд, а не всё сравнение; работает с обеих сторон.
 * Применяется к листу булева слота (ГДЕ/ИМЕЮЩИЕ/ПО). Лист с переводом строки или с
 * верхнеуровневым булевым оператором сюда не приходит (это уже не лист-сравнение).
 */
const COMPARE_OPS = new Set(['=', '<>', '<', '>', '<=', '>=']);
// 6.16.69: бинарные операторы, к которым применимо правило обёртки голого ВЫРАЗИТЬ-
// операнда: сравнение И арифметика (`* / % + -`). Конструктор оборачивает голый
// ВЫРАЗИТЬ(…), стоящий ОПЕРАНДОМ любого такого оператора, в любом контексте
// (ТОГДА/ИНАЧЕ/КОГДА/И), а не только в верхнеуровневом сравнении.
const CAST_OPERAND_OPS = new Set([...COMPARE_OPS, '+', '-', '*', '/', '%']);
export function wrapBareCastOperand(text: string): string {
  if (text.includes('\n')) return text;
  let toks: Token[];
  try {
    toks = tokenize(text);
  } catch {
    return text;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length === 0) return text;
  // Индексы верхнеуровневых (глубина скобок 0) бинарных операторов сравнения/арифметики.
  // Они делят токены на ОПЕРАНДЫ; каждый операнд-«голый ВЫРАЗИТЬ» оборачивается.
  const opIdx: number[] = [];
  let depth = 0;
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    const v = t.text ?? t.value;
    if (v === '(') { depth++; continue; }
    if (v === ')') { if (depth > 0) depth--; continue; }
    if (depth !== 0) continue;
    if (t.type === 'punct' && CAST_OPERAND_OPS.has(v)) {
      // Унарный `+`/`-` (в начале или сразу после другого оператора) — не делитель.
      if ((v === '+' || v === '-') && (i === 0 || opIdx[opIdx.length - 1] === i - 1)) continue;
      opIdx.push(i);
    }
  }
  if (opIdx.length === 0) return text;
  // Голый вызов-приведение ВЫРАЗИТЬ: токены `ВЫРАЗИТЬ` `(` … сбалансированно `)`,
  // покрывающие ВЕСЬ операнд (за `)` ничего нет — иначе это `.Поле` или арифметика).
  const isBareCast = (ops: Token[]): boolean => {
    if (ops.length < 3) return false;
    const head = ops[0];
    if ((head.text ?? head.value).toUpperCase() !== 'ВЫРАЗИТЬ') return false;
    if ((ops[1].text ?? ops[1].value) !== '(') return false;
    let d = 0;
    for (let i = 1; i < ops.length; i++) {
      const v = ops[i].text ?? ops[i].value;
      if (v === '(') d++;
      else if (v === ')') { d--; if (d === 0) return i === ops.length - 1; }
    }
    return false;
  };
  const opStr = (ops: Token[]): string => {
    const first = ops[0];
    const last = ops[ops.length - 1];
    const end = last.pos + (last.text ?? last.value).length;
    return text.slice(first.pos, end);
  };
  // Границы операндов: [start, opIdx[0]), (opIdx[0], opIdx[1]), …, (last, end).
  const bounds = [0, ...opIdx.map((x) => x + 1)];
  const ends = [...opIdx, sig.length];
  let changed = false;
  const parts: string[] = [];
  for (let k = 0; k < bounds.length; k++) {
    const ops = sig.slice(bounds[k], ends[k]);
    if (ops.length === 0) { parts.push(''); continue; }
    if (isBareCast(ops)) { parts.push(`(${opStr(ops)})`); changed = true; }
    else parts.push(opStr(ops));
    // Оператор между операндами.
    if (k < opIdx.length) parts.push(sig[opIdx[k]].text ?? sig[opIdx[k]].value);
  }
  if (!changed) return text;
  return parts.join(' ');
}

/**
 * Содержит ли лист верхнеуровневый булев оператор И/ИЛИ (вне скобок и вне `МЕЖДУ a
 * И b`). Такой «лист» — на самом деле булево значение-выражение, которое конструктор
 * раскладывает по строкам с переносом по оператору; сплющивать его нельзя.
 */
export function leafHasTopBoolean(raw: string): boolean {
  return leafHasBoolean(raw, false);
}

/**
 * Обобщение: булев оператор И/ИЛИ на верхнем уровне (`anyDepth=false`) либо на
 * ЛЮБОЙ глубине скобок (`anyDepth=true`); `И` диапазона `МЕЖДУ a И b` не считается.
 * Конструктор переносит строку по И/ИЛИ и внутри скобочной группы
 * (`a <> (x И y)` печатается с переносом) — для сплющивания листа важна
 * любая глубина.
 */
function leafHasBoolean(raw: string, anyDepth: boolean): boolean {
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return false;
  }
  let depth = 0;
  let betweenPending = 0;
  for (const t of toks) {
    if (t.type === 'eof') break;
    if (t.type === 'punct' && t.value === '(') { depth++; continue; }
    if (t.type === 'punct' && t.value === ')') { if (depth > 0) depth--; continue; }
    if (!anyDepth && depth !== 0) continue;
    if (isWord(t, 'МЕЖДУ')) { betweenPending++; continue; }
    if (isOr(t)) return true;
    if (isAnd(t)) {
      if (betweenPending > 0) betweenPending--;
      else return true;
    }
  }
  return false;
}

export function flattenLeafText(raw: string): string {
  if (!raw || !/\s/.test(raw)) return raw;
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length === 0) return raw;
  let out = '';
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    const text = t.text ?? t.value;
    if (i > 0) {
      const prev = sig[i - 1];
      const gapFrom = prev.pos + (prev.text ?? prev.value).length;
      const gap = raw.slice(gapFrom, t.pos);
      // Пунктуационное сплющивание как у конструктора 1С: пробел не ставится
      // СРАЗУ ПОСЛЕ открывающей `(` и ПЕРЕД закрывающей `)` / запятой, даже если в
      // исходнике там был перенос строки/отступ (`(\n\tЗНАЧЕНИЕ…` → `(ЗНАЧЕНИЕ…`).
      const prevText = prev.text ?? prev.value;
      const noSpaceAfter = prevText === '(';
      const noSpaceBefore = text === ')' || text === ',';
      out += gap.length > 0 && !noSpaceAfter && !noSpaceBefore ? ' ' : '';
    }
    out += text;
  }
  return out;
}

/**
 * Сплющивание МНОГОСТРОЧНОГО листового выражения в одну строку, если это
 * безопасно (фаза 6.15.3, MCP-пробы): конструктор 1С печатает листовые выражения
 * (вложенные вызовы функций вида `ЕСТЬNULL(a, ЕСТЬNULL(b, c))`, разбитые
 * разработчиком по строкам) ОДНОЙ строкой — и в списке выборки, и в ГДЕ.
 * Не сплющиваем: лист с вложенным подзапросом (`В (ВЫБРАТЬ …)` раскладывается
 * по строкам), лист с верхнеуровневым И/ИЛИ (конструктор переносит по
 * оператору, в т.ч. ВНУТРИ скобочной группы: `a <> (x И y)`), лист с ВЫБОР
 * где угодно — даже внутри вызова функции (`СУММА(ВЫБОР … КОНЕЦ)`) конструктор
 * раскладывает ВЫБОР по строкам, — а также лист, в который парсер ошибочно
 * захватил хвостовые секции запроса (`…3\n\nУПОРЯДОЧИТЬ ПО …`, `{ГДЕ …}`) —
 * их многострочную геометрию трогать нельзя. Однострочный текст возвращается
 * как есть.
 */
export function flattenMultilineLeaf(raw: string): string {
  return raw.includes('\n') && !leafFlattenBlocked(raw) && !leafHasBoolean(raw, true)
    ? flattenLeafText(raw)
    : raw;
}

/**
 * Стоп-слова сплющивания листа: подзапрос (ВЫБРАТЬ), ВЫБОР, секции запроса,
 * которые парсер мог затянуть в хвост листа, и `{` построителя.
 *
 * Стоп-слово как СЕГМЕНТ ПУТИ (`Док.Итоги`, `ВТ.Поместить`) сплющивание НЕ
 * блокирует: после точки это имя поля, а не секция запроса (подтверждено
 * MCP-пробой: `ЕСТЬNULL(ВТВалюты.Итоги,\n "")` конструктор печатает одной
 * строкой). Исключение — зарезервированные ВЫБРАТЬ/ВЫБОР: они блокируют
 * безусловно (именем поля быть не могут).
 */
const FLATTEN_STOP_WORDS = new Set([
  'ВЫБРАТЬ', 'ВЫБОР', 'УПОРЯДОЧИТЬ', 'СГРУППИРОВАТЬ', 'ИТОГИ', 'ОБЪЕДИНИТЬ',
  'ИНДЕКСИРОВАТЬ', 'ИМЕЮЩИЕ', 'ПОМЕСТИТЬ',
]);
const FLATTEN_STOP_RESERVED = new Set(['ВЫБРАТЬ', 'ВЫБОР']);
function leafFlattenBlocked(raw: string): boolean {
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return true;
  }
  for (let k = 0; k < toks.length; k++) {
    const t = toks[k];
    if (t.type === 'punct' && (t.value === '{' || t.value === '}')) return true;
    if ((t.type === 'keyword' || t.type === 'ident') && FLATTEN_STOP_WORDS.has(t.value.toUpperCase())) {
      if (FLATTEN_STOP_RESERVED.has(t.value.toUpperCase())) return true;
      const prev = toks[k - 1];
      const isPathSegment = prev !== undefined && prev.type === 'punct' && prev.value === '.';
      if (!isPathSegment) return true;
    }
  }
  return false;
}

/**
 * Перебазировка подзапроса внутри листа (фаза 6.15.9, MCP-пробы): конструктор 1С
 * переотрисовывает блок `(ВЫБРАТЬ …)` правого операнда `В`/`В ИЕРАРХИИ` как
 * полноценный запрос с отступом строки `(ВЫБРАТЬ` по КОНТЕКСТУ слота, игнорируя
 * отступы разработчика. Здесь — РАВНОМЕРНЫЙ сдвиг блока (внутренняя относительная
 * геометрия сохраняется): полный ре-рендер парсером ломает коррелированные
 * подзапросы (квалификация ссылок на внешние таблицы без знания их псевдонимов).
 * `base` — целевой отступ строки `(ВЫБРАТЬ`; каждый ведущий `НЕ` головы листа
 * добавляет +1. Хвостовой пробел строки перед подзапросом (`… В `) конструктор
 * срезает.
 *
 * Консервативно: перебазируются ТОЛЬКО листья, у которых блок подзапроса
 * начинается с собственной строки и закрывается на ПОСЛЕДНЕЙ строке листа
 * (баланс скобок, кавычки учитываются). Листья сложнее (И/ИЛИ-цепочка значения
 * с двумя подзапросами, хвост после скобки) сохраняют геометрию исходника.
 */
/**
 * Сплющивает в одну строку многострочные СПИСКИ ЗНАЧЕНИЙ оператора `В (\n a,\n b)`
 * внутри тела подзапроса (фаза 6.15.20). Находит строку, заканчивающуюся на ` В (`
 * или ` В(` (открытие списка), где за `(` НЕ следует подзапрос (ВЫБРАТЬ), собирает
 * последующие строки до закрытия скобок списка и склеивает их в одну строку с
 * пунктуационным сплющиванием (как flattenLeafText). Хвост после закрытия списка
 * (`)) КАК …` и т. п.) сохраняется на той же строке. Прочее не трогает.
 */
function flattenInlineValueLists(text: string): string {
  if (!text.includes('\n')) return text;
  const lines = text.split('\n');
  const out: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Открытие списка значений: строка кончается на `В (` / `В(` (вне строкового
    // литерала; кавычки в строке не учитываем — список значений их не содержит).
    const opensInline =
      /(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*\($/u.test(line) &&
      i + 1 < lines.length &&
      !/^[\t ]*ВЫБРАТЬ(?![\p{L}\p{N}_])/u.test(lines[i + 1]);
    // Разработчик отбил скобку списка на СЛЕДУЮЩУЮ строку: строка кончается оператором
    // `В`/`В ИЕРАРХИИ`, а список `(…)` открывается строкой ниже (`… В\n (a, b)`).
    // Конструктор сшивает `В (a, b)` обратно на одну строку (как и инлайн-список).
    const opensNextLine =
      /(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*$/u.test(line) &&
      i + 1 < lines.length &&
      /^[\t ]*\(/u.test(lines[i + 1]) &&
      !/^[\t ]*\(\s*ВЫБРАТЬ(?![\p{L}\p{N}_])/u.test(lines[i + 1]);
    const opensList = opensInline || opensNextLine;
    if (!opensList) { out.push(line); continue; }
    // Считаем баланс скобок начиная с этой строки, пока список не закроется.
    let depth = 0;
    let inStr = false;
    const buf: string[] = [];
    let j = i;
    let closed = false;
    for (; j < lines.length; j++) {
      buf.push(lines[j]);
      for (const ch of lines[j]) {
        if (ch === '"') { inStr = !inStr; continue; }
        if (inStr) continue;
        if (ch === '(') depth++;
        else if (ch === ')') { depth--; if (depth === 0) { closed = true; } }
      }
      if (closed) break;
    }
    if (!closed) { out.push(line); continue; }
    // Подзапрос внутри списка — не сплющиваем (страховка).
    if (buf.some(b => /(?:^|[^\p{L}\p{N}_])ВЫБРАТЬ(?![\p{L}\p{N}_])/u.test(b))) {
      out.push(line); continue;
    }
    // Сохраняем ведущий отступ первой строки, сплющиваем содержимое.
    const indent = (buf[0].match(/^\t*/u) ?? [''])[0];
    out.push(indent + flattenLeafText(buf.join('\n').replace(/^\t*/u, '')));
    i = j;
  }
  return out.join('\n');
}

export function reindentLeafSubquery(text: string, base: number): string {
  if (!text.includes('\n')) return text;
  // Многострочный СПИСОК ЗНАЧЕНИЙ оператора `В (\n a,\n b)` внутри тела подзапроса
  // конструктор печатает инлайн на одной строке (фаза 6.15.20, MCP). Списки
  // подзапроса (`В (ВЫБРАТЬ …)`) НЕ трогаем (после `(` идёт ВЫБРАТЬ).
  text = flattenInlineValueLists(text);
  if (!text.includes('\n')) return text;
  const lines = text.split('\n');
  // Склеенная открывающая скобка `… В (` в конце строки, когда `ВЫБРАТЬ` стоит на
  // СЛЕДУЮЩЕЙ строке (геометрия разработчика `В (\n\tВЫБРАТЬ …`). Конструктор 1С
  // переносит `(` на строку `ВЫБРАТЬ` (`… В` + `\n` + отступ + `(ВЫБРАТЬ …`).
  // Нормализуем перед перебазировкой: отделяем хвостовую `(` оператора `В`/
  // `В ИЕРАРХИИ` и приклеиваем к началу следующей строки. Срабатывает только если
  // отдельной строки `(ВЫБРАТЬ` ещё нет.
  if (!lines.some((l) => l.replace(/^[\t ]+/u, '').startsWith('(ВЫБРАТЬ'))) {
    for (let i = 0; i < lines.length - 1; i++) {
      if (!/(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*\($/u.test(lines[i])) continue;
      if (!lines[i + 1].replace(/^[\t ]+/u, '').startsWith('ВЫБРАТЬ')) continue;
      lines[i] = lines[i].replace(/\s*\($/u, '');
      lines[i + 1] = lines[i + 1].replace(/^([\t ]*)/u, '$1(');
      break;
    }
  }
  let start = -1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].replace(/^[\t ]+/u, '').startsWith('(ВЫБРАТЬ')) { start = i; break; }
  }
  if (start <= 0) return text;
  // ГОЛОВА перед строкой `(ВЫБРАТЬ` (`(поле1, поле2, …) В`) набрана разработчиком на
  // НЕСКОЛЬКИХ строках — конструктор 1С печатает весь список-кортеж операнда `В` на
  // ОДНОЙ строке (`(поле1, поле2, поле3) В`). Схлопываем строки 0..start-1 в одну,
  // сохраняя отступ строки 0 (корпус СборкаЗапасов/РасходнаяНакладная/ЗаказПоставщику).
  if (start > 1) {
    const lead = (lines[0].match(/^[\t ]*/u) ?? [''])[0];
    const body = lines.slice(0, start)
      .map((l) => l.replace(/^[\t ]+/u, '').replace(/[ \t]+$/u, ''))
      .filter((l) => l !== '')
      .join(' ')
      .replace(/[ \t]+/gu, ' ')
      .replace(/\(\s+/gu, '(')
      .replace(/\s+\)/gu, ')')
      .replace(/\s+,/gu, ',');
    // Схлопываем ТОЛЬКО чистый КОРТЕЖ-операнд `В`: сбалансированная пара скобок-списка,
    // за которой идёт ровно `В` (без булевых операторов/сравнений внутри). Иначе это
    // составное условие `(A = &X ИЛИ B В (…))`, чьи И/ИЛИ переносы трогать нельзя.
    if (/^\([^()=<>]*\)\s+В$/u.test(body) &&
      !/(?:^|[^\p{L}\p{N}_])(?:И|ИЛИ|НЕ|МЕЖДУ|ПОДОБНО|ССЫЛКА|ЕСТЬ)(?:[^\p{L}\p{N}_])/u.test(body)) {
      lines.splice(0, start, lead + body);
      start = 1;
    }
  }
  // Баланс скобок блока (вне строковых литералов) должен закрыться в конце листа.
  let depth = 0;
  let inStr = false;
  for (let i = start; i < lines.length; i++) {
    for (const ch of lines[i]) {
      if (ch === '"') inStr = !inStr;
      else if (!inStr && ch === '(') depth++;
      else if (!inStr && ch === ')') depth--;
    }
    if (depth <= 0 && i < lines.length - 1) return text;
  }
  if (depth > 0) return text;
  // Ведущие НЕ головы листа (включая после открывающих скобок): по +1 каждое.
  const neMatch = /^[\s(]*((?:НЕ\s+)+)/u.exec(lines[0]);
  const neCount = neMatch ? (neMatch[1].match(/НЕ/gu) ?? []).length : 0;
  const target = base + neCount;
  // Хвостовые пробелы строки перед подзапросом (`… В ` → `… В`).
  lines[start - 1] = lines[start - 1].replace(/[ \t]+$/u, '');
  // Геометрия отступа тела подзапроса в исходнике разработчика может быть набрана
  // ПРОБЕЛАМИ (или смесью таб+пробел) — тогда счёт ведущих ТАБОВ её не видит, и
  // простое до-набивание `delta` табов оставляет исходные пробелы как мусор
  // (`\t\t\t\t\t            (ВЫБРАТЬ`). Если в ведущем отступе тела есть пробелы —
  // нормализуем тело юнит-независимо: уровень строки вычисляем по ВИЗУАЛЬНОЙ ширине
  // её отступа относительно строки `(ВЫБРАТЬ` (таб=8, пробел=1), шаг — минимальный
  // положительный прирост в блоке, и переотрисовываем как `(target + level)` табов.
  // Для чисто-табного тела (current behaviour) ветка не срабатывает — байт-в-байт.
  const visWidth = (ws: string): number => {
    let w = 0;
    for (const ch of ws) w += ch === '\t' ? 8 : 1;
    return w;
  };
  const bodyHasSpaceIndent = lines
    .slice(start)
    .some((l) => l.trim() !== '' && / /u.test((l.match(/^[\t ]*/u) ?? [''])[0]));
  if (bodyHasSpaceIndent) {
    const headW = visWidth((lines[start].match(/^[\t ]*/u) ?? [''])[0]);
    // Минимальный положительный прирост ширины относительно головы — единица уровня.
    let step = Infinity;
    for (let i = start; i < lines.length; i++) {
      if (lines[i].trim() === '') continue;
      const d = visWidth((lines[i].match(/^[\t ]*/u) ?? [''])[0]) - headW;
      if (d > 0 && d < step) step = d;
    }
    if (!Number.isFinite(step)) step = 1;
    for (let i = start; i < lines.length; i++) {
      if (lines[i].trim() === '') continue;
      const ws = (lines[i].match(/^[\t ]*/u) ?? [''])[0];
      const extra = visWidth(ws) - headW;
      const level = extra > 0 ? Math.round(extra / step) : 0;
      lines[i] = TAB.repeat(target + level) + lines[i].slice(ws.length);
    }
  } else {
    const cur = (lines[start].match(/^\t*/u) ?? [''])[0].length;
    const delta = target - cur;
    if (delta !== 0) {
      for (let i = start; i < lines.length; i++) {
        // Пустые строки-разделители (вокруг `ОБЪЕДИНИТЬ ВСЕ`) НЕСУТ собственный значимый
        // отступ (член−1 у подзапроса-источника, член−2 у В-операнда с ведущим `В`).
        // Сдвигаем их на ту же `delta`, СОХРАНЯЯ относительную геометрию разработчика
        // (нулевой отступ обрабатываем отдельным проходом ниже — там геометрии нет).
        if (lines[i].trim() === '') {
          const haveB = (lines[i].match(/^\t*/u) ?? [''])[0].length;
          if (haveB > 0) lines[i] = TAB.repeat(Math.max(0, haveB + delta));
          continue;
        }
        if (delta > 0) {
          lines[i] = TAB.repeat(delta) + lines[i];
        } else {
          const have = (lines[i].match(/^\t*/u) ?? [''])[0].length;
          if (have < -delta) return text; // нечего срезать — геометрия нестандартная, не трогаем
          lines[i] = lines[i].slice(-delta);
        }
      }
    }
  }
  // Пустые строки-разделители, набранные разработчиком БЕЗ отступа (0 табов), своей
  // геометрии не несут — конструктор ставит их на ОДИН таб мельче ключевого слова
  // `ОБЪЕДИНИТЬ` (член−1). Переотрисовываем ТОЛЬКО такие нулевые разделители, соседние
  // со строкой `ОБЪЕДИНИТЬ` (ненулевые сохраняют относительную геометрию выше; фаза 6.16).
  const isUnionKw = (s: string): boolean => /^\t*ОБЪЕДИНИТЬ(?:\s+ВСЕ)?\s*$/u.test(s);
  for (let i = start; i < lines.length; i++) {
    if (lines[i] !== '') continue; // только строки БЕЗ отступа (ровно пустые)
    const prevKw = i > 0 && isUnionKw(lines[i - 1]);
    const nextKw = i + 1 < lines.length && isUnionKw(lines[i + 1]);
    if (!prevKw && !nextKw) continue;
    const kwLine = prevKw ? lines[i - 1] : lines[i + 1];
    const kwInd = (kwLine.match(/^\t*/u) ?? [''])[0].length;
    lines[i] = TAB.repeat(Math.max(0, kwInd - 1));
  }
  // Пустые строки ВНУТРИ тела подзапроса, набранные разработчиком ради читаемости
  // (напр. перед `УПОРЯДОЧИТЬ ПО` или между секциями), конструктор 1С УБИРАЕТ —
  // значимы лишь разделители вокруг `ОБЪЕДИНИТЬ` (их сохраняет ветка выше, MCP-проба
  // `В (ВЫБРАТЬ … ГДЕ …\n\n УПОРЯДОЧИТЬ ПО …)` → пустая строка исчезает). Удаляем
  // пустые строки тела (i > start), НЕ соседние с `ОБЪЕДИНИТЬ` (фаза 6.16).
  for (let i = lines.length - 1; i > start; i--) {
    if (lines[i].trim() !== '') continue;
    const prevKw = isUnionKw(lines[i - 1] ?? '');
    const nextKw = i + 1 < lines.length && isUnionKw(lines[i + 1]);
    if (prevKw || nextKw) continue;
    lines.splice(i, 1);
  }
  // Хвостовые пробелы СОДЕРЖАТЕЛЬНЫХ строк подзапроса конструктор срезает
  // (`ИЗ ` → `ИЗ`). Не трогаем: строки со строковым литералом (там пробел может быть
  // значимым) и пустые/только-пробельные строки-разделители (конструктор сохраняет их
  // отступ, напр. `\t\t` вокруг `ОБЪЕДИНИТЬ ВСЕ`).
  for (let i = start; i < lines.length; i++) {
    if (lines[i].trim() === '') continue;
    if (!lines[i].includes('"')) lines[i] = lines[i].replace(/[ \t]+$/u, '');
  }
  // Структурный отступ СОЕДИНЕНИЙ внутри тела подзапроса: разработчик нередко набирает
  // `ВНУТРЕННЕЕ СОЕДИНЕНИЕ`/`ПО` НА ОДНОМ уровне с источником (плоско), а конструктор 1С
  // отбивает присоединяемый источник и `ПО` на ОДИН таб ГЛУБЖЕ источника (source+1), а
  // условие `ПО` — ещё на +1. Равномерный сдвиг этого не делает. Поэтому, если строка
  // СОЕДИНЕНИЯ стоит ВРОВЕНЬ с предшествующим источником (после `ИЗ`), углубляем её и
  // относящиеся к ней `ПО`/конъюнкты на +1 (фаза 6.16). Узкий гейт: трогаем только
  // плоскую геометрию (join-отступ == source-отступ) — корректно набранную не трогаем.
  {
    const JOIN_RE = /^(\t*)(?:ВНУТРЕННЕЕ|ЛЕВОЕ(?:\s+ВНЕШНЕЕ)?|ПРАВОЕ(?:\s+ВНЕШНЕЕ)?|ПОЛНОЕ(?:\s+ВНЕШНЕЕ)?)\s+СОЕДИНЕНИЕ(?:[^\p{L}\p{N}_]|$)/u;
    const PO_RE = /^(\t*)ПО(?:[^\p{L}\p{N}_]|$)/u;
    const indOf = (s: string): number => (s.match(/^\t*/u) ?? [''])[0].length;
    let srcInd = -1; // отступ источника текущего блока ИЗ (строка сразу после `ИЗ`)
    let expectSource = false;
    let joinExtra = 0; // накопленный +1 для строк текущего соединения
    let poExtra = 0; // признак активного плоского `ПО` (его конъюнкты углубляем на +2)
    for (let i = start; i < lines.length; i++) {
      const l = lines[i];
      if (l.trim() === '') continue;
      if (/^\t*ИЗ\s*$/u.test(l)) { expectSource = true; joinExtra = 0; poExtra = 0; continue; }
      if (expectSource) { srcInd = indOf(l); expectSource = false; continue; }
      const jm = JOIN_RE.exec(l);
      if (jm && srcInd >= 0 && jm[1].length === srcInd) {
        // Плоское соединение: углубляем строку соединения на +1 (source+1).
        lines[i] = TAB + l;
        joinExtra = 1;
        poExtra = 0;
        continue;
      }
      const pm = PO_RE.exec(l);
      if (pm && joinExtra > 0 && pm[1].length === srcInd) {
        // `ПО` (и однострочное `ПО <условие>`) того же плоского соединения — на +1.
        lines[i] = TAB + l;
        poExtra = 1;
        continue;
      }
      // Конъюнкты-продолжения `И`/`ИЛИ` условия `ПО` (`ПО a = b\n\tИ c = d`): условие
      // конструктор отбивает на ПО+2 (само условие на ПО+1, его `И` — ещё на +1). При
      // плоском соединении разработчик ставит их на source+1; углубляем на +2.
      if (poExtra > 0 && /^\t*(?:И|ИЛИ)(?:[^\p{L}\p{N}_])/u.test(l) && indOf(l) <= srcInd + 1) {
        lines[i] = TAB + TAB + l;
        continue;
      }
      // Возврат к источнику/новой секции сбрасывает накопленное углубление.
      if (indOf(l) <= srcInd) { joinExtra = 0; poExtra = 0; }
    }
  }
  // Булев оператор `И`/`ИЛИ`, набранный разработчиком ОТДЕЛЬНОЙ строкой (`Поле = X\n\t\tИЛИ\n\t\t\tПоле = Y`):
  // конструктор 1С склеивает оператор с его операндом в ОДНУ строку (как renderBool —
  // `ИЛИ операнд`), а оператор-одиночку убирает. reindentLeafSubquery лишь равномерно
  // сдвигает геометрию разработчика и сам по себе этот неканон не разнёс бы. Узкий гейт:
  //   • строка тела подзапроса (i > start);
  //   • строка — РОВНО `\t*(И|ИЛИ)` (оператор без операнда);
  //   • следующая непустая строка строго ГЛУБЖЕ оператора (его операнд, набранный +1).
  // Склеенная строка наследует ОТСТУП операнда (оракул держит `ИЛИ операнд` на уровне
  // операнда, на +1 глубже строки операнда0). Прочие соседи (комментарии, скобки) не
  // трогаются. Фаза 6.16.
  for (let i = start + 1; i < lines.length - 1; i++) {
    const opM = /^(\t*)(И|ИЛИ)$/u.exec(lines[i]);
    if (!opM) continue;
    let j = i + 1;
    while (j < lines.length && lines[j].trim() === '') j++;
    if (j >= lines.length) continue;
    const opInd = opM[1].length;
    const operandInd = (lines[j].match(/^\t*/u) ?? [''])[0].length;
    if (operandInd <= opInd) continue;
    // Конъюнкт `И`, набранный отдельной строкой: оракул держит склеенный `И операнд` на
    // уровне ОПЕРАТОРА (= уровень предыдущего конъюнкта), без скобок (`a = b\n\tИ\n\t\tc = d`
    // → `a = b\n\tИ c = d`, MCP). `ИЛИ` остаётся на уровне ОПЕРАНДА (на +1, со скобками
    // выше) — прежнее поведение. Узкий гейт по оператору.
    const targetInd = opM[2] === 'И' ? opInd : operandInd;
    lines[j] = lines[j].replace(/^\t*/u, `${TAB.repeat(targetInd)}${opM[2]} `);
    lines.splice(i, 1);
    i--; // строка сдвинулась
  }
  // Скобочная группа `НЕ(…)`, набранная разработчиком МНОГОСТРОЧНО с ПЛОСКИМИ
  // продолжениями (`И НЕ(A = B` на отступе N, `И C = D)` — тоже на N): конструктор 1С
  // отбивает продолжения такой группы на ДВА таба ГЛУБЖЕ строки-открывателя `НЕ(`
  // (N+2), пока скобка группы не закроется (MCP-проба `ГДЕ … И НЕ(A\n\t\t…И B)` в
  // подзапросе-операнде → продолжение на openerInd+2). Равномерный сдвиг этого не делает.
  // Узкий гейт: строка открывает группу `НЕ(` со скобкой, остающейся ОТКРЫТОЙ к концу
  // строки, а продолжения — `И`/`ИЛИ` на отступе <= openerInd (плоская геометрия).
  // Фаза 6.16.
  {
    const indOf = (s: string): number => (s.match(/^\t*/u) ?? [''])[0].length;
    const balance = (s: string): number => {
      let d = 0, inStr = false;
      for (const ch of s) {
        if (ch === '"') inStr = !inStr;
        else if (!inStr && ch === '(') d++;
        else if (!inStr && ch === ')') d--;
      }
      return d;
    };
    // Открывает ли строка группу `НЕ(` (слово НЕ вплотную/через пробел перед `(`),
    // и баланс скобок ПОСЛЕ строки >= 1 (группа продолжается ниже).
    const opensNotGroup = /(?:^|[^\p{L}\p{N}_])НЕ\s*\(/u;
    for (let i = start; i < lines.length; i++) {
      if (!opensNotGroup.test(lines[i])) continue;
      if (balance(lines[i]) < 1) continue;
      const openerInd = indOf(lines[i]);
      let depth = balance(lines[i]);
      let j = i + 1;
      // Все продолжения группы должны быть плоскими (<= openerInd) — иначе геометрия
      // уже задана разработчиком, не трогаем (отступ от строки-открывателя break).
      const span: number[] = [];
      let flat = true;
      for (; j < lines.length && depth > 0; j++) {
        if (lines[j].trim() === '') continue;
        if (indOf(lines[j]) > openerInd) { flat = false; break; }
        if (/^\t*(?:И|ИЛИ)(?:[^\p{L}\p{N}_])/u.test(lines[j])) span.push(j);
        else { flat = false; break; }
        depth += balance(lines[j]);
      }
      if (flat && depth <= 0 && span.length > 0) {
        for (const k of span) {
          lines[k] = TAB.repeat(openerInd + 2) + lines[k].replace(/^\t*/u, '');
        }
        i = j - 1;
      }
    }
  }
  // Внутри подзапроса-операнда условия `ПО` соединения печатается на отдельной
  // строке, а условие — НИЖЕ с отступом +1 (фаза 6.15.14, MCP). В сыром тексте
  // подзапроса (`В (ВЫБРАТЬ … СОЕДИНЕНИЕ … ПО <условие>)`) перекладываем строку
  // `<таб>ПО <условие>` в две: `<таб>ПО` + `<таб+1><условие>`. Продолжения `И`
  // конъюнктов уже стоят на нужном отступе в исходнике — их не трогаем.
  const split: string[] = [];
  for (const l of lines) {
    const m = /^(\t*)ПО\s+(\S.*)$/u.exec(l);
    if (m) {
      split.push(`${m[1]}ПО`);
      split.push(`${m[1]}${TAB}${m[2]}`);
    } else {
      split.push(l);
    }
  }
  // Закрывающая скобка В-подзапроса на ОТДЕЛЬНОЙ последней строке (`…\n\t)`):
  // конструктор приклеивает её к последней содержательной строке тела
  // (`…&КлючВарианта)`), а псевдоним поля добавляет вызывающий (фаза 6.15.20, MCP).
  // Срабатывает только когда последняя строка — ровно закрывающие скобки.
  const last = split.length - 1;
  if (last > start && /^\t*\)+$/u.test(split[last])) {
    const close = split[last].trim();
    split.splice(last, 1);
    split[split.length - 1] = split[split.length - 1].replace(/[ \t]+$/u, '') + close;
  }
  return split.join('\n');
}

/**
 * Является ли значение ветки CASE «ОДИНОЧНЫМ верхнеуровневым ВЫБОР» — то есть содержит
 * РОВНО ОДИН ВЫБОР, открытый бинарным оператором на ВЕРХНЕМ уровне скобок значения
 * (`Расчеты.Сумма * ВЫБОР … КОНЕЦ`: строка оканчивается словом ВЫБОР, баланс скобок
 * ПЕРЕД ним равен 0). Более одного ВЫБОР (арифметика нескольких CASE, вложенный CASE
 * в значении ветки) или ВЫБОР внутри скобок вызова (`ВЫРАЗИТЬ(ЕСТЬNULL(ВЫБОР…`,
 * `РАЗНОСТЬДАТ(…, ВЫБОР…`) — НЕ наш случай (его база другая, считается иначе). Подзапрос
 * (`(ВЫБРАТЬ …)`) тоже исключаем. Узкий гейт перед reindentLeafCase (фаза 6.16.56).
 */
function isSingleTopLevelCaseValue(text: string): boolean {
  if (!text.includes('\n')) return false;
  if (/(?:^|[^\p{L}\p{N}_])ВЫБРАТЬ(?:[^\p{L}\p{N}_]|$)/iu.test(text)) return false;
  // Ровно один ВЫБОР во всём значении.
  const vyborCount = (text.match(/(?:^|[^\p{L}\p{N}_])ВЫБОР(?:[^\p{L}\p{N}_]|$)/giu) ?? []).length;
  if (vyborCount !== 1) return false;
  const lines = text.split('\n');
  // Позиция (индекс) начала слова ВЫБОР, если строка им оканчивается (на границе слова).
  const trailingVyborPos = (line: string): number => {
    const m = /(^|[^\p{L}\p{N}_])(ВЫБОР)\s*$/u.exec(line);
    if (!m) return -1;
    return m.index + m[1].length; // начало «ВЫБОР»
  };
  let depth = 0;
  let inStr = false;
  for (const line of lines) {
    // Открывающий ВЫБОР конструктор всегда ставит В КОНЕЦ строки. Проверяем: строка
    // оканчивается словом ВЫБОР И баланс скобок ИМЕННО ПЕРЕД этим словом равен 0
    // (а не просто к началу строки — `ВЫРАЗИТЬ(A / ВЫБОР` открывает скобку до ВЫБОР,
    // глубина там 1, и под гейт не подпадает).
    const viPos = trailingVyborPos(line);
    let d = depth;
    let s: boolean = inStr;
    for (let c = 0; c < line.length; c++) {
      if (c === viPos && !s && d === 0) return true;
      const ch = line[c];
      if (ch === '"') { s = !s; continue; }
      if (s) continue;
      if (ch === '(') d++;
      else if (ch === ')') d--;
    }
    depth = d;
    inStr = s;
  }
  return false;
}

/**
 * Значение ветки ТОГДА/ИНАЧЕ, ОТКРЫВАЮЩЕЕСЯ верхнеуровневым ВЫБОР (первая непустая
 * строка — голое слово `ВЫБОР` без префикса/скобок, на глубине скобок 0). В отличие от
 * isSingleTopLevelCaseValue допускает НЕСКОЛЬКО ВЫБОР (CASE-арифметика `ВЫБОР…КОНЕЦ -
 * ВЫБОР…КОНЕЦ`). Подзапрос (ВЫБРАТЬ) исключаем — его раскладывает reindentLeafSubquery.
 * reindentLeafCase ниже сам бракует нестандартную геометрию (возврат входа).
 */
function opensWithTopLevelVybor(text: string): boolean {
  if (!text.includes('\n')) return false;
  if (/(?:^|[^\p{L}\p{N}_])ВЫБРАТЬ(?:[^\p{L}\p{N}_]|$)/iu.test(text)) return false;
  const lines = text.split('\n');
  const first = lines.find((l) => l.trim() !== '');
  // Первая структурная строка ОКАНЧИВАЕТСЯ словом ВЫБОР — это открыватель CASE
  // (голый `ВЫБОР` для CASE-арифметики `ВЫБОР…КОНЕЦ - ВЫБОР…КОНЕЦ`, либо хвост
  // `… ВЫРАЗИТЬ(… / ВЫБОР` для CASE внутри вызова без селектора). reindentLeafCase
  // ниже сам отбракует нестандартную геометрию (несбалансированные скобки и т. п.).
  if (first === undefined || !/(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u.test(first)) return false;
  // Исключаем СМЕШАННУЮ скобочную ситуацию в строке-ПЕРЕОТКРЫТИИ `КОНЕЦ … ВЫБОР`, где
  // число открытых ВЫЗОВ-скобок не равно чистому балансу скобок (есть скобка-ГРУППИРОВКА
  // вокруг переоткрываемого ВЫБОР: `КОНЕЦ + (ВЫРАЗИТЬ(ЕСТЬNULL(ВЫБОР`). В таком листе
  // funcParenDepth-семантика и чистый баланс расходятся, и канон неоднозначен — отдаём
  // лист прежнему пути (reindentLeafSubquery), сохраняя байт-в-байт (корпус
  // ДатыЗапретаИзменения). Простые переоткрытия (`КОНЕЦ - ВЫБОР`, баланс=вызовы) — ок.
  const onlyParens = (s: string): string => {
    let inStr = false, out = '';
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inStr = !inStr; out += '"'; continue; }
      out += ch;
    }
    return out;
  };
  // Число скобок-ГРУППИРОВКИ (не вызов-функции), ОТКРЫТЫХ в `s` и оставшихся открытыми
  // к концу. Закрывающие `)` (закрытие скобки, открытой ДО `s`) НЕ дисквалифицируют.
  const openGroupParensOf = (s: string): number => {
    const st: boolean[] = []; // true — вызов-скобка, false — группировка
    let inStr = false, prev = '';
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inStr = !inStr; prev = ch; continue; }
      if (inStr) continue;
      if (ch === '(') { st.push(/[\p{L}\p{N}_]/u.test(prev)); prev = ch; continue; }
      if (ch === ')') { st.pop(); prev = ch; continue; }
      if (ch !== ' ' && ch !== '\t') prev = ch;
    }
    return st.filter((isCall) => !isCall).length;
  };
  for (const l of lines) {
    if (!/^[\t ]*КОНЕЦ(?![\p{L}\p{N}_])/u.test(l)) continue;
    if (!/(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u.test(l)) continue;
    const head = onlyParens(l.replace(/(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u, '$1').replace(/^[\t ]*/u, ''));
    // Скобка-ГРУППИРОВКА, ОХВАТЫВАЮЩАЯ переоткрываемый ВЫБОР (`КОНЕЦ + (ВЫРАЗИТЬ(ЕСТЬNULL(
    // ВЫБОР`): funcParenDepth-семантика и чистый баланс расходятся, канон неоднозначен —
    // отдаём лист прежнему пути (корпус ДатыЗапретаИзменения). Закрытие предыдущей группы
    // (`КОНЕЦ) * … * ВЫБОР`) НЕ дисквалифицирует (корпус КорректировкаПоступления).
    if (openGroupParensOf(head) > 0) return false;
  }
  return true;
}

/**
 * Значение ветки ТОГДА/ИНАЧЕ, в котором единственный ВЫБОР открыт ВНУТРИ ВЫЗОВА
 * функции (`ВЫРАЗИТЬ(A * B / (C * ВЫБОР … КОНЕЦ) КАК Тип)`), а АРИФМЕТИЧЕСКАЯ ГОЛОВА
 * перед этим ВЫБОР разнесена разработчиком по НЕСКОЛЬКИМ физическим строкам
 * (`ВЫРАЗИТЬ(A * B\n / (C * ВЫБОР`). Конструктор 1С СКЛЕИВАЕТ голову в одну строку
 * (как и любую арифметику) и раскладывает вложенный CASE по funcParenDepth-глубине —
 * ровно то, что делает reindentLeafCase(.., funcParenDepth=true). isSingleTopLevelCaseValue
 * этот лист не ловит (его ВЫБОР на глубине скобок > 0), opensWithTopLevelVybor — тоже
 * (первая структурная строка НЕ оканчивается словом ВЫБОР, она оборвана арифметикой).
 *
 * Узкий гейт (фаза 6.16.104): ровно один ВЫБОР; нет подзапроса; строка-открыватель
 * (оканчивается словом ВЫБОР) стоит на глубине скобок > 0; голова до этой строки —
 * МНОГОСТРОЧНАЯ (есть что склеивать; одностроковый открыватель уже идёт штатным путём);
 * до строки-открывателя НЕ встречается закрывающая `)` (чистая вложенность вызова).
 */
function opensWithVyborInCall(text: string): boolean {
  if (!text.includes('\n')) return false;
  if (/(?:^|[^\p{L}\p{N}_])ВЫБРАТЬ(?:[^\p{L}\p{N}_]|$)/iu.test(text)) return false;
  const vyborCount = (text.match(/(?:^|[^\p{L}\p{N}_])ВЫБОР(?:[^\p{L}\p{N}_]|$)/giu) ?? []).length;
  if (vyborCount !== 1) return false;
  const lines = text.split('\n');
  const trailingVyborPos = (line: string): number => {
    const m = /(^|[^\p{L}\p{N}_])(ВЫБОР)\s*$/u.exec(line);
    return m ? m.index + m[1].length : -1;
  };
  let depth = 0;
  let inStr = false;
  let sawClose = false;
  for (let li = 0; li < lines.length; li++) {
    const line = lines[li];
    const viPos = trailingVyborPos(line);
    let d = depth;
    let s: boolean = inStr;
    for (let c = 0; c < line.length; c++) {
      // Строка-открыватель CASE: оканчивается словом ВЫБОР на глубине вызова > 0,
      // ей предшествует МНОГОСТРОЧНАЯ голова, и до неё не было закрывающих скобок.
      if (c === viPos && !s) return d > 0 && li > 0 && !sawClose;
      const ch = line[c];
      if (ch === '"') { s = !s; continue; }
      if (s) continue;
      if (ch === '(') d++;
      else if (ch === ')') { d--; if (d < 0) return false; sawClose = true; }
    }
    depth = d;
    inStr = s;
  }
  return false;
}

/**
 * Канонический отступ блока ВЫБОР, ВЛОЖЕННОГО внутрь листа (фаза 6.15.9b, MCP-пробы).
 * Конструктор 1С переотрисовывает ВЫБОР/КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ даже когда ВЫБОР стоит
 * внутри вызова функции (`СУММА(ВЫБОР … КОНЕЦ)`), арифметики (`… - ВЫБОР … КОНЕЦ`) или
 * условия соединения (`ПО (ВЫБОР … КОНЕЦ)`) — то есть там, где парсер выражений
 * поглощает весь блок одним листом и не строит узел case. Раскладка (проба
 * `СУММА(ВЫБОР …)`): КОНЕЦ = E, КОГДА = E+1, продолжения условия (`И`/`ИЛИ`) = E+3
 * (whenInd+2), ТОГДА = E+2, ИНАЧЕ = E+1, где E = `base` + число НЕзакрытых скобок,
 * стоящих между началом листа и словом ВЫБОР. Вложенный ВЫБОР после ТОГДА/ИНАЧЕ
 * получает свой E = (отступ ТОГДА/ИНАЧЕ) + 1.
 *
 * Реализация — построчная переустановка ведущих табов СТРУКТУРНЫХ строк (тех, что
 * начинаются ключевым словом ВЫБОР/КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ/И/ИЛИ); прочее содержимое
 * (тексты значений, хвосты) сохраняется побайтно. Полный ре-парс не используем —
 * он терял бы дословный текст листьев. Консервативно: при любой неожиданной
 * геометрии (значение на нескольких строках, рассинхрон стека ВЫБОР/КОНЕЦ,
 * подзапрос внутри) функция возвращает исходный текст без изменений.
 */
/**
 * Предразбиение ИНЛАЙН-CASE на структурные строки (фаза 6.16.71). Конструктор 1С
 * раскладывает КАЖДЫЙ `ВЫБОР … КОНЕЦ` по своим строкам, даже когда разработчик
 * записал весь CASE в ОДНУ физическую строку (`МАКСИМУМ(ВЫБОР КОГДА A И B ТОГДА X
 * ИНАЧЕ Y КОНЕЦ)`), или склеил `КОГДА <условие> ТОГДА <значение>` в одну строку.
 * reindentLeafCase сам по себе бросает такой лист (нет `\n` / ТОГДА приклеен к
 * КОГДА), поэтому ПЕРЕД ним вставляем переводы строки перед каждым верхнеуровневым
 * (на глубине самого CASE) КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ и перед продолжением условия
 * И/ИЛИ. Дальше штатная геометрия reindentLeafCase расставит отступы.
 *
 * Узкий гейт. Работает по токенам (строковые литералы `"…"`/`'…'` лексер выдаёт
 * одним токеном — слова внутри них не трогаем). Возврат входа БЕЗ изменений, если:
 *   - текст не токенизируется;
 *   - есть подзапрос (ВЫБРАТЬ) — его раскладывает reindentLeafSubquery;
 *   - у какого-либо ВЫБОР есть СЕЛЕКТОР (`ВЫБОР <выражение> КОГДА`) — селекторный
 *     CASE раскладывает reflowLeafSelectorCase, не наш путь.
 * И/ИЛИ разбиваем ТОЛЬКО внутри условия (между КОГДА и его ТОГДА): в значении ветки
 * ТОГДА/ИНАЧЕ верхнеуровневые И/ИЛИ — это редкая геометрия продолжения значения,
 * которую reindentLeafCase обрабатывает отдельно и которой нет в каноне; их не трогаем.
 */
export function splitInlineLeafCase(text: string): string {
  if (!text.includes('ВЫБОР') && !/ВЫБОР/iu.test(text)) return text;
  let toks: Token[];
  try {
    toks = tokenize(text);
  } catch {
    return text;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  const isW = (t: Token, w: string): boolean =>
    (t.type === 'keyword' || t.type === 'ident') && t.value.toUpperCase() === w;
  if (sig.some((t) => isW(t, 'ВЫБРАТЬ'))) return text;
  if (!sig.some((t) => isW(t, 'ВЫБОР'))) return text;
  // Глубина скобок ПЕРЕД каждым токеном.
  const depthBefore: number[] = [];
  let pd = 0;
  for (const t of sig) {
    depthBefore.push(pd);
    if (t.type === 'punct' && t.value === '(') pd++;
    else if (t.type === 'punct' && t.value === ')') pd--;
  }
  // Селекторный ВЫБОР (`ВЫБОР <не-КОГДА> …`) — не наша зона, отдаём reflowLeafSelectorCase.
  for (let k = 0; k < sig.length; k++) {
    if (isW(sig[k], 'ВЫБОР')) {
      const nx = sig[k + 1];
      if (!nx || !isW(nx, 'КОГДА')) return text;
    }
  }
  // Предпроход: условие КОГДА, ЦЕЛИКОМ обёрнутое в ОДНУ скобочную пару (`КОГДА (НЕ A И НЕ
  // B) ТОГДА …`), конструктор 1С печатает БЕЗ этих скобок (границы задаёт КОГДА…ТОГДА —
  // зеркало структурного renderWhenCondition, где верхняя группа не оборачивается). Снимаем
  // пару, чтобы её булевы операторы стали верхнеуровневыми конъюнктами условия (их разнесёт
  // основной цикл ниже, как обычные `И`/`ИЛИ` на уровне CASE). Узкий гейт: первый токен
  // условия — `(`, его пара — последний токен перед ТОГДА того же CASE, между ними есть
  // верхнеуровневый (относительно этой пары) булев `И`/`ИЛИ` (без него скобку снимет
  // stripRedundantCaseClauseParens на строке КОГДА — здесь не дублируем). Выполняется ДО
  // основного цикла; при срабатывании текст перетокенизируется (рекурсивный вызов).
  {
    const caseDepth: number[] = [];
    const dropPos: number[] = [];
    for (let k = 0; k < sig.length; k++) {
      const t = sig[k];
      if (isW(t, 'ВЫБОР')) { caseDepth.push(depthBefore[k]); continue; }
      const top = caseDepth[caseDepth.length - 1];
      if (top === undefined) continue;
      if (isW(t, 'КОНЕЦ') && depthBefore[k] === top) { caseDepth.pop(); continue; }
      if (!isW(t, 'КОГДА') || depthBefore[k] !== top) continue;
      // Первый токен условия — `(` на уровне top.
      const open = sig[k + 1];
      if (!open || !(open.type === 'punct' && open.value === '(') || depthBefore[k + 1] !== top) continue;
      // Идём до ТОГДА того же CASE; пара `(` должна закрыться РОВНО перед ним.
      let j = k + 2;
      let closeIdx = -1;
      let hasTopBool = false;
      for (; j < sig.length; j++) {
        const d = depthBefore[j];
        if (d <= top) break; // вышли из открытой пары (её `)` уже учтён в depthBefore)
        if (d === top + 1 && (isW(sig[j], 'И') || isW(sig[j], 'ИЛИ'))) hasTopBool = true;
      }
      // sig[j] — первый токен на глубине <= top после пары: это её `)` уже закрыт, значит
      // closeIdx = j-1 (последний токен внутри/закрывающая `)`); требуем, чтобы это была `)`
      // и следующий значимый токен — ТОГДА того же CASE.
      const closeTok = sig[j - 1];
      if (!closeTok || !(closeTok.type === 'punct' && closeTok.value === ')')) continue;
      const next = sig[j];
      if (!next || !isW(next, 'ТОГДА') || depthBefore[j] !== top) continue;
      if (!hasTopBool) continue;
      closeIdx = j - 1;
      dropPos.push(open.pos, closeTok.pos);
      void closeIdx;
    }
    if (dropPos.length > 0) {
      const drop = new Set(dropPos);
      let rebuilt = '';
      for (let p = 0; p < text.length; p++) if (!drop.has(p)) rebuilt += text[p];
      // Перетокенизируем и повторяем (теперь скобки сняты, операторы — верхнеуровневые).
      return splitInlineLeafCase(rebuilt);
    }
  }
  // Стек глубин CASE: глубина скобок на уровне открывающего ВЫБОР. Структурную строку
  // начинаем перед КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ ТЕКУЩЕГО CASE (на его скобочной глубине) и
  // перед И/ИЛИ-продолжением условия (между КОГДА и ТОГДА того же CASE).
  const caseStack: number[] = [];
  // Внутри условия КОГДА текущего (верхнего) CASE? Тогда И/ИЛИ на той же глубине —
  // продолжение условия и подлежит сплиту.
  let inCondition = false;
  // Сколько `И` принадлежат открытым `МЕЖДУ a И b` — их НЕ переносим (диапазонное И,
  // не булев конъюнкт). Без этого `КОГДА X МЕЖДУ &A И &B` ошибочно рвался на `И &B`.
  let betweenPending = 0;
  // Стек «вида» открытых скобок: true — ГРУППИРУЮЩАЯ (`… И (X ИЛИ Y)`), её
  // верхнеуровневые булевы операторы — часть условия и подлежат сплиту; false — скобка
  // ВЫЗОВА-функции (`ЗНАЧЕНИЕ(…)`, `ВЫРАЗИТЬ(…)`) или иной не-булев контекст, внутрь не
  // лезем. Группирующей считаем `(`, чей левый сосед НЕ идентификатор/слово-функция
  // (т.е. оператор/`(`/`И`/`ИЛИ`/`НЕ`/`КОГДА`/начало).
  const parenKind: boolean[] = [];
  const breakBefore = new Set<number>();
  const gluedToPrevAt = (k: number): boolean => {
    const p = sig[k - 1];
    if (!p) return false;
    const pEnd = p.pos + p.text.length;
    return !text.slice(pEnd, sig[k].pos).includes('\n');
  };
  for (let k = 0; k < sig.length; k++) {
    const t = sig[k];
    const dep = depthBefore[k];
    if (t.type === 'punct' && t.value === '(') {
      const prev = sig[k - 1];
      const isCallOpen = !!prev && (prev.type === 'ident' || (prev.type === 'keyword' && !isW(prev, 'И') && !isW(prev, 'ИЛИ') && !isW(prev, 'НЕ') && !isW(prev, 'КОГДА') && !isW(prev, 'МЕЖДУ')));
      parenKind.push(!isCallOpen);
    } else if (t.type === 'punct' && t.value === ')') {
      parenKind.pop();
    }
    if (isW(t, 'ВЫБОР')) {
      caseStack.push(dep);
      inCondition = false;
      continue;
    }
    const top = caseStack[caseStack.length - 1];
    if (top === undefined) continue;
    // `МЕЖДУ` отслеживаем ВНУТРИ условия на ЛЮБОЙ глубине (`dep >= top`): его `И` —
    // диапазонный, не булев разделитель, и его НЕ переносим ни на верхнем уровне, ни
    // внутри группы `(X МЕЖДУ a И b)`. Считаем ДО обработчиков И/ИЛИ.
    if (inCondition && dep >= top && isW(t, 'МЕЖДУ')) { betweenPending++; continue; }
    // Операнд `ИЛИ`/`И` ровно на ОДИН уровень глубже текущего CASE (`dep === top+1`),
    // принадлежащий ГРУППИРУЮЩЕЙ скобке условия КОГДА (`И (X ИЛИ Y)`): конструктор 1С
    // тоже разносит его по строкам (оракул `И (X\n\t\tИЛИ Y)`). Узкий гейт: мы внутри
    // условия, ведущая скобка — группирующая (parenKind top == true), оператор склеен с
    // предыдущим и это не диапазонное `И` (`МЕЖДУ a И b` — betweenPending>0).
    if (
      inCondition &&
      dep === top + 1 &&
      parenKind[parenKind.length - 1] === true &&
      (isW(t, 'И') || isW(t, 'ИЛИ'))
    ) {
      // Диапазонное `И` из `МЕЖДУ a И b` — не разрываем.
      if (isW(t, 'И') && betweenPending > 0) { betweenPending--; continue; }
      if (k > 0 && gluedToPrevAt(k)) breakBefore.add(k);
      continue;
    }
    if (dep !== top) continue; // не на уровне текущего CASE — внутренняя группа/вложение
    // Перенос ставим ТОЛЬКО когда токен СКЛЕЕН с предыдущим в одну физическую строку
    // (в зазоре нет `\n`): инлайн-CASE мы разбиваем, а уже разложенные построчно
    // структурные строки НЕ трогаем — иначе сорвём их ведущий отступ (фаза 6.16.71).
    const gluedToPrev = (): boolean => gluedToPrevAt(k);
    if (isW(t, 'КОГДА')) {
      if (k > 0 && gluedToPrev()) breakBefore.add(k);
      inCondition = true;
    } else if (isW(t, 'ТОГДА')) {
      if (k > 0 && gluedToPrev()) breakBefore.add(k);
      inCondition = false;
    } else if (isW(t, 'ИНАЧЕ')) {
      if (k > 0 && gluedToPrev()) breakBefore.add(k);
      inCondition = false;
    } else if (isW(t, 'КОНЕЦ')) {
      if (k > 0 && gluedToPrev()) breakBefore.add(k);
      caseStack.pop();
      inCondition = false;
    } else if (inCondition && (isW(t, 'И') || isW(t, 'ИЛИ'))) {
      // `И` диапазона `МЕЖДУ a И b` — не булев разделитель условия, не переносим.
      if (isW(t, 'И') && betweenPending > 0) { betweenPending--; continue; }
      if (k > 0 && gluedToPrev()) breakBefore.add(k);
    }
  }
  if (breakBefore.size === 0) return text;
  // Сборка: вставляем `\n` перед позицией каждого помеченного токена. Между токенами
  // сохраняем исходный текст листа дословно (срезы по pos), правит уже reindentLeafCase.
  let out = '';
  let prev = 0;
  for (let k = 0; k < sig.length; k++) {
    if (breakBefore.has(k)) {
      out += text.slice(prev, sig[k].pos).replace(/\s+$/u, '') + '\n';
      prev = sig[k].pos;
    }
  }
  out += text.slice(prev);
  return out;
}

/**
 * Снимает ИЗБЫТОЧНУЮ группирующую пару скобок, обёрнутую ровно вокруг ОДНОГО
 * вызова-функции (`ЕСТЬNULL((СУММА(ВЫБОР…)) - (СУММА(ВЫБОР…)), 0)` →
 * `ЕСТЬNULL(СУММА(ВЫБОР…) - СУММА(ВЫБОР…), 0)`) — конструктор 1С такую обёртку
 * убирает (вызов функции атомарен, скобки приоритета не несут), и делает это даже
 * для МНОГОСТРОЧНОГО листа, где stripRedundantLeafParens (однострочный) не работает.
 *
 * Пара `( ИДЕНТ ( … ) )` снимается ТОЛЬКО когда:
 *   - левый сосед открывающей скобки НЕ открывает вызов (isCallOpenContext) — т.е.
 *     это группировка, а не аргумент-скобка самой функции (`ВНЕШ(ВНУТР(x))` не трогаем);
 *   - сразу за `(` идёт идентификатор/слово-функция, затем `(`, и закрытие этого
 *     внутреннего вызова приходится РОВНО на токен перед внешним `)` (т.е. содержимое
 *     внешней пары — единственный вызов и ничего больше).
 * Переводы строк сохраняются (заменяем только символы скобок пробелом и подчищаем
 * прилегающие пробелы, не трогая `\n`). Фаза 6.16.76, MCP-проба оракула.
 */
export function stripRedundantCallWrapParens(text: string): string {
  if (!text.includes('(')) return text;
  let toks: Token[];
  try {
    toks = tokenize(text);
  } catch {
    return text;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  const match = new Map<number, number>();
  const stack: number[] = [];
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    if (t.type === 'punct' && t.value === '(') stack.push(i);
    else if (t.type === 'punct' && t.value === ')') {
      const o = stack.pop();
      if (o === undefined) return text;
      match.set(o, i);
    }
  }
  if (stack.length) return text;

  const isOpen = (t: Token | undefined): boolean => !!t && t.type === 'punct' && t.value === '(';
  const drop = new Set<number>();
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    if (!(t.type === 'punct' && t.value === '(')) continue;
    if (drop.has(i)) continue;
    const close = match.get(i)!;
    const prev = i > 0 ? sig[i - 1] : undefined;
    const nx = close + 1 < sig.length ? sig[close + 1] : undefined;
    // Левый сосед открывает вызов (`func(`) — это аргумент-скобка функции, не группировка.
    if (isCallOpenContext(prev)) continue;
    // Сосед-сравнение/предикат — оракул скобки вокруг ОПЕРАНДА сравнения СОХРАНЯЕТ
    // (`(ВЫРАЗИТЬ(…)) = &П`, `Сумма < (ВЫРАЗИТЬ(…))`). Снимаем лишь в арифм./арг-контексте.
    const isCmpOrPred = (t: Token | undefined): boolean =>
      !!t && ((t.type === 'punct' && COMPARISON_PUNCT_SET.has(t.value)) ||
        ((t.type === 'keyword' || t.type === 'ident') && PRED_NEIGHBOR_WORDS.has(t.value.toUpperCase())));
    if (isCmpOrPred(prev) || isCmpOrPred(nx)) continue;
    // Содержимое: вызов АГРЕГАТА (СУММА/КОЛИЧЕСТВО/…) + `(` … `)`, и закрытие == close-1.
    // Оракул снимает лишнюю обёртку лишь вокруг агрегата; вокруг ВЫРАЗИТЬ/др. — СОХРАНЯЕТ
    // (`ЕСТЬNULL((ВЫРАЗИТЬ(…))`, `-(ВЫРАЗИТЬ(…))`, `(ВЫРАЗИТЬ(…)) - ВЫБОР` остаются).
    const a = sig[i + 1];
    const b = sig[i + 2];
    if (!a) continue;
    if (!isOpen(b)) continue;
    const callClose = match.get(i + 2);
    if (callClose === undefined || callClose !== close - 1) continue;
    const isAgg = AGGREGATE_WORDS.has(a.value.toUpperCase());
    // Агрегат — снимаем обёртку в любом не-сравнительном контексте (прежнее правило).
    // Прочий вызов-функция (ЕСТЬNULL/ВЫРАЗИТЬ/…) — снимаем ТОЛЬКО когда пара охватывает
    // ВСЁ выражение целиком (ни слева, ни справа соседей): `(ЕСТЬNULL(…)) КАК Алиас` →
    // `ЕСТЬNULL(…)`. Внутри арифметики/аргумента (`(ВЫРАЗИТЬ(…)) - ВЫБОР`) обёртку
    // оракул СОХРАНЯЕТ, поэтому там не трогаем (фаза 6.16.77, MCP).
    const isCallWord =
      (a.type === 'ident' || a.type === 'keyword') &&
      !(PRED_NEIGHBOR_WORDS.has(a.value.toUpperCase()));
    if (!isAgg) {
      if (!isCallWord) continue;
      if (prev !== undefined || nx !== undefined) continue;
    }
    drop.add(i);
    drop.add(close);
  }
  if (!drop.size) return text;

  const positions: number[] = [];
  for (const idx of drop) positions.push(sig[idx].pos);
  positions.sort((a, b) => b - a);
  let out = text;
  for (const p of positions) {
    out = out.slice(0, p) + ' ' + out.slice(p + 1);
  }
  // Подчистка прилегающих к снятым скобкам пробелов — только горизонтальных (не \n).
  // Снятая ВЕДУЩАЯ/ХВОСТОВАЯ скобка целиком-охватывающей пары оставляет пробел на
  // краю выражения — убираем его (`(ЕСТЬNULL(…))` → `ЕСТЬNULL(…)`, без ведущего ` `).
  return out
    .replace(/\( +/g, '(')
    .replace(/ +\)/g, ')')
    .replace(/^ +/, '')
    .replace(/ +$/, '');
}

/**
 * Снимает обёртку `(…)`, охватывающую ВСЁ многострочное условие КОГДА (фаза 6.16.78).
 * Для каждой строки `КОГДА (…`, чья ведущая `(` (сразу после слова КОГДА) парна
 * закрывающей `)` в КОНЦЕ последней строки-продолжения условия (перед ТОГДА/КОНЕЦ/
 * КОГДА/ИНАЧЕ), и внутри есть верхнеуровневый булев И/ИЛИ — убирает обе скобки.
 * Мутирует массив `lines` на месте. Однострочные условия не трогает (их снимает
 * stripClause / stripRedundantCaseClauseParens).
 */
function stripMultilineWhenWrap(lines: string[]): void {
  const fw = (s: string): string => {
    const m = /^[\t ]*([\p{L}]+)/u.exec(s);
    return m ? m[1].toUpperCase() : '';
  };
  const parenDelta = (s: string): number => {
    let d = 0, inS = false;
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (ch === '(') d++;
      else if (ch === ')') d--;
    }
    return d;
  };
  for (let i = 0; i < lines.length; i++) {
    if (fw(lines[i]) !== 'КОГДА') continue;
    // Строка вида `КОГДА (<тело…>` — ведущая `(` сразу после КОГДА, и она НЕ
    // закрывается на этой же строке (delta>0). Однострочные обёртки не наш случай.
    const m = /^([\t ]*КОГДА[\t ]+)\((.*)$/u.exec(lines[i]);
    if (!m) continue;
    const headDelta = parenDelta('(' + m[2]);
    if (headDelta < 1) continue; // ведущая `(` закрывается на этой строке
    // Идём по продолжениям, отслеживая глубину. Закрытие ведущей `(` (глубина → 0)
    // должно прийти РОВНО на последнем символе строки, а следующая значимая строка —
    // структурное слово конца условия (ТОГДА/КОНЕЦ/КОГДА/ИНАЧЕ). Иначе обёртка не
    // охватывает всё условие — не трогаем.
    let depth = headDelta;
    let closeLine = -1;
    let hasBool = /(?:^|[^\p{L}\p{N}_])(И|ИЛИ)(?:[^\p{L}\p{N}_]|$)/u.test(m[2]);
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim() === '') continue;
      const w = fw(lines[j]);
      if (w === 'И' || w === 'ИЛИ') { hasBool = true; }
      else if (w === 'ТОГДА' || w === 'КОНЕЦ' || w === 'КОГДА' || w === 'ИНАЧЕ') break;
      const before = depth;
      depth += parenDelta(lines[j]);
      if (depth === 0) {
        // Закрытие ведущей `(` пришло на этой строке. Требуем: (а) `)` — ПОСЛЕДНИЙ
        // непробельный символ строки; (б) СЛЕДУЮЩАЯ значимая строка — терминатор
        // условия (ТОГДА), т.е. обёртка охватывает ВСЁ условие КОГДА, а не его ПЕРВУЮ
        // часть (`КОГДА (A ИЛИ B) И C` — здесь `)` закрывается посреди условия, и
        // оракул обёртку СОХРАНЯЕТ; фаза 6.16.78, корпус ПриходнаяНакладная).
        if (before > 0 && /\)\s*$/u.test(lines[j])) {
          let nextW = '';
          for (let k = j + 1; k < lines.length; k++) {
            if (lines[k].trim() === '') continue;
            nextW = fw(lines[k]); break;
          }
          if (nextW === 'ТОГДА') closeLine = j;
        }
        break;
      }
      if (depth < 0) break;
    }
    if (closeLine < 0 || !hasBool) continue;
    // Снимаем ведущую `(` после КОГДА и закрывающую `)` в конце closeLine.
    lines[i] = m[1] + m[2];
    lines[closeLine] = lines[closeLine].replace(/\)(\s*)$/u, '$1');
  }
}

/**
 * Снимает ИЗБЫТОЧНУЮ группирующую `(…)`, обёрнутую разработчиком вокруг ЛЕВОГО
 * операнда мультипликативной арифметики в значении ветки ТОГДА/ИНАЧЕ, когда внутри
 * обёртки — вложенный `… / ВЫБОР … КОНЕЦ`, а сразу за её закрывающей `)` идёт `*`/`/`
 * того же приоритета (`ТОГДА (A / ВЫБОР … КОНЕЦ) * (B / C)` → `ТОГДА A / ВЫБОР … КОНЕЦ
 * * (B / C)`; фаза 6.16, корпус ФормаПодбораАвансовПокупателей). Скобка избыточна:
 * `*`/`/` левоассоциативны и одного приоритета, поэтому `(a / b) * c == a / b * c`.
 * Мутирует `lines` на месте. Узкий гейт: ведущая `(` сразу после ТОГДА/ИНАЧЕ;
 * голова строки оканчивается словом ВЫБОР (открывает вложенный CASE); верхнеуровневый
 * (внутри обёртки) оператор перед этим ВЫБОР — `/` или `*`; закрывающая `)` обёртки
 * стоит на строке КОНЕЦ вложенного CASE и за ней СРАЗУ идёт `*`/`/`.
 */
function stripRedundantThenArithmeticWrap(lines: string[]): void {
  const fw = (s: string): string => {
    const m = /^[\t ]*([\p{L}]+)/u.exec(s);
    return m ? m[1].toUpperCase() : '';
  };
  const parenDelta = (s: string): number => {
    let d = 0, inS = false;
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (ch === '(') d++;
      else if (ch === ')') d--;
    }
    return d;
  };
  for (let i = 0; i < lines.length; i++) {
    const w = fw(lines[i]);
    if (w !== 'ТОГДА' && w !== 'ИНАЧЕ') continue;
    // Голова `ТОГДА (<тело> ВЫБОР` — ведущая `(` сразу после ключевого слова, строка
    // оканчивается словом ВЫБОР (открывает вложенный CASE).
    const m = new RegExp(`^([\\t ]*${w}[\\t ]+)\\((.*)$`, 'u').exec(lines[i]);
    if (!m) continue;
    if (!/(?:^|[^\p{L}\p{N}_])ВЫБОР\s*$/u.test(m[2])) continue;
    const headBody = '(' + m[2];
    if (parenDelta(headBody) < 1) continue; // ведущая `(` не охватывает продолжения
    // Верхнеуровневый (внутри обёртки) оператор перед ВЫБОР: на глубине РОВНО 1
    // относительно ведущей `(`. Ищем последний `*`/`/` на этой глубине в теле головы.
    let d = 0, inS = false, topMulOp = false;
    for (let c = 0; c < headBody.length; c++) {
      const ch = headBody[c];
      if (ch === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (ch === '(') d++;
      else if (ch === ')') d--;
      else if (d === 1 && (ch === '*' || ch === '/')) topMulOp = true;
    }
    if (!topMulOp) continue;
    // Идём по продолжениям, отслеживая глубину обёртки. Её закрытие (глубина → 0)
    // должно прийти на строке КОНЕЦ вложенного CASE: либо за `)` СРАЗУ идёт `*`/`/`
    // (приоритетная обёртка `(A / ВЫБОР…КОНЕЦ) * B`), либо `)` — конец значения ветки
    // (полная обёртка `ИНАЧЕ (A / ВЫБОР…КОНЕЦ)`, следующая значимая строка —
    // терминатор внешнего CASE: КОНЕЦ/ТОГДА/ИНАЧЕ/КОГДА).
    let depth = parenDelta(headBody);
    let closeLine = -1;
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim() === '') continue;
      const before = depth;
      depth += parenDelta(lines[j]);
      if (depth <= 0) {
        if (before > 0 && fw(lines[j]) === 'КОНЕЦ') {
          if (/^[\t ]*КОНЕЦ\)\s*[*/]\s/u.test(lines[j])) {
            closeLine = j;
          } else if (/^[\t ]*КОНЕЦ\)\s*$/u.test(lines[j])) {
            // Полная обёртка значения: за `)` ничего нет, следующая значимая строка —
            // терминатор внешнего CASE.
            let nextW = '';
            for (let k = j + 1; k < lines.length; k++) {
              if (lines[k].trim() === '') continue;
              nextW = fw(lines[k]); break;
            }
            if (nextW === 'КОНЕЦ' || nextW === 'ТОГДА' || nextW === 'ИНАЧЕ' || nextW === 'КОГДА') {
              closeLine = j;
            }
          }
        }
        break;
      }
    }
    if (closeLine < 0) continue;
    // Снимаем ведущую `(` после ТОГДА/ИНАЧЕ и закрывающую `)` ПОСЛЕ слова КОНЕЦ.
    lines[i] = m[1] + m[2];
    lines[closeLine] = lines[closeLine].replace(/^([\t ]*КОНЕЦ)\)/u, '$1');
  }
}

export function reindentLeafCase(text: string, base: number, funcParenDepth = false): string {
  // Снимаем избыточную группировку вокруг одиночного вызова (`ЕСТЬNULL((СУММА(…))`),
  // прежде чем считать геометрию CASE — иначе лишняя `(` сдвинула бы отступ (6.16.76).
  text = stripRedundantCallWrapParens(text);
  // Инлайн-CASE (весь `ВЫБОР … КОНЕЦ` в одну строку, либо `КОГДА … ТОГДА` склеены)
  // предразбиваем на структурные строки, чтобы дальнейшая геометрия его разложила
  // (фаза 6.16.71). На многострочном каноне сплит идемпотентен (переводы уже стоят).
  text = splitInlineLeafCase(text);
  if (!text.includes('\n')) return text;
  // Подзапросы внутри листа обрабатывает reindentLeafSubquery — здесь не трогаем.
  if (/\bВЫБРАТЬ\b/u.test(text)) return text;
  const lines = text.split('\n');

  // Найти первую строку, ОКАНЧИВАЮЩУЮСЯ словом ВЫБОР (открытие CASE — конструктор
  // всегда переносит после ВЫБОР). До неё считаем баланс скобок (вне литералов).
  const endsWithVybor = (s: string): boolean => /(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u.test(s);
  let openIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (endsWithVybor(lines[i])) { openIdx = i; break; }
  }
  // СЕЛЕКТОРНЫЙ CASE (`ВЫБОР <селектор>\n КОГДА … = … ТОГДА …`): открывающая строка
  // НАЧИНАЕТСЯ словом ВЫБОР, но НЕ оканчивается им (после ВЫБОР стоит селектор).
  // Трактуем её как открыватель (openIdx=0) — иначе reindentLeafCase пасовал и
  // сохранял исходный отступ (корпус ПланФактныйАнализПродаж, параметр-условие ВТ).
  // Гейт узкий: первая непустая строка начинается с ВЫБОР и в листе есть КОНЕЦ.
  if (openIdx < 0 && /^[\t ]*ВЫБОР(?:[^\p{L}\p{N}_]|$)/u.test(lines[0]) &&
      lines.some(l => /^[\t ]*КОНЕЦ(?:[^\p{L}\p{N}_]|$)/u.test(l))) {
    openIdx = 0;
  }
  if (openIdx < 0) return text;

  // Рефлоу к каноническому построчному виду (фаза 6.16.36, сверено живым оракулом).
  // Конструктор 1С ИГНОРИРУЕТ исходные переносы внутри выражения CASE и раскладывает
  // его по своим правилам: (а) всё ДО и ВКЛЮЧАЯ открывающее слово ВЫБОР — в ОДНУ строку
  // (`СУММА(\nВЫБОР` → `СУММА(ВЫБОР`; `СУММА(A * ВЫБОР`); (б) каждая структурная строка
  // (КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ/И/ИЛИ) — отдельная, а перенесённое ЗНАЧЕНИЕ ветки
  // (продолжение, НЕ начинающееся структурным словом) приклеивается к своей строке —
  // значение ТОГДА/ИНАЧЕ всегда на одной физической строке, как бы длинным оно ни было.
  // Старый код при таком переносе значения возвращал лист как есть (bail ниже по
  // структурному else) — исходное форматирование сохранялось, расходясь с оракулом.
  // Рефлоу применяем ТОЛЬКО когда в листе нет вложенного подзапроса. Подзапрос
  // (`КОГДА … В (ВЫБРАТЬ …)`) раскладывается своим путём (reindentLeafSubquery), а его
  // тело — многострочное и НЕ начинается структурными словами CASE; склейка его строк
  // схлопнула бы подзапрос. Штатный guard `\bВЫБРАТЬ\b` (выше) не ловит `(ВЫБРАТЬ`
  // (ASCII-граница слова на кириллице), поэтому проверяем здесь по Unicode-границам.
  const HAS_SUBQUERY_RE = /(?:^|[^\p{L}\p{N}_])ВЫБРАТЬ(?:[^\p{L}\p{N}_]|$)/iu;
  if (!HAS_SUBQUERY_RE.test(text)) {
    const STRUCT = new Set(['КОГДА', 'ТОГДА', 'ИНАЧЕ', 'КОНЕЦ', 'И', 'ИЛИ']);
    const fw = (s: string): string => {
      const m = /^[\t ]*([\p{L}]+)/u.exec(s);
      return m ? m[1].toUpperCase() : '';
    };
    // Склейка двух физических строк выражения по границе: без пробела после `(`,
    // перед `)`/`,`; иначе одиночный пробел. Внутреннее содержимое строк не трогаем
    // (строковые литералы сохраняются — нормализуем только стык).
    const joinAt = (a: string, b: string): string => {
      const left = a.replace(/\s+$/u, '');
      const right = b.replace(/^[\t ]+/u, '');
      if (right === '') return left;
      if (left.endsWith('(')) return left + right;
      if (right.startsWith(')') || right.startsWith(',')) return left + right;
      return left + ' ' + right;
    };
    const opener = lines.slice(0, openIdx + 1)
      .reduce((acc, l, i) => (i === 0 ? l.replace(/\s+$/u, '') : joinAt(acc, l)), '');
    const canonical: string[] = [opener];
    let cur: string | null = null;
    for (let i = openIdx + 1; i < lines.length; i++) {
      const r = lines[i];
      if (r.trim() === '') continue;
      if (STRUCT.has(fw(r))) {
        if (cur !== null) canonical.push(cur);
        cur = r.replace(/\s+$/u, '');
      } else if (cur === null) {
        cur = r.replace(/\s+$/u, '');
      } else {
        cur = joinAt(cur, r);
      }
    }
    if (cur !== null) canonical.push(cur);
    // Заменяем рабочий набор строк каноническим; открывающее слово ВЫБОР теперь в [0].
    lines.length = 0;
    lines.push(...canonical);
    openIdx = 0;
  }

  // Снятие ИЗБЫТОЧНОЙ обёртки `(…)` вокруг ВСЕГО условия КОГДА, разнесённого по
  // нескольким строкам (`КОГДА (НЕ A ЕСТЬ NULL\n И НЕ B ЕСТЬ NULL)` → без скобок).
  // Оракул снимает группу, охватывающую всё условие (И связывает крепче, чем нужна
  // обёртка) — зеркало renderWhenCondition (case 'group') для структурного пути,
  // фаза 6.16.78 (живой оракул). Однострочную обёртку снимает stripClause ниже;
  // здесь — только МНОГОСТРОЧНУЮ. Закрывающая `)` снимается с последней строки
  // условия (перед ТОГДА/КОНЕЦ/КОГДА/ИНАЧЕ).
  stripMultilineWhenWrap(lines);
  stripRedundantThenArithmeticWrap(lines);

  // Баланс скобок от начала листа до слова ВЫБОР на строке openIdx. Параллельно
  // считаем «эффективную» глубину: подряд идущие открывающие скобки `((` конструктор
  // 1С трактует как ОДИН уровень отступа (избыточная группировка `ЕСТЬNULL((СУММА(…`
  // даёт КОНЕЦ на base+2, а не base+3) — фаза 6.15.19, MCP. Если перед ВЫБОР
  // встречается закрывающая скобка (нетривиальная геометрия), эффективную глубину не
  // считаем и откатываемся на полный баланс (консервативно).
  //
  // `funcParenDepth` (фаза 6.16.14, MCP-пробы оракула `Справочник.Валюты` для слотов
  // ВЫБОРКА/ГДЕ): глубину CASE задают ТОЛЬКО ВЫЗОВ-функции скобки, остающиеся ОТКРЫТЫМИ
  // к слову ВЫБОР; скобка-ГРУППИРОВКА бинарной арифметики (`ВЫРАЗИТЬ(A * (B - ВЫБОР …`)
  // уровня НЕ добавляет, тогда как «эффективная» глубина (для слота ПО/ВТ, где скобка
  // вокруг вызова считается) её бы засчитала. Вызов-скобка — `(`, перед которой (без
  // пробелов) стоит символ идентификатора (имя функции).
  const isIdentChar = (ch: string | undefined): boolean =>
    ch !== undefined && /[\p{L}\p{N}_]/u.test(ch);
  let parenDepth = 0;
  let effectiveDepth = 0;
  let sawClose = false;
  let prevOpen = false;
  const callStack: boolean[] = [];
  let unbalanced = false;
  let prevNonSpace = '';
  let inStr = false;
  for (let i = 0; i <= openIdx; i++) {
    const line = lines[i];
    for (let c = 0; c < line.length; c++) {
      const ch = line[c];
      if (ch === '"') { inStr = !inStr; prevOpen = false; prevNonSpace = ch; continue; }
      if (inStr) continue;
      if (ch === '(') {
        parenDepth++;
        if (!prevOpen) effectiveDepth++; // первая скобка в серии `(((` — один уровень
        prevOpen = true;
        callStack.push(isIdentChar(prevNonSpace));
        prevNonSpace = ch;
        continue;
      }
      if (ch === ')') {
        parenDepth--; sawClose = true; prevOpen = false;
        if (callStack.pop() === undefined) unbalanced = true;
        prevNonSpace = ch;
        continue;
      }
      if (ch !== ' ' && ch !== '\t') { prevOpen = false; prevNonSpace = ch; }
    }
  }
  if (parenDepth < 0 || unbalanced) return text;

  const E0 = funcParenDepth
    ? base + callStack.filter(Boolean).length
    : base + (sawClose ? parenDepth : effectiveDepth);
  // Стек контекстов ВЫБОР: каждый элемент — отступ КОНЕЦ (E) данного ВЫБОР.
  const stack: number[] = [E0];
  // Текущий whenInd (для продолжений условия И/ИЛИ) — обновляется на строке КОГДА.
  let curWhen = -1;
  // Отступ ЗНАЧЕНИЯ ветки ТОГДА/ИНАЧЕ, после которой могут идти строки-продолжения
  // `И`/`ИЛИ`, принадлежащие ВЫРАЖЕНИЮ значения (а не условию КОГДА). Конструктор
  // отбивает такое продолжение значения на (отступ ТОГДА/ИНАЧЕ)+2 — глубже, чем
  // продолжение условия КОГДА (whenInd+2), т.к. условие КОГДА уже закрыто строкой
  // ТОГДА. -1 — продолжения значения сейчас нет (мы внутри условия КОГДА или после
  // КОНЕЦ). Геометрия `ТОГДА … \n И …` в каноне корпуса не встречается среди
  // ПРИНЯТЫХ — гейт узкий (фаза 6.16.43).
  let valueAnchor = -1;
  // Баланс скобок внутри текущего условия КОГДА (сбрасывается на КОГДА): продолжение
  // (`И`/`ИЛИ`), стоящее внутри вложенной скобочной группы условия, конструктор
  // отступает на +1 за каждый незакрытый уровень скобок.
  let condParen = 0;
  // Накопленный сдвиг приоритета И>ИЛИ по уровням скобок условия КОГДА: когда `И` со
  // сдвигом открывает группу, её содержимое наследует +1 (см. ветку И/ИЛИ ниже).
  // Индекс — уровень скобок, значение — суммарный сдвиг, действующий на этом уровне.
  let condShiftStack: number[] = [0];
  // Множество скобочных уровней текущего условия КОГДА, на которых встречается
  // верхнеуровневый `ИЛИ` (см. orLevelsForCondition). На таком уровне конъюнкты `И`
  // конструктор отступает на +1 глубже строк `ИЛИ` (приоритет И выше ИЛИ; фаза
  // 6.15.21, MCP). Чистая `И`-цепочка (без `ИЛИ` на уровне) сдвига НЕ получает.
  let condOrLevels = new Set<number>();
  // Скобочные уровни условия КОГДА, ОТКРЫТЫЕ группой `НЕ(…)`. Содержимое такой группы
  // отступается на +1 ГЛУБЖЕ (НЕ — отдельный уровень над скобкой; зеркало
  // leading-`НЕ`-сдвига в reindentLeafSubquery). Кроме того, на НЕ-уровне НЕ применяем
  // orShift приоритета И>ИЛИ: condOrLevels измеряет `ИЛИ` глобально по номеру уровня, а
  // `ИЛИ` соседней группы того же уровня к содержимому НЕ-группы не относится (фаза 6.16).
  let condNeLevels = new Set<number>();
  // Открывает ли строка `s` группу `НЕ(…)` (слово `НЕ` вплотную/через пробел перед `(`)?
  const neParenOpens = (s: string): number => {
    let opens = 0;
    let inS = false;
    let word = '';
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inS = !inS; word = ''; continue; }
      if (inS) continue;
      if (/[\p{L}\p{N}_]/u.test(ch)) { word += ch; continue; }
      if (ch === '(') { if (word.toUpperCase() === 'НЕ') opens++; word = ''; continue; }
      if (ch === ' ' || ch === '\t') { if (word.toUpperCase() !== 'НЕ') word = ''; continue; }
      word = '';
    }
    return opens;
  };
  // Чистый баланс скобок строки (вне строковых литералов).
  const parenDelta = (s: string): number => {
    let d = 0;
    let inS = false;
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (ch === '(') d++;
      else if (ch === ')') d--;
    }
    return d;
  };
  // Число ВЫЗОВ-функции скобок, остающихся ОТКРЫТЫМИ в конце строки `s` (`ЕСТЬNULL(`,
  // `ВЫРАЗИТЬ(` — `(`, перед которой без пробелов стоит символ-идентификатор). Скобка-
  // ГРУППИРОВКА арифметики уровня CASE не добавляет (зеркало funcParenDepth выше).
  // Используется при ТОГДА/ИНАЧЕ, ОТКРЫВАЮЩЕМ вложенный ВЫБОР внутри вызовов функций
  // (`ТОГДА ЕСТЬNULL(ВЫРАЗИТЬ(… * ВЫБОР`): глубина вложенного CASE = отступ ТОГДА +
  // число таких скобок + 1 — фаза 6.16.fmt, корпус РасходИзКассы/ПоступлениеВКассу.
  const openCallParens = (s: string): number => {
    const stackC: boolean[] = [];
    let inS = false;
    let prevNonSpace = '';
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inS = !inS; prevNonSpace = ch; continue; }
      if (inS) continue;
      if (ch === '(') { stackC.push(/[\p{L}\p{N}_]/u.test(prevNonSpace)); prevNonSpace = ch; continue; }
      if (ch === ')') { stackC.pop(); prevNonSpace = ch; continue; }
      if (ch !== ' ' && ch !== '\t') prevNonSpace = ch;
    }
    return stackC.filter(Boolean).length;
  };
  // Ведущий отступ листа может быть НАБРАН ПРОБЕЛАМИ (исходник конструктора иногда
  // отбивает CASE пробелами, а не табами). Функция переотрисовывает ВСЕ отступы от
  // base по структуре ВЫБОР/КОГДА/ТОГДА и от ВХОДНОГО отступа не зависит — поэтому
  // распознаём ключевые слова и считаем глубину игнорируя и пробелы, и табы.
  const tabsOf = (s: string): number => (s.match(/^[\t ]*/u) ?? [''])[0].length;
  // Переустановка ведущих табов + нормализация хвостовых пробелов: конструктор
  // срезает хвостовой пробел структурных строк, КРОМЕ предиката `ЕСТЬ НЕ NULL `,
  // который сохраняет ровно один хвостовой пробел (см. appendIsNotNullTrailingSpace).
  // Содержимое строки (после ведущих табов) прогоняем через normalizeLeafWhitespace —
  // тот же токенный нормализатор межтокенных промежутков, что и у однострочных листьев
  // (`НЕ (` → `НЕ(`, `( X` → `(X`, `,1` → `, 1`, схлопывание пробелов), который иначе
  // многострочные листья НЕ получают (его \n-skip подавляет построчные правки). Строковые
  // литералы и квирк `ЕСТЬ НЕ NULL ` он сохраняет (фаза 6.16.67).
  const reTab = (s: string, n: number): string =>
    '\t'.repeat(n) + appendIsNotNullTrailingSpace(normalizeLeafWhitespace(s.replace(/^[\t ]+/u, '').replace(/\s+$/u, '')));
  const firstWord = (s: string): string => {
    const m = /^[\t ]*([\p{L}]+)/u.exec(s);
    return m ? m[1].toUpperCase() : '';
  };
  // Снять избыточные охватывающие скобки вокруг ЗНАЧЕНИЯ ветки КОГДА/ТОГДА/ИНАЧЕ,
  // когда вся ветка умещается на одной строке (`КОГДА (X = &Y)` → `КОГДА X = &Y`,
  // `ТОГДА (a - b)` → `ТОГДА a - b`; фаза 6.16.37). НЕ трогаем строки, открывающие
  // вложенный ВЫБОР (kw … ВЫБОР), и строки с продолжением условия (обрабатываются
  // отдельной веткой И/ИЛИ). Работает на уже отбитой строке: переразбираем по
  // ключевому слову, чистим хвост скобок у содержимого.
  const stripClause = (line: string, kw: string): string => {
    const m = new RegExp(`^([\\t ]*${kw}[\\t ]+)([\\s\\S]+)$`, 'u').exec(line);
    if (!m) return line;
    // Сначала снимаем избыточную охватывающую пару; затем переотрисовываем чисто
    // арифметическое тело (снятие избыточных скобок по приоритету: `(A * B) / (C * D)`
    // → `A * B / (C * D)`, фаза 6.16.78) — reprintLeafArithmetic безопасно пасует на
    // не-чистой арифметике (сравнение/булева/стоп-слово → исходный текст); затем
    // оборачиваем голый ВЫРАЗИТЬ-операнд (фаза 6.16.69).
    const body = wrapBareCastOperand(reprintLeafComparison(reprintLeafArithmetic(stripRedundantCaseClauseParens(m[2]))));
    return body === m[2] ? line : m[1] + body;
  };
  // Голова значения ТОГДА/ИНАЧЕ, ОТКРЫВАЮЩАЯ вложенный ВЫБОР (`ТОГДА ВЫРАЗИТЬ(…) * ВЫБОР`):
  // охватывающую пару НЕ снимаем (ВЫБОР продолжается ниже), но голый ВЫРАЗИТЬ-операнд
  // арифметики/сравнения оборачиваем (`(ВЫРАЗИТЬ(…)) * ВЫБОР`; фаза 6.16.69).
  const wrapClauseHeadCast = (line: string, kw: string): string => {
    const m = new RegExp(`^([\\t ]*${kw}[\\t ]+)([\\s\\S]+)$`, 'u').exec(line);
    if (!m) return line;
    const body = wrapBareCastOperand(m[2]);
    return body === m[2] ? line : m[1] + body;
  };
  // Предсканирование условия КОГДА (строка startIdx — сама КОГДА): какие скобочные
  // уровни несут верхнеуровневый `ИЛИ`. Уровень строки = баланс скобок к её НАЧАЛУ
  // (после строки КОГДА). На таких уровнях конъюнкты `И` идут глубже (приоритет И>ИЛИ).
  const orLevelsForCondition = (startIdx: number): Set<number> => {
    const levels = new Set<number>();
    let lvl = parenDelta(lines[startIdx]); // незакрытые скобки после строки КОГДА
    for (let j = startIdx + 1; j < lines.length; j++) {
      const r = lines[j];
      if (r.trim() === '') continue;
      const fw = firstWord(r);
      if (fw === 'И' || fw === 'ИЛИ') {
        if (fw === 'ИЛИ') levels.add(lvl);
        lvl += parenDelta(r);
      } else {
        break; // ТОГДА/КОНЕЦ/прочее — конец условия
      }
    }
    return levels;
  };

  // Значение ветки ТОГДА/ИНАЧЕ — членство `(…) В (ВЫБРАТЬ …)`, где подзапрос разнесён
  // разработчиком по строкам ПОД строкой ключевого слова. reindentLeafCase сам по себе
  // не умеет вкладывать подзапрос (строки тела не структурные → штатный bail), а внешний
  // равномерный сдвиг (reindentLeafSubquery вокруг всего CASE) роняет геометрию КОГДА.
  // Здесь: если строка-значение `kwIdx` ОКАНЧИВАЕТСЯ оператором `В`/`В ИЕРАРХИИ`, а
  // следующая структурная строка открывает `(ВЫБРАТЬ`, отдаём блок подзапроса (от
  // строки `(ВЫБРАТЬ` до её сбалансированного `)`) в reindentLeafSubquery с base =
  // отступ ключевого слова + 2 (`(ВЫБРАТЬ` встаёт на anchor+2, тело глубже — как оракул).
  // Возвращаем индекс ПОСЛЕДНЕЙ поглощённой строки (или kwIdx, если случай не подходит).
  // Узкий гейт: ровно `… В` в конце строки kwIdx, подзапрос-операнд `(ВЫБРАТЬ` следом.
  const consumeValueSubquery = (kwIdx: number, anchor: number): number => {
    if (!/(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*$/u.test(lines[kwIdx])) return kwIdx;
    // Найти строку, начинающуюся с `(ВЫБРАТЬ` среди ближайших непустых.
    let sub = -1;
    for (let j = kwIdx + 1; j < lines.length; j++) {
      if (lines[j].trim() === '') continue;
      if (/^[\t ]*\(\s*ВЫБРАТЬ(?![\p{L}\p{N}_])/u.test(lines[j])) { sub = j; break; }
      return kwIdx; // первой непустой строкой идёт не подзапрос — не наш случай
    }
    if (sub < 0) return kwIdx;
    // Баланс скобок блока подзапроса от строки `(ВЫБРАТЬ` до закрытия.
    let depth = 0, inS = false, end = -1;
    for (let j = sub; j < lines.length; j++) {
      for (const ch of lines[j]) {
        if (ch === '"') inS = !inS;
        else if (!inS && ch === '(') depth++;
        else if (!inS && ch === ')') depth--;
      }
      if (depth <= 0) { end = j; break; }
    }
    if (end < 0) return kwIdx;
    // Реиндент блока подзапроса: `(ВЫБРАТЬ` на anchor+2, тело глубже. reindentLeafSubquery
    // ждёт «голову» перед строкой `(ВЫБРАТЬ`; даём фиктивную (пустую) строку-голову,
    // чтобы start>0, затем отбрасываем её. base подзапроса = anchor + 2 (его `(ВЫБРАТЬ`
    // ложится на base = anchor+2).
    const block = ['', ...lines.slice(sub, end + 1)].join('\n');
    const re = reindentLeafSubquery(block, anchor + 2).split('\n');
    re.shift(); // убрать фиктивную голову
    if (re.length !== end - sub + 1) return kwIdx; // геометрия не разложилась — не трогаем
    for (let j = sub; j <= end; j++) lines[j] = re[j - sub];
    return end;
  };

  for (let i = openIdx + 1; i < lines.length; i++) {
    const raw = lines[i];
    if (raw.trim() === '') continue; // пустые/разделительные строки не трогаем
    const E = stack[stack.length - 1];
    if (E === undefined) return text; // стек опустошён раньше времени — нестандартно
    const w = firstWord(raw);
    if (w === 'КОГДА') {
      const whenInd = E + 1;
      // Снимаем избыточные охватывающие скобки ПЕРВОГО конъюнкта условия КОГДА
      // (`КОГДА (X = &Y)` → `КОГДА X = &Y`). Пара охватывает лишь содержимое ЭТОЙ
      // строки; продолжения `И`/`ИЛИ` стоят отдельными строками — на их разбор это
      // не влияет (stripRedundantCaseClauseParens требует охвата всего текста строки).
      lines[i] = stripClause(reTab(raw, whenInd), 'КОГДА');
      if (endsWithVybor(lines[i])) {
        // Вложенный СЕЛЕКТОРНЫЙ ВЫБОР как операнд условия КОГДА: открывается прямо на
        // строке КОГДА (`КОГДА ВЫБОР … КОНЕЦ = &П ТОГДА …`). Его E (КОНЕЦ) = whenInd+1
        // (опорная строка-открыватель — сама КОГДА); хвост после внутреннего КОНЕЦ
        // (`КОНЕЦ = &П`) завершает условие КОГДА и остаётся на строке КОНЕЦ. Без этой
        // ветки внутренний ВЫБОР не отслеживался и стек опустошался раньше времени
        // → весь лист откатывался к исходному форматированию (фаза 6.16.65).
        stack.push(whenInd + 1);
        curWhen = -1; valueAnchor = -1; condParen = 0; condOrLevels = new Set(); condShiftStack = [0]; condNeLevels = new Set();
      } else {
        curWhen = whenInd;
        valueAnchor = -1;
        condParen = 0;
        condShiftStack = [0];
        condNeLevels = new Set();
        // Ведущая скобка-ГРУППА ПЕРВОГО конъюнкта (`КОГДА (X = … \n ИЛИ Y)`), не
        // снятая stripClause (она охватывает НЕСКОЛЬКО строк, поэтому не считается
        // охватывающей одну строку), уровня отступа продолжениям НЕ добавляет: оракул
        // ставит первое `ИЛИ` на whenInd+2, а не whenInd+3. Уменьшаем стартовый
        // уровень скобок условия на этот ведущий `(` (только если условие НАЧИНАЕТСЯ
        // с него — внутренние группы `A И (B ИЛИ C)` уровень добавляют как прежде).
        // Тот же сдвиг отражаем в orLevelsForCondition, чтобы `И`-сдвиг считался от
        // согласованного уровня (фаза 6.16.65).
        const condBody = stripClause(reTab(raw, whenInd), 'КОГДА').replace(/^\t*КОГДА\s*/u, '');
        // Ведущую `(` вычитаем ТОЛЬКО если её группа ОХВАТЫВАЕТ продолжения (остаётся
        // ОТКРЫТОЙ к концу строки КОГДА — `КОГДА (X = … \n ИЛИ Y)`). Самодостаточная
        // ведущая группа, ЗАКРЫВАЮЩАЯСЯ на той же строке (`(ВЫРАЗИТЬ(…)) = Z ИЛИ …`),
        // продолжениям уровня не задаёт — её вычитать нельзя (иначе ИЛИ уезжал на −1,
        // корпус СтатистикаЧеков). Признак охвата: глубина после ведущей `(` не
        // возвращается к 0 до конца condBody.
        const leadParenEncloses = (): boolean => {
          if (!/^\(/u.test(condBody)) return false;
          let d = 0, inS = false;
          for (let c = 0; c < condBody.length; c++) {
            const ch = condBody[c];
            if (ch === '"') { inS = !inS; continue; }
            if (inS) continue;
            if (ch === '(') d++;
            else if (ch === ')') { d--; if (d === 0 && c < condBody.length - 1) return false; }
          }
          return d >= 1;
        };
        const condLeadParen = leadParenEncloses() ? 1 : 0;
        condOrLevels = orLevelsForCondition(i);
        condParen += parenDelta(lines[i]) - condLeadParen;
      }
    } else if (w === 'И' || w === 'ИЛИ') {
      // Продолжение значения ветки ТОГДА/ИНАЧЕ (фаза 6.16.43): если строка `И`/`ИЛИ`
      // стоит ПОСЛЕ ТОГДА/ИНАЧЕ (valueAnchor задан) — это продолжение ВЫРАЖЕНИЯ
      // значения (`ТОГДА A В (…) И B = …`), а не условия КОГДА. Конструктор отбивает
      // его на (отступ ТОГДА/ИНАЧЕ)+2. Условие КОГДА к этому моменту закрыто.
      if (valueAnchor >= 0) {
        lines[i] = reTab(raw, valueAnchor + 2 + condParen);
        condParen += parenDelta(raw);
        continue;
      }
      // Продолжение условия КОГДА: базовый отступ whenInd+2, плюс по +1 за каждый
      // незакрытый уровень скобок условия (вложенная группа `И (… ИЛИ …)`). Если на
      // текущем уровне есть верхнеуровневый `ИЛИ`, конъюнкт `И` идёт ещё на +1 глубже
      // (приоритет И>ИЛИ; фаза 6.15.21, MCP).
      if (curWhen < 0) return text;
      // На уровне-внутри-`НЕ(…)` приоритет И>ИЛИ НЕ применяем: condOrLevels измеряет
      // `ИЛИ` глобально по номеру скобочного уровня, но `ИЛИ` СОСЕДНЕЙ группы того же
      // уровня к содержимому НЕ-группы не относится (его +1 уже даёт сама НЕ-группа).
      const orShift = w === 'И' && !condNeLevels.has(condParen) && condOrLevels.has(condParen) ? 1 : 0;
      // Накопленный сдвиг приоритета на ТЕКУЩЕМ уровне скобок: когда `И` со сдвигом
      // ИЛИ-приоритета ОТКРЫВАЕТ группу (`И (G ИЛИ H)`), содержимое этой группы
      // наследует тот же +1 (вложенный `ИЛИ H` встаёт глубже строки `И (G`, а не
      // вровень). Без наследования вложенный ИЛИ уезжал на −1 (корпус ПриходнаяНакладная,
      // ОстаткиТоваровМеньшеНуля). Сдвиг хранится по уровням скобок.
      const curShift = condShiftStack[condParen] ?? 0;
      lines[i] = reTab(raw, curWhen + 2 + condParen + curShift + orShift);
      // Избыточная обёртка вокруг операнда продолжения `ИЛИ` условия КОГДА
      // (`ИЛИ (X МЕЖДУ a И b)`, `ИЛИ (X ЕСТЬ NULL)`): предикат/сравнение связывает
      // крепче ИЛИ, и оракул скобки снимает (`ИЛИ X МЕЖДУ a И b`). Зеркало
      // renderBool/renderWhenCondition (`group(leaf)`-операнд ИЛИ разворачивается).
      // ТОЛЬКО для `ИЛИ`: операнд `И` оракул В СКОБКАХ СОХРАНЯЕТ (`И (X МЕЖДУ a И b)`
      // остаётся со скобками — живой оракул; зеркало `and`-ветки renderBool, которая
      // group(leaf) НЕ разворачивает). Узко: пара ОТКРЫВАЕТСЯ и ЗАКРЫВАЕТСЯ на этой
      // же строке (parenDelta==0, не трогаем учёт уровней condParen), внутри нет
      // верхнеуровневого И/ИЛИ/ВЫБОР (stripRedundantCaseClauseParens сам пасует) —
      // значимую группу `(A ИЛИ B)` не разворачиваем (корпус ОбработкаНовостейСлужебный).
      if (w === 'ИЛИ' && parenDelta(raw) === 0) {
        lines[i] = stripClause(lines[i], w);
      }
      // Открытие новых уровней скобок на этой строке наследует сдвиг текущей строки
      // (curShift + orShift) — он действует на всё содержимое открытой группы. Группа
      // `НЕ(…)` добавляет содержимому ЕЩЁ +1 (НЕ — отдельный уровень над скобкой) и
      // помечает открытые уровни как НЕ-уровни (фаза 6.16, корпус ДанныеОКорректировке).
      const delta = parenDelta(raw);
      if (delta > 0) {
        const neOpens = (w === 'И' || w === 'ИЛИ') ? neParenOpens(raw) : 0;
        const inherited = curShift + orShift;
        for (let lv = condParen + 1; lv <= condParen + delta; lv++) {
          condShiftStack[lv] = inherited + (neOpens > 0 ? 1 : 0);
          if (neOpens > 0) condNeLevels.add(lv); else condNeLevels.delete(lv);
        }
      }
      // Закрывающая скобка ВЕДУЩЕЙ группы первого конъюнкта (вычтенной из стартового
      // condParen) приходит на этой же строке-продолжении — клампим уровень снизу
      // нулём, чтобы её `)` не утянул последующие конъюнкты на −1 (фаза 6.16.65).
      condParen = Math.max(0, condParen + delta);
    } else if (w === 'ТОГДА') {
      const tabbed = reTab(raw, E + 2);
      lines[i] = endsWithVybor(raw) ? wrapClauseHeadCast(tabbed, 'ТОГДА') : stripClause(tabbed, 'ТОГДА');
      if (endsWithVybor(raw)) {
        // Вложенный ВЫБОР, открытый внутри ВЫЗОВ-функции скобок на строке ТОГДА
        // (`ТОГДА ЕСТЬNULL(ВЫРАЗИТЬ(… * ВЫБОР`): его КОНЕЦ глубже на число открытых
        // вызов-скобок (funcParenDepth-семантика; иначе нет — backward-compatible).
        const head = lines[i].replace(/(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u, '$1');
        const callDepth = funcParenDepth ? openCallParens(head.replace(/^\t*/u, '')) : 0;
        stack.push(E + 2 + callDepth + 1); curWhen = -1; valueAnchor = -1;
      }
      else {
        curWhen = -1; valueAnchor = E + 2; condParen = parenDelta(lines[i]);
        const consumed = consumeValueSubquery(i, E + 2);
        if (consumed > i) { i = consumed; valueAnchor = -1; }
      }
    } else if (w === 'ИНАЧЕ') {
      const tabbed = reTab(raw, E + 1);
      lines[i] = endsWithVybor(raw) ? wrapClauseHeadCast(tabbed, 'ИНАЧЕ') : stripClause(tabbed, 'ИНАЧЕ');
      if (endsWithVybor(raw)) {
        const head = lines[i].replace(/(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u, '$1');
        const callDepth = funcParenDepth ? openCallParens(head.replace(/^\t*/u, '')) : 0;
        stack.push(E + 1 + callDepth + 1); curWhen = -1; valueAnchor = -1;
      }
      else {
        curWhen = -1; valueAnchor = E + 1; condParen = parenDelta(lines[i]);
        const consumed = consumeValueSubquery(i, E + 1);
        if (consumed > i) { i = consumed; valueAnchor = -1; }
      }
    } else if (w === 'КОНЕЦ') {
      // Хвост-арифметика после КОНЕЦ (`КОНЕЦ / ВЫРАЗИТЬ(…)`): голый ВЫРАЗИТЬ-операнд
      // оборачиваем (`КОНЕЦ / (ВЫРАЗИТЬ(…))`; фаза 6.16.69). wrapBareCastOperand —
      // идемпотентна и срабатывает лишь при наличии бинарного оператора и голого cast.
      // wrapBareCastOperand отбрасывает ведущие табы (работает по позициям токенов),
      // поэтому отделяем отступ и возвращаем его на место.
      {
        const tabbed = reTab(raw, E);
        const lead = /^\t*/u.exec(tabbed)![0];
        lines[i] = lead + wrapBareCastOperand(tabbed.slice(lead.length));
      }
      stack.pop();
      curWhen = -1;
      valueAnchor = -1;
      // Соседний ВЫБОР на той же строке КОНЕЦ (`КОНЕЦ + ВЫБОР`, `КОНЕЦ) + СУММА(ВЫБОР`):
      // арифметика из нескольких ВЫБОР внутри одного листа. Конструктор открывает
      // новый блок с E, сдвинутым на чистый баланс скобок строки ДО слова ВЫБОР
      // (закрытие `)` сразу скомпенсировано открытием `(` следующего вызова → E тот
      // же). Переоткрываем стек и продолжаем (фаза 6.15.19).
      if (endsWithVybor(lines[i])) {
        // Соседний ВЫБОР той же арифметической цепочки (`КОНЕЦ) * ВЫБОР`,
        // `КОНЕЦ * ЕСТЬNULL(ВЫБОР`, `КОНЕЦ) * Y * ВЫБОР`). Его отступ = E, сдвинутый на
        // баланс ВЫЗОВ-функции скобок головы (до слова ВЫБОР): скобка-ГРУППИРОВКА уровня
        // не даёт и не отнимает (`КОНЕЦ) * Y * ВЫБОР` после `(100 + ВЫБОР` остаётся на E,
        // `КОНЕЦ * (ВЫБОР` тоже на E), а вот закрытие ВЫЗОВ-скобки (`СУММА(ВЫБОР…КОНЕЦ) *
        // ВЫБОР`) опускает сиблинг на −1, открытие (`ЕСТЬNULL(ВЫБОР`) поднимает на +1.
        // Тип закрываемой `)` определяем по типовому стеку скобок от начала листа
        // (корпус СдельныйНаряд, КорректировкаПоступления, РасчетыПроведениеДокументов).
        const head = lines[i].replace(/(^|[^\p{L}\p{N}_])ВЫБОР\s*$/u, '$1');
        // Типовой стек скобок ДО головы текущей строки: true — вызов-функция.
        const typeStack: boolean[] = [];
        {
          let inS = false; let prev = '';
          const scan = (s: string): void => {
            for (let c = 0; c < s.length; c++) {
              const ch = s[c];
              if (ch === '"') { inS = !inS; prev = ch; continue; }
              if (inS) continue;
              if (ch === '(') { typeStack.push(/[\p{L}\p{N}_]/u.test(prev)); prev = ch; }
              else if (ch === ')') { typeStack.pop(); prev = ch; }
              else if (ch !== ' ' && ch !== '\t') prev = ch;
            }
          };
          for (let j = 0; j < i; j++) scan(lines[j]);
          // Голову текущей строки сканируем со счётом call-delta.
          let callDelta = 0;
          for (let c = 0; c < head.length; c++) {
            const ch = head[c];
            if (ch === '"') { inS = !inS; prev = ch; continue; }
            if (inS) continue;
            if (ch === '(') { const isCall = /[\p{L}\p{N}_]/u.test(prev); typeStack.push(isCall); if (isCall) callDelta++; prev = ch; }
            else if (ch === ')') { if (typeStack.pop()) callDelta--; prev = ch; }
            else if (ch !== ' ' && ch !== '\t') prev = ch;
          }
          stack.push(E + callDelta);
        }
        continue;
      }
      if (stack.length === 0) {
        // Достигли КОНЕЦ внешнего ВЫБОР: оставшиеся строки (если есть непустые) —
        // нестандартный хвост, который не должен возникать; всё ок если их нет.
        for (let j = i + 1; j < lines.length; j++) {
          if (lines[j].trim() !== '') return text;
        }
        break;
      }
    } else {
      // Строка не начинается структурным ключевым словом: это либо значение
      // ТОГДА/ИНАЧЕ, перенесённое на свою строку (геометрия не каноническая),
      // либо неожиданная конструкция. Сверяем её отступ — если он уже совпадает с
      // ожидаемым (значение инлайн с ТОГДА/ИНАЧЕ кладётся на ту же строку, сюда
      // такие не попадают), пропускаем; иначе bail.
      const t = tabsOf(raw);
      if (t < E) return text; // мельче КОНЕЦ — точно чужая геометрия
      // Иное продолжение значения — не трогаем абсолютную позицию (bail безопаснее).
      return text;
    }
  }
  if (stack.length !== 0) return text; // не все ВЫБОР закрылись — нестандартно
  // Хвостовой СПИСОК ЗНАЧЕНИЙ оператора `В` после КОНЕЦ (`КОНЕЦ В (\n a,\n b)`),
  // разбитый разработчиком по строкам, конструктор печатает ИНЛАЙН на строке КОНЕЦ
  // (как и прочие списки значений). Сплющиваем (подзапрос `В (ВЫБРАТЬ …)` не трогаем).
  return flattenInlineValueLists(lines.join('\n'));
}

/**
 * Рефлоу СЕЛЕКТОРНОГО ВЫБОР, ВЛОЖЕННОГО в значение ТОГДА/ИНАЧЕ внутрь вызова функции
 * (фаза 6.15.26, MCP-пробы). Когда значение ветки CASE — листовой вызов вида
 * `ЕСТЬNULL(a, ЕСТЬNULL(ВЫБОР sel КОГДА … ТОГДА … КОНЕЦ, b))`, конструктор 1С:
 *   (а) сплющивает аргументы функции до строки `… ЕСТЬNULL(ВЫБОР sel` (первая строка);
 *   (б) РЕФЛОИТ встроенный CASE — разбивает инлайн `КОГДА X ТОГДА Y` на отдельные
 *       строки с канонической геометрией: КОГДА=E+1, ТОГДА=E+2, ИНАЧЕ=E+1, КОНЕЦ=E,
 *       где E = `valueBaseInd` (отступ значения-листа = отступ ТОГДА/ИНАЧЕ + 2) +
 *       число НЕзакрытых скобок, стоящих перед словом ВЫБОР;
 *   (в) хвост после КОНЕЦ (закрывающие аргументы `, b))`) кладёт на строку КОНЕЦ.
 *
 * Применяется ТОЛЬКО когда: лист содержит ВЫБОР на глубине скобок > 0 (внутри вызова,
 * а не голым значением — голый ВЫБОР парсер делает узлом case), у этого ВЫБОР есть
 * СЕЛЕКТОР (`ВЫБОР <выражение> КОГДА`, а не `ВЫБОР КОГДА`), и весь CASE закрывается
 * на верхнем уровне скобок одним КОНЕЦ. Любая иная геометрия (несколько ВЫБОР,
 * подзапрос, вложенный ВЫБОР в ТОГДА) → возврат входа без изменений.
 *
 * ВАЖНО: в каноне всего корпуса нет ни одного инлайн `КОГДА X ТОГДА Y`, поэтому
 * направленный сплит однострочных КОГДА/ТОГДА безопасен.
 */
export function reflowLeafSelectorCase(text: string, valueBaseInd: number): string | null {
  if (!text) return null;
  // Сплющиваем весь лист в одну строку (аргументы вызова), сохраняя пунктуацию.
  const flat = flattenLeafText(text);
  let toks: Token[];
  try {
    toks = tokenize(flat);
  } catch {
    return null;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  const isW = (t: Token, w: string): boolean =>
    (t.type === 'keyword' || t.type === 'ident') && t.value.toUpperCase() === w;
  if (!sig.some((t) => isW(t, 'ВЫБОР'))) return null;
  if (sig.some((t) => isW(t, 'ВЫБРАТЬ'))) return null; // подзапрос — не наша зона
  // Глубина скобок ПЕРЕД каждым токеном.
  const depthBefore: number[] = [];
  let d = 0;
  for (const t of sig) {
    depthBefore.push(d);
    if (t.type === 'punct' && t.value === '(') d++;
    else if (t.type === 'punct' && t.value === ')') d--;
  }
  // Первый ВЫБОР на глубине > 0 (внутри вызова функции).
  let vi = -1;
  for (let k = 0; k < sig.length; k++) {
    if (isW(sig[k], 'ВЫБОР') && depthBefore[k] > 0) { vi = k; break; }
  }
  if (vi < 0) return null;
  // Более одного ВЫБОР в листе — арифметика/иная геометрия, не наш случай.
  if (sig.some((t, k) => k !== vi && isW(t, 'ВЫБОР'))) return null;
  const caseDepth = depthBefore[vi];
  // У ВЫБОР должен быть СЕЛЕКТОР: следующий значимый токен — не КОГДА.
  if (vi + 1 >= sig.length || isW(sig[vi + 1], 'КОГДА')) return null;
  // Найти первый КОГДА на уровне CASE (после селектора).
  let firstWhen = -1;
  for (let k = vi + 1; k < sig.length; k++) {
    if (depthBefore[k] === caseDepth && isW(sig[k], 'КОГДА')) { firstWhen = k; break; }
    // Скобка закрылась раньше КОГДА — нестандартно.
    if (depthBefore[k] < caseDepth) return null;
  }
  if (firstWhen < 0) return null;
  // E (отступ КОНЕЦ) = базовый отступ значения-листа − 1 + число НЕзакрытых скобок
  // перед ВЫБОР. (valueBaseInd = отступ ТОГДА/ИНАЧЕ + 2; MCP-пробы фазы 6.15.26.)
  const E = valueBaseInd - 1 + caseDepth;
  // Первая строка: всё от начала листа до начала первого КОГДА (включая `ВЫБОР sel`).
  const out: string[] = [];
  out.push(flat.slice(0, sig[firstWhen].pos).replace(/\s+$/u, ''));
  // Перебор КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ на уровне CASE; текст между ключевыми словами
  // прикрепляется к предыдущему ключевому слову (инлайн-значение/условие).
  type Mark = { k: number; word: 'КОГДА' | 'ТОГДА' | 'ИНАЧЕ' | 'КОНЕЦ' };
  const marks: Mark[] = [];
  for (let k = firstWhen; k < sig.length; k++) {
    if (depthBefore[k] !== caseDepth) continue;
    const t = sig[k];
    if (isW(t, 'КОГДА')) marks.push({ k, word: 'КОГДА' });
    else if (isW(t, 'ТОГДА')) marks.push({ k, word: 'ТОГДА' });
    else if (isW(t, 'ИНАЧЕ')) marks.push({ k, word: 'ИНАЧЕ' });
    else if (isW(t, 'КОНЕЦ')) { marks.push({ k, word: 'КОНЕЦ' }); break; }
  }
  // Последний mark обязан быть КОНЕЦ (CASE закрылся на своём уровне).
  if (marks.length === 0 || marks[marks.length - 1].word !== 'КОНЕЦ') return null;
  // Вложенный ВЫБОР в значении ветки исключён выше (единственный ВЫБОР в листе).
  for (let m = 0; m < marks.length; m++) {
    const cur = marks[m];
    const ind = cur.word === 'КОГДА' ? E + 1
      : cur.word === 'ТОГДА' ? E + 2
      : cur.word === 'ИНАЧЕ' ? E + 1
      : E; // КОНЕЦ
    // Текст строки: от начала текущего ключевого слова до начала следующего
    // (для КОНЕЦ — до конца листа, включая хвостовые `, b))`).
    const from = cur.k;
    const to = m + 1 < marks.length ? marks[m + 1].k : -1;
    const sliceFrom = sig[from].pos;
    const sliceTo = to >= 0 ? sig[to].pos : flat.length;
    const seg = flat.slice(sliceFrom, sliceTo).replace(/\s+$/u, '');
    out.push('\t'.repeat(ind) + seg);
  }
  return out.join('\n');
}

/**
 * Переотступ продолжений булева листа поля выборки (фаза 6.15.19, MCP). Конструктор
 * нормализует отступ строк-продолжений `И`/`ИЛИ` плоской И/ИЛИ-цепочки поля выборки
 * к `base + 1` НЕЗАВИСИМО от исходного отступа разработчика (`X\n\t\t\tИ Y` →
 * `X\n\tИ Y` при base=1). Применяется только к ПЛОСКОЙ цепочке: первая строка —
 * операнд0 (любой текст), все последующие непустые строки обязаны начинаться с
 * `И`/`ИЛИ` на верхнем уровне скобок. Любая иная геометрия (ВЫБОР, подзапрос,
 * перенос операнда без И/ИЛИ, непарный баланс скобок) → возврат входа без изменений.
 */
export function reindentLeafBool(text: string, base: number): string {
  if (!text.includes('\n')) return text;
  if (/\bВЫБРАТЬ\b|\bВЫБОР\b/u.test(text)) return text; // подзапрос/CASE — не наша зона
  const lines = text.split('\n');
  const parenDelta = (s: string): number => {
    let d = 0;
    let inS = false;
    for (let c = 0; c < s.length; c++) {
      const ch = s[c];
      if (ch === '"') { inS = !inS; continue; }
      if (inS) continue;
      if (ch === '(') d++;
      else if (ch === ')') d--;
    }
    return d;
  };
  const firstWord = (s: string): string => {
    const m = /^\t*([\p{L}]+)/u.exec(s);
    return m ? m[1].toUpperCase() : '';
  };
  // Уровни скобок, на которых ВСТРЕТИЛСЯ верхнеуровневый `ИЛИ`: на таком уровне
  // последующий конъюнкт `И` идёт на +1 глубже строк `ИЛИ` (приоритет И>ИЛИ; зеркало
  // condOrLevels в reindentLeafCase) — корпус УчетНДФЛ `МАКСИМУМ(A ИЛИ B И C)`.
  const orLevels = new Set<number>();
  // Баланс скобок к началу каждой следующей строки: продолжение `И`/`ИЛИ` считаем
  // верхнеуровневым, только если до него все скобки сбалансированы (depth 0).
  let depth = parenDelta(lines[0]);
  for (let i = 1; i < lines.length; i++) {
    const raw = lines[i];
    if (raw.trim() === '') { depth += parenDelta(raw); continue; }
    const w = firstWord(raw);
    if (w !== 'И' && w !== 'ИЛИ') return text; // продолжение не И/ИЛИ — не наша цепочка
    // Продолжение `И`/`ИЛИ` внутри незакрытой скобочной группы конструктор отбивает
    // на `base+1` ПЛЮС по +1 за каждый открытый уровень скобок в начале строки
    // (`(A\n\tИЛИ B)` при base=1 → ИЛИ на base+1+1). Плоская цепочка (depth=0) — как
    // прежде на base+1 (фаза 6.16.66). Плюс +1 для `И` на уровне, несущем `ИЛИ`.
    const orShift = w === 'И' && orLevels.has(depth) ? 1 : 0;
    if (w === 'ИЛИ') orLevels.add(depth);
    lines[i] = '\t'.repeat(base + 1 + depth + orShift) + raw.replace(/^\t+/u, '').replace(/\s+$/u, '');
    depth += parenDelta(lines[i]);
  }
  return lines.join('\n');
}

/**
 * Правая часть простого условия `<op> <param>`. Конструктор 1С не ставит пробел перед
 * скобкой списка значений у оператора `В` (и `В ИЕРАРХИИ`): `В (&Список)` → `В(&Список)`,
 * `В ИЕРАРХИИ (&Род)` → `В ИЕРАРХИИ(&Род)`. Перед подзапросом (`В (ВЫБРАТЬ …)`) конструктор
 * переносит на новую строку — это вне модели простых условий (фаза 6.11), здесь не трогаем.
 * Общая точка генератора и парсера (фаза 6.14.4): парсер строит этим же рендером
 * текст произвольного условия с не-параметром справа — байт-в-байт со старым выводом.
 *
 * `leafSpacing` (фаза 6.15.1, MCP-пробы): условие целиком лежит ВНУТРИ подзапроса
 * правого операнда `В` (`В (ВЫБРАТЬ … ГДЕ …)`) — конструктор печатает такой текст
 * по правилам произвольного выражения, С пробелом перед скобкой: `В (&П)`,
 * `В ИЕРАРХИИ (&П)`. Подзапрос-источник (`ИЗ (ВЫБРАТЬ …)`) рендерится БЕЗ пробела
 * (структурный путь) — там флаг не взводится.
 */
export function renderOperatorRhs(op: string, param: string, leafSpacing = false): string {
  if (op === 'В') {
    if (param.startsWith('(')) {
      // Список значений `В (a, b, …)` конструктор печатает ИНЛАЙН на одной строке,
      // даже если разработчик разбил его по запятым на несколько строк. Сплющиваем
      // многострочный список в одну строку. Сплющиваем ТОЛЬКО если param —
      // сбалансированный список `( … )` БЕЗ хвоста (иногда парсер ошибочно
      // захватывает в param хвостовые секции вида `\n\nУПОРЯДОЧИТЬ ПО …` — их
      // сплющивать нельзя) и БЕЗ вложенного подзапроса `(ВЫБРАТЬ …)`.
      const list =
        param.includes('\n') && isPureBalancedList(param) && !leafHasSubquery(param)
          ? flattenLeafText(param)
          : param;
      // Список из 2+ элементов конструктор отделяет пробелом: `В (a, b)`; список из
      // одного элемента — без пробела: `В(a)` (доказано на корпусе оракула:
      // multi 18 пробел / 0 без; single 14 пробел / 249 без — single оставляем как есть).
      return `В${leafSpacing || valueListIsMulti(list) ? ' ' : ''}${list}`;
    }
    if (/^ИЕРАРХИИ ?\(/.test(param)) {
      return 'В ИЕРАРХИИ' + (leafSpacing ? ' ' : '') + param.slice('ИЕРАРХИИ'.length).replace(/^ ?\(/, '(');
    }
  }
  return `${op} ${param}`;
}

/**
 * `param` — сбалансированный список `( … )` без хвостовых символов после внешней
 * закрывающей скобки. Используется, чтобы НЕ сплющивать param, в который парсер
 * ошибочно затянул хвост запроса (`(&X)\n\nУПОРЯДОЧИТЬ ПО …`).
 */
function isPureBalancedList(param: string): boolean {
  if (param[0] !== '(') return false;
  let depth = 0;
  for (let i = 0; i < param.length; i++) {
    const ch = param[i];
    if (ch === '(') depth++;
    else if (ch === ')') {
      depth--;
      if (depth === 0) return i === param.length - 1;
    }
  }
  return false;
}

/**
 * Список значений `(…)` оператора `В` содержит 2+ элемента верхнего уровня?
 * Считает запятые вне вложенных скобок (ЗНАЧЕНИЕ(…) и т.п. — один элемент).
 * Подзапрос (`(ВЫБРАТЬ …)`) — не список значений, трактуется как один элемент.
 */
function valueListIsMulti(param: string): boolean {
  const inner = param.slice(1, param.lastIndexOf(')'));
  if (/(^|[^\p{L}\p{N}_])ВЫБРАТЬ([^\p{L}\p{N}_]|$)/u.test(inner)) return false;
  let depth = 0;
  for (const ch of inner) {
    if (ch === '(') depth++;
    else if (ch === ')') depth--;
    else if (ch === ',' && depth === 0) return true;
  }
  return false;
}

/**
 * Лист-условие ГДЕ верхнего уровня (НЕ внутри подзапроса/VT-параметра) вида ПРОСТОГО
 * членства `<путь-поля> В (<один элемент>)` / `… В ИЕРАРХИИ (<один элемент>)` оракул
 * печатает БЕЗ пробела перед скобкой (`В(&П)`) — как структурный путь renderOperatorRhs.
 * Срабатывает СТРОГО на всём листе: ведущее `НЕ` (`НЕ Поле В (&П)`), многоэлементный
 * список (`В (a, b)`), подзапрос (`В (ВЫБРАТЬ …)`) и любые иные операторы пробел
 * СОХРАНЯЮТ (оракул их печатает с пробелом). Многострочный лист (подзапрос/VT-параметр —
 * контекст leafSpacing) не трогается. Применяется к простому листу; формат-выражения
 * сюда не попадают.
 */
export function tightenLeafInOperator(text: string): string {
  if (text.includes('\n')) return text;
  // Весь лист — `<путь> В[ ИЕРАРХИИ] (<группа>)` с хвостовым `)` в самом конце.
  const m = /^([\p{L}_][\p{L}\p{N}_]*(?:\.[\p{L}_][\p{L}\p{N}_]*)*)\s+(В(?:\s+ИЕРАРХИИ)?)\s+(\(.*\))$/u.exec(text);
  if (!m) return text;
  const group = m[3];
  // Группа должна быть СБАЛАНСИРОВАННОЙ парой (одиночный элемент), не списком/подзапросом.
  if (!isPureBalancedList(group)) return text;
  if (valueListIsMulti(group)) return text;
  // Оракул убирает пробел ТОЛЬКО когда единственный элемент — ПАРАМЕТР `(&X)`.
  // Для значения/выражения (`(ЗНАЧЕНИЕ(…))`, `(ВЫРАЗИТЬ(…))`, литерал) пробел СОХРАНЯЕТСЯ.
  if (!/^\(\s*&[\p{L}_][\p{L}\p{N}_]*\s*\)$/u.test(group)) return text;
  return `${m[1]} ${m[2].replace(/\s+/g, ' ')}${group}`;
}

/**
 * Удаляет незначащие ведущие нули из целой части числового литерала:
 * `01` → `1`, `007` → `7`, `00` → `0`, `00.5` → `0.5`. Дробную часть не трогает.
 */
function stripLeadingZeros(value: string): string {
  const dot = value.indexOf('.');
  const intPart = dot >= 0 ? value.slice(0, dot) : value;
  const frac = dot >= 0 ? value.slice(dot) : '';
  const trimmed = intPart.replace(/^0+(?=\d)/, '');
  return trimmed + frac;
}

/**
 * Унарен ли минус `sig[idx]` (значение `-`). Минус БИНАРЕН (вычитание), если перед
 * ним стоит ОПЕРАНД: число/строка/параметр/дата, закрывающая `)`, либо
 * идентификатор/ключевое слово, НЕ являющееся зарезервированным разделителем
 * (т. е. имя поля). Иначе (начало листа, `(`, `,`, оператор сравнения/арифметики,
 * зарезервированное слово) минус УНАРЕН.
 */
function isUnaryMinusAt(sig: Token[], idx: number): boolean {
  const prev = sig[idx - 1];
  if (!prev) return true; // начало листа
  if (prev.type === 'number' || prev.type === 'string' ||
      prev.type === 'param' || prev.type === 'date') return false;
  if (prev.type === 'punct') {
    if (prev.value === ')') return false; // `…) - X` — вычитание
    return true; // `(`, `,`, операторы сравнения/арифметики и пр.
  }
  // ident / keyword: сегмент пути после точки — заведомо имя поля (операнд) ⇒ бинарный.
  const pp = sig[idx - 2];
  if (pp && pp.type === 'punct' && pp.value === '.') return false;
  // Прочее: зарезервированное слово-разделитель ⇒ унарный, имя поля ⇒ бинарный.
  return UNARY_MINUS_PREV_WORDS.has((prev.text ?? prev.value).toUpperCase());
}

/**
 * Является ли скобочная группа, открываемая `sig[openIdx]` (значение `(`), ТЮПЛОМ —
 * списком элементов через запятую верхнего уровня (`(a, b, …)`), а НЕ булевой группой
 * (`(X = Y …)`). Тюплом считаем, если внутри ВЕРХНЕГО уровня скобок встречается запятая
 * РАНЬШЕ любого оператора сравнения (= <> < > <= >=). Конструктор у тюпла `НЕ (a, b) В …`
 * пробел перед `(` сохраняет, у булевой группы `НЕ(…)` — убирает.
 */
function isTupleGroupAt(sig: Token[], openIdx: number): boolean {
  let depth = 0;
  for (let k = openIdx; k < sig.length; k++) {
    const t = sig[k];
    if (t.type === 'punct' && t.value === '(') { depth++; continue; }
    if (t.type === 'punct' && t.value === ')') { depth--; if (depth === 0) return false; continue; }
    if (depth !== 1) continue;
    if (t.type === 'punct' && t.value === ',') return true;
    if (t.type === 'punct' && COMPARISON_PUNCT.has(t.value)) return false;
  }
  return false;
}

export function normalizeLeafWhitespace(raw: string): string {
  if (!raw) return raw;
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  const sig = toks.filter((t) => t.type !== 'eof');

  const isCmp = (t: Token): boolean => t.type === 'punct' && COMPARISON_PUNCT.has(t.value);

  // Оператор включения `В (…)` / `В ИЕРАРХИИ (…)` в листовом (произвольном)
  // выражении конструктор 1С печатает С пробелом перед скобкой, даже если
  // разработчик написал `В(…)`. (Простые структурированные условия идут другим
  // путём — renderOperatorRhs, где у одиночного элемента пробела нет.)
  const isInOpWord = (t: Token): boolean =>
    (t.type === 'keyword' || t.type === 'ident') &&
    (t.value.toUpperCase() === 'В' || t.value.toUpperCase() === 'ИЕРАРХИИ');

  // Правки промежутков (gap) между соседними токенами, применяем справа налево.
  const edits: Array<{ from: number; to: number; text: string }> = [];

  // Нормализация числовых литералов: удаление незначащих ведущих нулей
  // (`01` → `1`, `00` → `0`), как делает конструктор 1С (напр. `ДАТАВРЕМЯ(2000, 1, 1)`).
  for (const t of sig) {
    if (t.type !== 'number') continue;
    const v = t.value;
    const stripped = stripLeadingZeros(v);
    if (stripped !== v) {
      edits.push({ from: t.pos, to: t.pos + v.length, text: stripped });
    }
  }

  for (let i = 0; i < sig.length - 1; i++) {
    const a = sig[i];
    const b = sig[i + 1];
    const gapFrom = a.pos + (a.text ?? a.value).length;
    const gapTo = b.pos;
    if (gapTo <= gapFrom) {
      // Нет пробела между токенами. Пробел нужен, если один из них — оператор
      // сравнения, либо предыдущий токен — запятая (`(1,1)` → `(1, 1)`). Запятую
      // перед `)` не разделяем (висячих запятых в выражениях нет, но на всякий случай).
      const needSpace =
        isCmp(a) || isCmp(b) ||
        (a.type === 'punct' && a.value === ',' && !(b.type === 'punct' && b.value === ')')) ||
        (isInOpWord(a) && b.type === 'punct' && b.value === '(');
      if (needSpace) edits.push({ from: gapFrom, to: gapTo, text: ' ' });
      continue;
    }
    const gap = raw.slice(gapFrom, gapTo);
    if (gap.includes('\n')) continue; // многострочный промежуток — не трогаем
    // Промежуток ПЕРЕД оператором включения `В`/`В ИЕРАРХИИ` конструктор печатает
    // ровно одним пробелом, даже если разработчик отбил его табом (`Поле\tВ (…)` →
    // `Поле В (…)`). Внутренний таб перед `В` (не ведущий отступ строки — `a` не пуст)
    // схлопываем к одному пробелу (фаза 6.16.67). Прочие правила табы НЕ трогают.
    if (isInOpWord(b) && b.value.toUpperCase() === 'В' && gap !== ' ') {
      edits.push({ from: gapFrom, to: gapTo, text: ' ' });
      continue;
    }
    if (isCmp(a) || isCmp(b)) {
      if (gap !== ' ') edits.push({ from: gapFrom, to: gapTo, text: ' ' });
      continue;
    }
    if (a.type === 'punct' && a.value === ',') {
      if (gap !== ' ') edits.push({ from: gapFrom, to: gapTo, text: ' ' });
      continue;
    }
    // Пробел ПЕРЕД запятой конструктор убирает (`Количество , 0` → `Количество, 0`).
    // Таб не трогаем (значимый отступ; запятая в начале строки в листе не встречается,
    // но из осторожности). Фаза 6.16.67.
    if (b.type === 'punct' && b.value === ',' && !gap.includes('\t')) {
      if (gap !== '') edits.push({ from: gapFrom, to: gapTo, text: '' });
      continue;
    }
    // Пробел после УНАРНОГО минуса конструктор убирает (`ИНАЧЕ -Поле`, `(-1)`),
    // тогда как бинарное вычитание сохраняет пробелы (`a - b`). Минус унарен, если
    // перед ним нет операнда: начало листа, `(`, `,`, оператор сравнения/арифметики
    // или зарезервированное слово-разделитель (UNARY_MINUS_PREV_WORDS). Табы в
    // промежутке не трогаем (значимый отступ).
    if (a.type === 'punct' && a.value === '-' && !gap.includes('\t') && isUnaryMinusAt(sig, i)) {
      if (gap !== '') edits.push({ from: gapFrom, to: gapTo, text: '' });
      continue;
    }
    // Пробел сразу ПОСЛЕ открывающей `(` конструктор 1С убирает (`( X` → `(X`,
    // `В ( "112"` → `В ("112"`). Табы в промежутке не трогаем (форматирование).
    if (a.type === 'punct' && a.value === '(' && !gap.includes('\t')) {
      if (gap !== '') edits.push({ from: gapFrom, to: gapTo, text: '' });
      continue;
    }
    // Пробел ПЕРЕД закрывающей `)` убирается (`X )` → `X)`), КРОМЕ квирка предиката
    // `… ЕСТЬ [НЕ] NULL )` — конструктор сохраняет ровно один хвостовой пробел перед
    // скобкой (см. appendIsNotNullTrailingSpace). Тогда нормализуем к одному пробелу.
    if (b.type === 'punct' && b.value === ')' && !gap.includes('\t')) {
      const aUp = (a.text ?? a.value).toUpperCase();
      const prevW = sig[i - 1];
      const isNullTail = aUp === 'NULL' && !!prevW &&
        (prevW.value.toUpperCase() === 'НЕ' || prevW.value.toUpperCase() === 'ЕСТЬ');
      const want = isNullTail ? ' ' : '';
      if (gap !== want) edits.push({ from: gapFrom, to: gapTo, text: want });
      continue;
    }
    // Пробел между ИМЕНЕМ АГРЕГАТА и открывающей `(` конструктор убирает
    // (`КОЛИЧЕСТВО (…)` → `КОЛИЧЕСТВО(…)`). Ограничиваемся агрегатами: прочие слова
    // FUNCTION_WORDS включают булевы операторы (И/ИЛИ/НЕ/В/МЕЖДУ…), у которых `(` —
    // группирующая/тюплевая, и оракул пробел перед ней СОХРАНЯЕТ (`И (…)`, `НЕ (…, …) В`).
    if (b.type === 'punct' && b.value === '(' &&
        (a.type === 'ident' || a.type === 'keyword') && !gap.includes('\t')) {
      const aUp = (a.text ?? a.value).toUpperCase();
      if ((AGGREGATE_WORDS.has(aUp) || CALL_NOSPACE_WORDS.has(aUp)) && gap !== '') {
        edits.push({ from: gapFrom, to: gapTo, text: '' });
        continue;
      }
      // Параметризованный примитивный тип в приведении (`КАК СТРОКА (10)` →
      // `КАК СТРОКА(10)`, `КАК ЧИСЛО (11, 0)`): пробел перед `(` конструктор убирает.
      // Гейтим по предыдущему слову `КАК` (контекст приведения), чтобы не задеть поле
      // с именем СТРОКА/ЧИСЛО/… перед группирующей скобкой. Фаза 6.16.67.
      if (PRIMITIVE_TYPE_WORDS.has(aUp) && gap !== '') {
        const prevW = sig[i - 1];
        if (prevW && (prevW.text ?? prevW.value).toUpperCase() === 'КАК') {
          edits.push({ from: gapFrom, to: gapTo, text: '' });
          continue;
        }
      }
      // `НЕ (` перед БУЛЕВОЙ группой конструктор печатает БЕЗ пробела (`НЕ(X = …)`,
      // `НЕ(X В (…) ИЛИ …)`), тогда как ТЮПЛ `НЕ (a, b) В …` (запятая верхнего уровня
      // прежде оператора сравнения) пробел СОХРАНЯЕТ. Различаем по содержимому группы.
      if (aUp === 'НЕ' && gap !== '' && !isTupleGroupAt(sig, i + 1)) {
        edits.push({ from: gapFrom, to: gapTo, text: '' });
        continue;
      }
    }
    // Схлопывание серий из 2+ пробелов в один. Табы в однострочном промежутке
    // не трогаем (могут быть значимым отступом форматирования разработчика).
    if (/ {2,}/.test(gap) && !gap.includes('\t')) {
      const collapsed = gap.replace(/ {2,}/g, ' ');
      if (collapsed !== gap) edits.push({ from: gapFrom, to: gapTo, text: collapsed });
    }
  }

  if (!edits.length) return raw;
  edits.sort((x, y) => y.from - x.from);
  let out = raw;
  for (const e of edits) {
    out = out.slice(0, e.from) + e.text + out.slice(e.to);
  }
  return out;
}

/**
 * Приводит к верхнему регистру РАСПОЗНАННЫЕ ключевые слова в листе выражения,
 * сохраняя всё остальное (идентификаторы, строки, параметры, пробелы) дословно.
 * Применяется к каждому листовому срезу перед выводом.
 */
/**
 * Имя функции, чьему списку аргументов непосредственно принадлежит токен sig[idx]:
 * идёт назад по значимым токенам, отслеживая баланс скобок, до «лишней» открывающей
 * скобки текущего уровня; токен-слово прямо перед ней — имя функции. Возвращает true,
 * если это имя (в верхнем регистре) входит в `names`.
 */
function enclosingFunctionIs(sig: Token[], idx: number, names: Set<string>): boolean {
  let depth = 0;
  for (let k = idx - 1; k >= 0; k--) {
    const t = sig[k];
    if (t.type === 'punct' && t.value === ')') depth++;
    else if (t.type === 'punct' && t.value === '(') {
      if (depth === 0) {
        const fn = sig[k - 1];
        return !!fn && (fn.type === 'ident' || fn.type === 'keyword') && names.has(tokUpper(fn));
      }
      depth--;
    }
  }
  return false;
}

/**
 * Канонизация лексики листа (фаза 6.15.10): конструктор 1С нормализует ряд
 * англоязычных/перестановочных форм предикатов внутри листового выражения. Правила
 * подтверждены MCP-пробами `validate_query`:
 *   1) `IS NULL`   → `ЕСТЬ NULL`   (англоязычная форма предиката ЕСТЬ NULL);
 *   2) `ISNULL(`   → `ЕСТЬNULL(`   (англоязычное имя функции ЕСТЬNULL);
 *   3) `x НЕ В (…)` → `НЕ x В (…)`  (отрицание оператора В выносится перед операндом).
 * Применяется к листу до нормализации регистра/пробелов (`normalizeLeafCase`). Замены
 * делаются по позициям токенов справа налево, исходные пробелы между токенами не
 * затрагиваются (кроме переноса `НЕ ` в правиле 3). Многострочный лист в правило 3 не
 * попадает: предикат `В` приходит листом-сравнением без переносов строк.
 */
export function canonicalizeLeafLexemes(raw: string): string {
  if (!raw) return raw;
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length === 0) return raw;
  const upOf = (t: Token): string => (t.text ?? t.value).toUpperCase();
  const isW = (t: Token | undefined): boolean => !!t && (t.type === 'ident' || t.type === 'keyword');
  // Сегмент пути после точки трогать нельзя (это идентификатор).
  const afterDot = (k: number): boolean => {
    const p = sig[k - 1];
    return !!p && p.type === 'punct' && p.value === '.';
  };

  let out = raw;

  // Правила 1 и 2 — позиционные текстовые замены (длина меняется), справа налево.
  type Repl = { pos: number; len: number; to: string };
  const repls: Repl[] = [];
  for (let k = 0; k < sig.length; k++) {
    const t = sig[k];
    if (!isW(t) || afterDot(k)) continue;
    const u = upOf(t);
    const text = t.text ?? t.value;
    // 2) ISNULL( → ЕСТЬNULL(
    if (u === 'ISNULL') {
      const nx = sig[k + 1];
      if (nx && nx.type === 'punct' && nx.value === '(') {
        repls.push({ pos: t.pos, len: text.length, to: 'ЕСТЬNULL' });
      }
      continue;
    }
    // 1) IS NULL → ЕСТЬ NULL (NULL приводит к ВЕРХнему регистру normalizeLeafCase).
    if (u === 'IS') {
      const nx = sig[k + 1];
      if (nx && isW(nx) && upOf(nx) === 'NULL') {
        repls.push({ pos: t.pos, len: text.length, to: 'ЕСТЬ' });
      }
    }
  }
  if (repls.length) {
    repls.sort((a, b) => b.pos - a.pos);
    for (const r of repls) out = out.slice(0, r.pos) + r.to + out.slice(r.pos + r.len);
  }

  // 3) x НЕ В (…) → НЕ x В (…), а также x НЕ ПОДОБНО y → НЕ x ПОДОБНО y. Срабатывает
  //    только на однострочном листе-сравнении (без переносов): ищем `НЕ`, за которым
  //    непосредственно следует оператор членства `В` или `ПОДОБНО`, при наличии
  //    операнда слева. Переносим `НЕ ` в начало операнда (= начало листа). Фаза 6.16.76.
  if (!out.includes('\n')) {
    let toks2: Token[];
    try {
      toks2 = tokenize(out);
    } catch {
      return out;
    }
    const sig2 = toks2.filter((t) => t.type !== 'eof');
    for (let k = 1; k < sig2.length - 1; k++) {
      const t = sig2[k];
      if (!isW(t) || upOf(t) !== 'НЕ') continue;
      const nx = sig2[k + 1];
      const nxU = nx ? upOf(nx) : '';
      const isVOp = !!nx && nx.type === 'keyword' && (nxU === 'В' || nxU === 'ПОДОБНО');
      if (!isVOp) continue;
      // Операнд — всё от начала листа до токена `НЕ` (лист атомарен: верхнеуровневых
      // булевых операторов в нём нет, они расщепляются раньше).
      const operandStart = sig2[0].pos;
      if (t.pos <= operandStart) continue;
      const neEnd = t.pos + (t.text ?? t.value).length;
      // Кусок между `НЕ` и оператором `В` (обычно один пробел) — сохраняем как разделитель.
      const before = out.slice(operandStart, t.pos).replace(/\s+$/u, '');
      out = out.slice(0, operandStart) + 'НЕ ' + before + out.slice(neEnd);
      break; // одно вхождение на лист
    }
  }

  return out;
}

/**
 * Канонизация операндов сравнения для слотов ГДЕ/ИМЕЮЩИЕ: ПАРАМЕТР/ЛИТЕРАЛ слева,
 * ПОЛЕ справа — конструктор печатает поле слева, параметр/литерал справа
 * (`&П = Поле` → `Поле = &П`, `5 < Поле.Сумма` → `Поле.Сумма > 5`). По всему
 * golden-корпусу параметр/литерал НИКОГДА не остаётся слева от сравнения с полем
 * (param-on-right=16, param-on-left=0). НЕ применяется к слоту ПО — там конструктор
 * порядок операндов СОХРАНЯЕТ (`ПО (&П = Поле)`).
 *
 * Срабатывает СТРОГО на однострочном листе РОВНО из `операнд ОП поле`, где:
 *   - левый операнд — ОДИН токен: `&параметр` ИЛИ литерал (строка/число/дата);
 *   - оператор — сравнение `= <> < > <= >=` (оператор зеркалится: `<`↔`>`, `<=`↔`>=`);
 *   - правый операнд — путь-поле `ИДЕНТ(.ИДЕНТ)*`, причём НЕ литерал-ключевое слово
 *     (`ЛОЖЬ`/`ИСТИНА`/`НЕОПРЕДЕЛЕНО`/`NULL` остаются справа — это не поле).
 * Фаза 6.16.76.
 */
const CMP_MIRROR: Record<string, string> = { '<': '>', '>': '<', '<=': '>=', '>=': '<=', '=': '=', '<>': '<>' };
const LITERAL_KEYWORDS = new Set(['ЛОЖЬ', 'ИСТИНА', 'НЕОПРЕДЕЛЕНО', 'NULL']);
export function canonicalizeComparisonOperands(raw: string): string {
  if (!raw || raw.includes('\n')) return raw;
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length < 3) return raw;
  const lhs = sig[0];
  const op = sig[1];
  const isLit = lhs.type === 'param' || lhs.type === 'string' ||
    lhs.type === 'number' || lhs.type === 'date';
  const isCmpOp = op.type === 'punct' && COMPARISON_PUNCT_SET.has(op.value);
  if (!isLit || !isCmpOp) return raw;
  // Правый операнд (от sig[2] до конца) — путь-поле: ИДЕНТ, далее чередование `.ИДЕНТ`.
  for (let k = 2; k < sig.length; k++) {
    const tk = sig[k];
    if ((k - 2) % 2 === 0) {
      if (tk.type !== 'ident' && tk.type !== 'keyword') return raw;
      // Литерал-слово (ЛОЖЬ/ИСТИНА/НЕОПРЕДЕЛЕНО/NULL) — это НЕ поле; лексер метит его
      // как ident, поэтому проверяем по значению независимо от типа токена.
      if (k === 2 && sig.length === 3 && LITERAL_KEYWORDS.has((tk.text ?? tk.value).toUpperCase())) return raw;
    } else if (!(tk.type === 'punct' && tk.value === '.')) {
      return raw;
    }
  }
  if ((sig.length - 2) % 2 !== 1) return raw; // RHS не должен заканчиваться точкой
  const rhsText = raw.slice(sig[2].pos).replace(/\s+$/u, '');
  const lhsText = lhs.text ?? lhs.value;
  const opText = CMP_MIRROR[op.value] ?? op.value;
  return `${rhsText} ${opText} ${lhsText}`;
}

// --- Переотрисовка арифметики листа (фаза 6.15.11a) -------------------------
//
// Конструктор 1С переотрисовывает арифметические выражения листа в каноническом
// виде (подтверждено MCP validate_query):
//   - бинарные операторы `+ - * / %` окружаются пробелами;
//   - лишние скобки снимаются по приоритету/ассоциативности (левый операнд `/`,`-`
//     без скобок: `(a - 1) - 2` → `a - 1 - 2`; правый — сохраняет: `a - (1 - 2)`);
//   - вызов-приведение `ВЫРАЗИТЬ(…)`, стоящий ОПЕРАНДОМ арифметики, оборачивается
//     в скобки: `ВЫРАЗИТЬ(…) * &П` → `(ВЫРАЗИТЬ(…)) * &П` (расширение правила
//     6.15.12 со сравнения на арифметику);
//   - унарный минус/плюс к пробелам оператора не относится (`-Поле`, `- -1`).
// Реализация — самостоятельный рекурсивный парсер арифметики; при ЛЮБОМ незнакомом
// токене (сравнение, булевы операторы, ЕСТЬ/МЕЖДУ/В/ПОДОБНО, `[` `?` `@`, ВЫБОР и
// т. п.) возвращает исходный текст без изменений (чтобы не задеть прочие листья).
// Регистр/числа/прочее НЕ трогает — этим занимается `normalizeLeafCase` после.

interface ArithNode {
  /** Готовый текст узла без внешних скобок. */
  text: string;
  /** Приоритет верхнего оператора узла: 2 = `* / %`, 1 = `+ -`, 3 = атом/унарный. */
  prec: number;
  /** Узел — голый вызов `ВЫРАЗИТЬ(…)` (особое правило обёртки операнда). */
  bareCast: boolean;
}

const ARITH_ADD = new Set(['+', '-']);
const ARITH_MUL = new Set(['*', '/', '%']);
// Токены, при встрече которых арифметический парсер сдаётся (не наш случай).
const ARITH_STOP_PUNCT = new Set(['<', '>', '=', '<=', '>=', '<>', '[', ']', '?', '@', ';']);
const ARITH_STOP_WORDS = new Set([
  'ИЛИ', 'И', 'НЕ', 'ВЫБОР', 'КОГДА', 'ТОГДА', 'ИНАЧЕ', 'КОНЕЦ', 'ЕСТЬ',
  'МЕЖДУ', 'В', 'ПОДОБНО', 'ССЫЛКА', 'СПЕЦСИМВОЛ', 'ИЕРАРХИИ',
]);

class ArithError extends Error {}

class ArithReprinter {
  private i = 0;
  constructor(private readonly sig: Token[]) {}

  private peek(): Token | undefined { return this.sig[this.i]; }
  private next(): Token { return this.sig[this.i++]; }
  private val(t: Token | undefined): string { return t ? (t.text ?? t.value) : ''; }

  /** Полный разбор: выражение должно занять все токены. */
  parseAll(): string {
    const node = this.parseExpr();
    if (this.i !== this.sig.length) throw new ArithError('хвост');
    return node.text;
  }

  private parseExpr(): ArithNode {
    let left = this.parseTerm();
    while (this.peek() && this.peek()!.type === 'punct' && ARITH_ADD.has(this.peek()!.value)) {
      const op = this.next().value;
      const right = this.parseTerm();
      left = {
        text: `${this.wrap(left, 1, 'left', op)} ${op} ${this.wrap(right, 1, 'right', op)}`,
        prec: 1,
        bareCast: false,
      };
    }
    return left;
  }

  private parseTerm(): ArithNode {
    let left = this.parseUnary();
    while (this.peek() && this.peek()!.type === 'punct' && ARITH_MUL.has(this.peek()!.value)) {
      const op = this.next().value;
      const right = this.parseUnary();
      left = {
        text: `${this.wrap(left, 2, 'left', op)} ${op} ${this.wrap(right, 2, 'right', op)}`,
        prec: 2,
        bareCast: false,
      };
    }
    return left;
  }

  private parseUnary(): ArithNode {
    const t = this.peek();
    if (t && t.type === 'punct' && (t.value === '-' || t.value === '+')) {
      this.next();
      const operand = this.parseUnary();
      // Унарный минус/плюс без пробела: `-Поле`, `- -1` (родитель уже отделил).
      return { text: `${t.value}${this.atomText(operand)}`, prec: 3, bareCast: false };
    }
    return this.parsePrimary();
  }

  /** Операнд унарного оператора в скобках, если это бинарная арифметика. */
  private atomText(n: ArithNode): string {
    // 6.16.69: голый ВЫРАЗИТЬ(…) под унарным минусом всегда в скобках:
    // `-(ВЫРАЗИТЬ(…))`, как и в wrap(); `-Поле`/`- -1` остаются без скобок.
    return (n.bareCast || n.prec < 3) ? `(${n.text})` : n.text;
  }

  private parsePrimary(): ArithNode {
    const t = this.peek();
    if (!t) throw new ArithError('конец');
    if (t.type === 'punct' && t.value === '(') {
      this.next();
      const inner = this.parseExpr();
      const close = this.next();
      if (!close || !(close.type === 'punct' && close.value === ')')) throw new ArithError('нет )');
      // Скобочная группа: возвращаем содержимое, родитель решит про скобки.
      return inner;
    }
    if (t.type === 'number' || t.type === 'string' || t.type === 'param' || t.type === 'date') {
      this.next();
      return { text: this.val(t), prec: 3, bareCast: false };
    }
    if (t.type === 'ident' || t.type === 'keyword') {
      // Стоп-слова булевой/предикатной логики — не арифметика.
      if (ARITH_STOP_WORDS.has((t.text ?? t.value).toUpperCase())) throw new ArithError('стоп-слово');
      return this.parseNameOrCall();
    }
    if (t.type === 'punct' && ARITH_STOP_PUNCT.has(t.value)) throw new ArithError('стоп-пункт');
    throw new ArithError('неизвестно');
  }

  /** Точечный путь `Имя(.Имя)*` или вызов `Имя(arg, …)`. */
  private parseNameOrCall(): ArithNode {
    const headTok = this.next();
    const head = this.val(headTok);
    // Путь: Имя.Имя…
    let path = head;
    while (this.peek() && this.peek()!.type === 'punct' && this.peek()!.value === '.') {
      this.next();
      const seg = this.next();
      if (!seg || (seg.type !== 'ident' && seg.type !== 'keyword' && seg.type !== 'number')) {
        throw new ArithError('сегмент пути');
      }
      path += '.' + this.val(seg);
    }
    // Вызов функции? Открывающая скобка СРАЗУ за именем (без точки).
    if (path === head && this.peek() && this.peek()!.type === 'punct' && this.peek()!.value === '(') {
      this.next(); // (
      const args = this.parseArgList();
      const close = this.next();
      if (!close || !(close.type === 'punct' && close.value === ')')) throw new ArithError('нет ) вызова');
      const isCast = head.toUpperCase() === 'ВЫРАЗИТЬ';
      return { text: `${head}(${args.join(', ')})`, prec: 3, bareCast: isCast };
    }
    return { text: path, prec: 3, bareCast: false };
  }

  /** Список аргументов вызова: каждый — арифметика, опц. с `КАК <тип>` (ВЫРАЗИТЬ). */
  private parseArgList(): string[] {
    const args: string[] = [];
    if (this.peek() && this.peek()!.type === 'punct' && this.peek()!.value === ')') return args;
    for (;;) {
      args.push(this.parseArg());
      const t = this.peek();
      if (t && t.type === 'punct' && t.value === ',') { this.next(); continue; }
      break;
    }
    return args;
  }

  /** Аргумент вызова: арифм. выражение и опц. `КАК <тип-выражение>` (приведение). */
  private parseArg(): string {
    const expr = this.parseExpr();
    const t = this.peek();
    if (t && (t.type === 'keyword' || t.type === 'ident') && (t.text ?? t.value).toUpperCase() === 'КАК') {
      this.next(); // КАК
      // Тип — это вызов/имя (`ЧИСЛО(11, 0)`, `СТРОКА(10)`, ссылочный тип). Печатаем
      // через тот же примитив (parseNameOrCall) для нормализации запятых внутри.
      const type = this.parseNameOrCall();
      return `${expr.text} КАК ${type.text}`;
    }
    return expr.text;
  }

  /**
   * Решает обрамление дочернего операнда скобками. `parentPrec` — приоритет
   * родительского оператора; `side` — слева/справа от него.
   *   - Голый ВЫРАЗИТЬ-операнд арифметики всегда в скобках (особое правило 1С).
   *   - prec < parentPrec → нужны скобки (защита приоритета).
   *   - prec == parentPrec и правый операнд под `- /` (non-assoc) → скобки.
   */
  private wrap(n: ArithNode, parentPrec: number, side: 'left' | 'right', op: string): string {
    if (n.bareCast) return `(${n.text})`;
    if (n.prec < parentPrec) return `(${n.text})`;
    // Правый операнд при равном приоритете ВСЕГДА сохраняет скобки: конструктор 1С
    // не снимает их даже у ассоциативных `+`/`*` (`a + (b - c)`, `a + (b + c)`,
    // `a * (b * c)`, `a * (b / c)` — все сохранены, MCP, фаза 6.15.20). Левый операнд
    // при равном приоритете скобок не требует (левая ассоциативность):
    // `(a - 1) - 2` → `a - 1 - 2`, `(a + b) + c` → `a + b + c`.
    if (n.prec === parentPrec && side === 'right') {
      return `(${n.text})`;
    }
    return n.text;
  }
}

// Операторы сравнения/предиката, в чьём ОКРУЖЕНИИ скобки вокруг операнда избыточны
// (булев/предикатный слой; конструктор 1С их снимает). НЕ включает `В`/`В ИЕРАРХИИ`
// (там `(…)` — список значений / подзапрос, скобки обязательны) и `СПЕЦСИМВОЛ`.
const PRED_NEIGHBOR_WORDS = new Set([
  'НЕ', 'И', 'ИЛИ', 'КОГДА', 'ТОГДА', 'ИНАЧЕ', 'ЕСТЬ', 'МЕЖДУ', 'ПОДОБНО', 'ССЫЛКА',
]);
const COMPARISON_PUNCT_SET = new Set(['=', '<>', '<', '>', '<=', '>=']);
const ARITH_PUNCT_SET = new Set(['+', '-', '*', '/', '%']);

/**
 * Скобка `(` слева от операнда является ВЫЗОВОМ функции / приведения (`ВЫРАЗИТЬ(`,
 * `СУММА(`, `Поле.Метод(`), а НЕ группирующей: предыдущий значимый токен — имя
 * (идентификатор/ключевое слово-имя/параметр/число/строка) либо закрывающая `)`.
 */
function isCallOpenContext(prev: Token | undefined): boolean {
  if (!prev) return false;
  // Слово-оператор предиката (НЕ/И/ИЛИ/ЕСТЬ/…) — НЕ имя функции, даже будучи ident.
  if ((prev.type === 'ident' || prev.type === 'keyword') && PRED_NEIGHBOR_WORDS.has(prev.value.toUpperCase())) {
    return false;
  }
  if (prev.type === 'ident' || prev.type === 'param' || prev.type === 'number' || prev.type === 'string') {
    return true;
  }
  if (prev.type === 'punct' && prev.value === ')') return true;
  // Ключевое слово-функция (СУММА/ВЫРАЗИТЬ/…) непосредственно перед `(` — вызов.
  if (prev.type === 'keyword' && FUNCTION_WORDS.has(prev.value.toUpperCase())) return true;
  return false;
}

/**
 * Снимает ИЗБЫТОЧНЫЕ скобки вокруг операнда в булевом/предикатном слое листа, как это
 * делает конструктор 1С (подтверждено живым оракулом): `НЕ (Поле В (…))` → `НЕ Поле В (…)`,
 * `КОГДА (X = Y)` (через лист) → `X = Y`, `Поле = (&П)` → `Поле = &П`, `(Поле) = &П` →
 * `Поле = &П`, `(Поле ЕСТЬ NULL) КАК Алиас` → `Поле ЕСТЬ NULL КАК Алиас`, `ТОГДА (a - b)`
 * (через лист) → `a - b`.
 *
 * Снимаем пару `( C )` ТОЛЬКО когда:
 *   - `(` не открывает вызов функции (isCallOpenContext);
 *   - содержимое C сбалансировано и без верхнеуровневой запятой (иначе это список);
 *   - НИ левый, НИ правый сосед пары не является арифметическим оператором `+ - * / %`
 *     (чтобы НИКОГДА не менять приоритет арифметики — этим занят reprintLeafArithmetic);
 *   - левый сосед — начало строки, оператор сравнения, или слово-предикат
 *     (НЕ/И/ИЛИ/КОГДА/ТОГДА/ИНАЧЕ/ЕСТЬ/МЕЖДУ/ПОДОБНО/ССЫЛКА), или `(`;
 *   - правый сосед — конец, `КАК`, `)`, `,`, оператор сравнения, или слово-предикат.
 * Работает построчно (однострочный лист); многострочные листья не трогаем.
 */
export function stripRedundantLeafParens(raw: string): string {
  if (!raw || raw.includes('\n') || !raw.includes('(')) return raw;
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length < 2) return raw;

  const isPredWord = (t: Token | undefined): boolean =>
    !!t && (t.type === 'keyword' || t.type === 'ident') && PRED_NEIGHBOR_WORDS.has(t.value.toUpperCase());
  const isCmpPunct = (t: Token | undefined): boolean =>
    !!t && t.type === 'punct' && COMPARISON_PUNCT_SET.has(t.value);
  const isArithPunct = (t: Token | undefined): boolean =>
    !!t && t.type === 'punct' && ARITH_PUNCT_SET.has(t.value);
  const isOpenParen = (t: Token | undefined): boolean =>
    !!t && t.type === 'punct' && t.value === '(';

  // Левый сосед пары допускает снятие скобок (предикатный/сравнительный контекст).
  const leftOk = (prev: Token | undefined): boolean =>
    !prev || isCmpPunct(prev) || isPredWord(prev) || isOpenParen(prev);
  // Оператор членства `В` / `В ИЕРАРХИИ` как ПРАВЫЙ сосед: его ЛЕВЫЙ операнд (значение)
  // конструктор печатает без обёртки (`(ВЫРАЗИТЬ(…)) В (&М)` → `ВЫРАЗИТЬ(…) В (&М)`),
  // тогда как у сравнения обёртку сохраняет. `В` не входит в PRED_NEIGHBOR_WORDS
  // (там `(` справа — список значений), поэтому обрабатываем его отдельно (фаза 6.16.77).
  const isMembershipWord = (t: Token | undefined): boolean =>
    !!t && (t.type === 'keyword' || t.type === 'ident') && t.value.toUpperCase() === 'В';
  // Правый сосед пары допускает снятие скобок.
  const rightOk = (nx: Token | undefined): boolean => {
    if (!nx) return true;
    if (nx.type === 'punct' && (nx.value === ')' || nx.value === ',')) return true;
    if (nx.type === 'keyword' && nx.value.toUpperCase() === 'КАК') return true;
    if (isCmpPunct(nx)) return true;
    if (isPredWord(nx)) return true;
    if (isMembershipWord(nx)) return true;
    return false;
  };

  // Сопоставление скобок по индексам sig: match[openIdx] = closeIdx (и наоборот).
  const match = new Map<number, number>();
  const stack: number[] = [];
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    if (t.type === 'punct' && t.value === '(') stack.push(i);
    else if (t.type === 'punct' && t.value === ')') {
      const o = stack.pop();
      if (o === undefined) return raw; // несбалансированно — не трогаем
      match.set(o, i);
    }
  }
  if (stack.length) return raw;

  // Множество индексов скобок к удалению.
  const drop = new Set<number>();
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    if (!(t.type === 'punct' && t.value === '(')) continue;
    if (drop.has(i)) continue;
    const close = match.get(i)!;
    const prev = i > 0 ? sig[i - 1] : undefined;
    const nx = close + 1 < sig.length ? sig[close + 1] : undefined;
    // Уже помеченный к удалению сосед-скобка считается «прозрачным» (вложенная
    // охватывающая пара): пропускаем — внешняя пара решит за обе.
    if (isCallOpenContext(prev)) continue;
    // Содержимое не пустое и без верхнеуровневой запятой.
    if (close === i + 1) continue;
    let hasTopComma = false;
    let depth = 0;
    for (let k = i + 1; k < close; k++) {
      const c = sig[k];
      if (c.type === 'punct' && c.value === '(') depth++;
      else if (c.type === 'punct' && c.value === ')') depth--;
      else if (depth === 0 && c.type === 'punct' && c.value === ',') { hasTopComma = true; break; }
    }
    if (hasTopComma) continue;
    // Никогда не меняем приоритет арифметики: сосед-арифметика → оставляем скобки.
    if (isArithPunct(prev) || isArithPunct(nx)) continue;
    if (!leftOk(prev) || !rightOk(nx)) continue;
    // Приоритет/ассоциативность сравнения: `A <> (B = C)` НЕ упрощается до `A <> B = C`
    // (изменился бы смысл — сравнения левоассоциативны/неассоциативны). Если сосед —
    // оператор сравнения/предиката, а внутри есть верхнеуровневое сравнение/предикат,
    // скобки сохраняем. Префиксы НЕ/КОГДА/ТОГДА/ИНАЧЕ и границы (`,`/КАК/`)`/начало/
    // конец) приоритета не навязывают (НЕ связывает слабее сравнения).
    const neighborIsCompare = (t: Token | undefined): boolean =>
      isCmpPunct(t) || (!!t && (t.type === 'keyword' || t.type === 'ident') &&
        new Set(['ЕСТЬ', 'МЕЖДУ', 'ПОДОБНО', 'ССЫЛКА']).has(t.value.toUpperCase()));
    if (neighborIsCompare(prev) || neighborIsCompare(nx)) {
      let innerCompare = false;
      let d = 0;
      for (let k = i + 1; k < close; k++) {
        const c = sig[k];
        if (c.type === 'punct' && c.value === '(') d++;
        else if (c.type === 'punct' && c.value === ')') d--;
        else if (d === 0 && neighborIsCompare(c)) { innerCompare = true; break; }
      }
      if (innerCompare) continue;
    }
    // Для оператора членства `В` снимаем обёртку ТОЛЬКО когда левый операнд — ЦЕЛЬНОЕ
    // значение (без верхнеур. сравнения/предиката/булева И/ИЛИ внутри): `(ВЫРАЗИТЬ(…)) В`
    // → `ВЫРАЗИТЬ(…) В`. Это исключает теоретические `(a = b) В` (смысл изменился бы).
    if (isMembershipWord(nx)) {
      let innerBoolCmp = false;
      let d2 = 0;
      for (let k = i + 1; k < close; k++) {
        const c = sig[k];
        if (c.type === 'punct' && c.value === '(') d2++;
        else if (c.type === 'punct' && c.value === ')') d2--;
        else if (d2 === 0 && (isCmpPunct(c) || isAnd(c) || isOr(c) || neighborIsCompare(c))) { innerBoolCmp = true; break; }
      }
      if (innerBoolCmp) continue;
    }
    drop.add(i);
    drop.add(close);
  }

  if (!drop.size) return raw;

  // Заменяем помеченные скобки ПРОБЕЛОМ (а не пустотой), чтобы не склеить соседние
  // слова при слитной записи (`НЕ(поле)` → `НЕ поле`, а не `НЕполе`). Затем
  // нормализуем пробелы: схлопываем серии, убираем пробел сразу после `(` / перед `)`
  // оставшихся скобок и перед запятой.
  const positions: number[] = [];
  for (const idx of drop) positions.push(sig[idx].pos);
  positions.sort((a, b) => b - a);
  let out = raw;
  for (const p of positions) {
    out = out.slice(0, p) + ' ' + out.slice(p + 1);
  }
  return out
    .replace(/\s{2,}/g, ' ')
    .replace(/\(\s+/g, '(')
    .replace(/\s+\)/g, ')')
    .replace(/\s+,/g, ',')
    .trim();
}

/**
 * Снимает ОДНУ полностью охватывающую избыточную пару скобок вокруг ЦЕЛОГО значения
 * ветки CASE (`КОГДА (X = &Y)` → `КОГДА X = &Y`, `ТОГДА (a - b)` → `ТОГДА a - b`),
 * как это делает конструктор 1С внутри листового ВЫБОР (фаза 6.16.37). `content` —
 * текст ПОСЛЕ ключевого слова КОГДА/ТОГДА/ИНАЧЕ (одна строка).
 *
 * Снимаем строго консервативно — ТОЛЬКО когда:
 *   - первая `(` парна ПОСЛЕДНЕМУ символу `)` (пара охватывает всё значение целиком;
 *     `(a) - (b)` и `(ВЫРАЗИТЬ(…)) * X` сюда не попадают — там пара не охватывающая);
 *   - внутри НЕТ верхнеуровневого булева И/ИЛИ (приоритет/раскладку не меняем);
 *   - внутри НЕТ вызова `ВЫРАЗИТЬ` (конструктор оборачивает голый ВЫРАЗИТЬ-операнд
 *     своими правилами — не трогаем эту зону);
 *   - внутри НЕТ ВЫБОР/ВЫБРАТЬ (вложенный CASE/подзапрос раскладывается отдельно).
 * Иначе `content` возвращается без изменений.
 */
function stripRedundantCaseClauseParens(content: string): string {
  const t = content.trim();
  if (t.length < 2 || t[0] !== '(' || !t.endsWith(')')) return content;
  // Пара первой `(` должна закрываться ровно последним символом (охват всего значения).
  let depth = 0;
  let inStr = false;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '(') depth++;
    else if (ch === ')') {
      depth--;
      if (depth === 0 && i !== t.length - 1) return content; // не охватывающая
    }
  }
  if (depth !== 0) return content;
  const inner = t.slice(1, -1).trim();
  if (inner === '') return content;
  // Зоны риска: ВЫРАЗИТЬ (особые правила оборачивания), ВЫБОР/ВЫБРАТЬ (вложенный
  // CASE/подзапрос), верхнеуровневый булев И/ИЛИ (раскладка по оператору).
  if (/(?:^|[^\p{L}\p{N}_])(ВЫРАЗИТЬ|ВЫБОР|ВЫБРАТЬ)(?:[^\p{L}\p{N}_]|$)/iu.test(inner)) return content;
  if (leafHasTopBoolean(inner)) return content;
  return inner;
}

/**
 * Переотрисовка арифметики листа. Возвращает канонический текст; при незнакомой
 * конструкции — исходный (без изменений). См. комментарий выше.
 */
export function reprintLeafArithmetic(raw: string): string {
  if (!raw || raw.includes('\n')) return raw;
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length === 0) return raw;
  // Должна присутствовать арифметика (оператор `+ - * / %` на каком-либо уровне)
  // ИЛИ голый ВЫРАЗИТЬ-операнд — иначе незачем (и не рискуем чужими листьями).
  const hasArithOp = sig.some(
    (t) => t.type === 'punct' && (ARITH_ADD.has(t.value) || ARITH_MUL.has(t.value))
  );
  if (!hasArithOp) return raw;
  try {
    const out = new ArithReprinter(sig).parseAll();
    return out;
  } catch {
    return raw;
  }
}

/**
 * Снимает ИЗБЫТОЧНЫЕ скобки арифметического операнда СРАВНЕНИЯ (`(A - B) > 0` →
 * `A - B > 0`, `X > (B - C)` → `X > B - C`): арифметика связывает крепче сравнения,
 * поэтому обёртка операнда сравнения избыточна (живой оракул, фаза 6.16.78). Узко:
 * РОВНО один верхнеуровневый оператор сравнения, обе стороны — чистая арифметика/атом
 * (reprintLeafArithmetic их разбирает целиком). Иначе исходный текст без изменений
 * (булева логика/предикаты/несколько сравнений не трогаем).
 */
export function reprintLeafComparison(raw: string): string {
  if (!raw || raw.includes('\n') || !raw.includes('(')) return raw;
  let toks: Token[];
  try { toks = tokenize(raw); } catch { return raw; }
  const sig = toks.filter((t) => t.type !== 'eof');
  if (sig.length === 0) return raw;
  // Единственный верхнеуровневый оператор сравнения.
  let depth = 0;
  let cmpIdx = -1;
  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    if (t.type === 'punct' && t.value === '(') { depth++; continue; }
    if (t.type === 'punct' && t.value === ')') { depth--; continue; }
    if (depth !== 0) continue;
    // Любое предикатное/булево слово на верхнем уровне → не наш случай.
    if ((t.type === 'keyword' || t.type === 'ident') &&
        new Set(['И', 'ИЛИ', 'НЕ', 'ЕСТЬ', 'МЕЖДУ', 'ПОДОБНО', 'ССЫЛКА', 'В', 'КАК', 'ВЫБОР']).has((t.text ?? t.value).toUpperCase())) {
      return raw;
    }
    if (t.type === 'punct' && COMPARISON_PUNCT_SET.has(t.value)) {
      if (cmpIdx >= 0) return raw; // несколько сравнений — не трогаем
      cmpIdx = i;
    }
  }
  if (cmpIdx < 0) return raw;
  const leftToks = sig.slice(0, cmpIdx);
  const rightToks = sig.slice(cmpIdx + 1);
  if (leftToks.length === 0 || rightToks.length === 0) return raw;
  try {
    const left = new ArithReprinter(leftToks).parseAll();
    const right = new ArithReprinter(rightToks).parseAll();
    return `${left} ${sig[cmpIdx].value} ${right}`;
  } catch {
    return raw;
  }
}

export function normalizeLeafCase(raw: string): string {
  if (!raw) return raw;
  raw = canonicalizeLeafLexemes(raw);
  let toks: Token[];
  try {
    toks = tokenize(raw);
  } catch {
    return raw;
  }
  // Индексы значимых (не-eof) токенов для просмотра соседей.
  const sig = toks.filter((t) => t.type !== 'eof');
  // Карта: позиция токена -> его индекс в sig.
  const spans: Array<{ pos: number; len: number; up: string }> = [];

  const prevSig = (idx: number): Token | undefined => sig[idx - 1];
  const nextSig = (idx: number): Token | undefined => sig[idx + 1];
  const isWordTok = (t: Token | undefined): boolean =>
    !!t && (t.type === 'ident' || t.type === 'keyword');

  for (let i = 0; i < sig.length; i++) {
    const t = sig[i];
    if (!isWordTok(t)) continue;
    const prev = prevSig(i);
    // Сегмент пути после точки — идентификатор, не трогаем.
    if (prev && prev.type === 'punct' && prev.value === '.') continue;
    const up = tokUpper(t);
    const text = t.text ?? t.value;
    if (text === up) continue; // уже в верхнем регистре

    const next = nextSig(i);
    const followedByParen = !!next && next.type === 'punct' && next.value === '(';

    let shouldUpper = false;

    // 1) Имя функции в позиции вызова: WORD(
    if (FUNCTION_WORDS.has(up) && followedByParen) shouldUpper = true;

    // 2) Литерал-ключевое слово (вне пути; параметры &X — отдельный тип токена).
    if (!shouldUpper && LITERAL_WORDS.has(up)) shouldUpper = true;

    // 3) Примитивный тип в позиции типа: после КАК, либо первый токен внутри ТИП(.
    if (!shouldUpper && PRIMITIVE_TYPE_WORDS.has(up)) {
      const afterKak = !!prev && prev.type === 'keyword' && prev.value === 'КАК';
      // ТИП( <тип> : prev = '(', prev-prev = ТИП
      let insideTip = false;
      if (prev && prev.type === 'punct' && prev.value === '(') {
        const pp = prevSig(i - 1);
        if (pp && isWordTok(pp) && tokUpper(pp) === 'ТИП') insideTip = true;
      }
      if (afterKak || insideTip) shouldUpper = true;
    }

    // 4) Литерал периода в позиции аргумента функции даты (НАЧАЛОПЕРИОДА/КОНЕЦПЕРИОДА/
    //    ДОБАВИТЬКДАТЕ/РАЗНОСТЬДАТ). Голый токен-слово внутри списка аргументов такой
    //    функции, за которым НЕ следует `(` (иначе это имя функции ДЕНЬ(…)) и НЕ
    //    следует `.` (иначе голова `.`-пути). Принадлежность аргументного списка
    //    конкретной функции проверяем по имени перед охватывающей скобкой — это не
    //    даёт задеть голый идентификатор `Год`, стоящий после запятой в списках
    //    УПОРЯДОЧИТЬ ПО / ВЫБРАТЬ и т. п.
    if (!shouldUpper && PERIOD_WORDS.has(up)) {
      const nextIsDot = !!next && next.type === 'punct' && next.value === '.';
      if (!followedByParen && !nextIsDot && enclosingFunctionIs(sig, i, PERIOD_FUNCTIONS)) {
        shouldUpper = true;
      }
    }

    // 5) Операторы-идентификаторы (лексер не делает их keyword): НЕ/ИЛИ — никогда не
    //    имена полей, приводим к ВЕРХ всегда (вне пути). ССЫЛКА — ещё и имя поля,
    //    поэтому ВЕРХ только в ИНФИКСНОЙ позиции `<выражение> ССЫЛКА <Тип>`
    //    (фаза 6.16.7, MCP).
    if (!shouldUpper && (up === 'НЕ' || up === 'ИЛИ' || up === 'ЕСТЬ')) shouldUpper = true;

    // 5b) Ключевое слово КАК внутри листового выражения (`ВЫРАЗИТЬ(… как Тип)`,
    //     `… как Поле` в листе). Конструктор печатает КАК в каноническом ВЕРХНЕМ
    //     регистре. Другие keyword-слова (ИЗМЕНЕНИЯ, ИТОГИ …) НЕ трогаем в листе:
    //     они часто выступают головой псевдонима таблицы, регистр которого оракул
    //     сохраняет из метаданных (`Изменения`→`Изменения`, не `ИЗМЕНЕНИЯ`).
    if (!shouldUpper && t.type === 'keyword' && up === 'КАК') shouldUpper = true;
    if (!shouldUpper && up === 'ССЫЛКА') {
      const prevIsExprEnd = !!prev && (
        prev.type === 'number' || prev.type === 'string' ||
        (prev.type === 'punct' && prev.value === ')') ||
        ((prev.type === 'ident' || prev.type === 'keyword') && !(prev.type === 'keyword' && prev.value === 'КАК'))
      );
      if (prevIsExprEnd && isWordTok(next)) shouldUpper = true;
    }

    if (shouldUpper) spans.push({ pos: t.pos, len: text.length, up });
  }

  // Применяем замены регистра справа налево (длина не меняется), затем нормализуем
  // пробелы (класс C-misc). Регистровые замены сохраняют позиции, поэтому порядок
  // безопасен.
  let out = raw;
  if (spans.length) {
    spans.sort((a, b) => b.pos - a.pos);
    for (const s of spans) {
      out = out.slice(0, s.pos) + s.up + out.slice(s.pos + s.len);
    }
  }
  return normalizeLeafWhitespace(out);
}

// --- AST --------------------------------------------------------------------

type Node =
  | { kind: 'or'; operands: Node[] }
  | { kind: 'and'; operands: Node[] }
  | { kind: 'not'; child: Node }
  | { kind: 'group'; child: Node } // скобочная группа верхнего уровня
  | { kind: 'case'; clauses: CaseClause[]; elseExpr?: Node | null; elseText?: string; selector?: string; trailing?: string }
  | { kind: 'leaf'; text: string };

interface CaseClause {
  // условие после КОГДА (булев слот)
  whenNode: Node;
  // значение после ТОГДА (value-слот): либо вложенный ВЫБОР, либо дословный текст
  thenNode: Node;
}

// --- helpers для распознавания слов-операторов ------------------------------

function up(t: Token): string {
  return t.value.toUpperCase();
}
function isWord(t: Token, w: string): boolean {
  return (t.type === 'ident' || t.type === 'keyword') && up(t) === w;
}
function isOr(t: Token): boolean {
  return isWord(t, 'ИЛИ');
}
function isAnd(t: Token): boolean {
  return t.type === 'keyword' && t.value === 'И';
}
function isNot(t: Token): boolean {
  return isWord(t, 'НЕ');
}
function isCase(t: Token): boolean {
  return isWord(t, 'ВЫБОР');
}
function isWhen(t: Token): boolean {
  return isWord(t, 'КОГДА');
}
function isThen(t: Token): boolean {
  return isWord(t, 'ТОГДА');
}
function isElse(t: Token): boolean {
  return isWord(t, 'ИНАЧЕ');
}
function isEnd(t: Token): boolean {
  return isWord(t, 'КОНЕЦ');
}
/**
 * Является ли токен бинарным оператором (сравнения или арифметики), ПОСЛЕ которого
 * вложенный `ВЫБОР` — это RHS-операнд внутри листа (`= ВЫБОР`, `- ВЫБОР`, `* ВЫБОР`),
 * а не ведущий структурный CASE (тот идёт через parsePrimary).
 */
function isLeafCaseOpenerOp(t: Token): boolean {
  return t.type === 'punct' &&
    (COMPARISON_PUNCT.has(t.value) || ARITH_ADD.has(t.value) || ARITH_MUL.has(t.value));
}

/**
 * Добавляет операнд в список операндов ИЛИ, разворачивая левую ассоциативность:
 * ВЕДУЩАЯ скобочная группа, обёртывающая ИЛИ (`(a ИЛИ b) ИЛИ c`), — избыточные
 * скобки, которые конструктор 1С снимает (печатает `a ИЛИ b ИЛИ c`). Применяется
 * только к ПЕРВОМУ операнду (operands пуст): хвостовая группа `x ИЛИ (a ИЛИ b)`
 * сохраняет скобки. Голый ИЛИ-операнд (после такой же раскрутки ниже) тоже вливаем.
 */
function pushOrOperand(operands: Node[], op: Node): void {
  if (operands.length === 0) {
    if (op.kind === 'or') {
      operands.push(...op.operands);
      return;
    }
    if (op.kind === 'group' && op.child.kind === 'or') {
      operands.push(...op.child.operands);
      return;
    }
  }
  // Скобки вокруг И-группы операнда ИЛИ — избыточны (И связывает крепче ИЛИ);
  // конструктор их снимает: `… ИЛИ (a И b)` → `… ИЛИ a И b` (фаза 6.15.21, MCP).
  // Применимо к любой позиции операнда (приоритет операторов не зависит от места).
  if (op.kind === 'group' && op.child.kind === 'and') {
    operands.push(op.child);
    return;
  }
  operands.push(op);
}

// --- Parser -----------------------------------------------------------------

class Parser {
  private toks: Token[];
  private raw: string;
  private i = 0;
  /**
   * Сплющивать ли многострочные листья в одну строку. Включается только для слота
   * `select` (поля выборки и значения ВЫБОР), где конструктор печатает листовое
   * подвыражение на одной строке. В слотах ГДЕ/ИМЕЮЩИЕ/ПО исторически сохраняется
   * многострочная структура исходника дословно (нулевая регрессия принятых файлов).
   */
  private flattenLeaves: boolean;

  constructor(raw: string, flattenLeaves = false) {
    this.raw = raw;
    this.flattenLeaves = flattenLeaves;
    // исключаем eof из рабочего набора (но позиция eof нужна для среза «до конца»)
    this.toks = tokenize(raw);
  }

  private peek(): Token {
    return this.toks[this.i];
  }
  private atEof(): boolean {
    return this.peek().type === 'eof';
  }

  /** Срез исходной строки [from, to) с обрезкой хвостовых пробелов. */
  private slice(from: number, to: number): string {
    return this.raw.slice(from, to).replace(/\s+$/u, '');
  }

  /**
   * Текст листа [from, to): сплющивает многострочный лист в одну строку (конструктор
   * печатает листовые подвыражения на одной строке), затем нормализует регистр и
   * пробелы. Однострочные листья проходят только нормализацию (поведение принятых
   * запросов не меняется).
   */
  private leafText(from: number, to: number): string {
    const raw = this.raw.slice(from, to).replace(/\s+$/u, '');
    // Сплющиваем многострочный лист в одну строку ТОЛЬКО если это действительно
    // листовое подвыражение: без вложенного подзапроса (`В (ВЫБРАТЬ …)` —
    // раскладывается конструктором как запрос) и без верхнеуровневого булева
    // оператора И/ИЛИ (значение-слот вида `a ИЛИ b` конструктор переотрисовывает с
    // переносом по оператору — не сплющиваем, сохраняя структуру исходника).
    const flat =
      this.flattenLeaves &&
      raw.includes('\n') &&
      !leafHasSubquery(raw) &&
      !leafHasTopBoolean(raw) &&
      !leafHasCase(raw)
        ? flattenLeafText(raw)
        : raw;
    return normalizeLeafCase(flat);
  }

  parse(): Node {
    const node = this.parseOr();
    return node;
  }

  /**
   * Дословный хвост: всё от КОНЦА последнего потреблённого токена до конца строки
   * (включая исходные пробелы/переносы перед хвостом). '' если хвоста нет.
   * Сохраняет, например, ошибочно захваченные парсером SDBL `\n\nУПОРЯДОЧИТЬ ПО …`.
   */
  tail(): string {
    if (this.peek().type === 'eof') return '';
    // конец последнего потреблённого токена
    const prev = this.i > 0 ? this.toks[this.i - 1] : undefined;
    const from = prev ? prev.pos + prev.text.length : this.peek().pos;
    return this.raw.slice(from);
  }

  // ИЛИ — низший приоритет
  private parseOr(): Node {
    const first = this.parseAnd();
    const operands: Node[] = [];
    pushOrOperand(operands, first);
    while (!this.atEof() && isOr(this.peek())) {
      this.i++; // съесть ИЛИ
      pushOrOperand(operands, this.parseAnd());
    }
    return operands.length === 1 ? operands[0] : { kind: 'or', operands };
  }

  private parseAnd(): Node {
    const first = this.parseNot();
    const operands = [first];
    while (!this.atEof() && isAnd(this.peek())) {
      this.i++; // съесть И
      operands.push(this.parseNot());
    }
    return operands.length === 1 ? first : { kind: 'and', operands };
  }

  private parseNot(): Node {
    if (!this.atEof() && isNot(this.peek())) {
      // НЕ как булев префикс ТОЛЬКО если за ним идёт структурный примитив
      // (ВЫБОР, скобочная группа или булево подвыражение). Иначе НЕ — часть листа
      // (НЕ поле, НЕ &Параметр), и лист поглотит его дословно.
      if (this.notIsStructural()) {
        this.i++; // съесть НЕ
        return { kind: 'not', child: this.parseNot() };
      }
    }
    return this.parsePrimary();
  }

  /**
   * Является ли текущее `НЕ` структурным булевым отрицанием. Структурно — если
   * за ним ВЫБОР или открывающая скобка, чьё содержимое содержит верхнеуровневый
   * И/ИЛИ (булева группа). Иначе `НЕ` — унарный оператор внутри листа (`НЕ a.Флаг`,
   * `НЕ a.X В (…)`), и обрабатывается листом дословно.
   */
  private notIsStructural(): boolean {
    const next = this.toks[this.i + 1];
    if (!next) return false;
    if (isCase(next)) return true;
    if (next.type === 'punct' && next.value === '(') {
      return this.parenHasTopBoolean(this.i + 1);
    }
    return false;
  }

  /** Содержит ли скобочная группа, открытая на индексе `open`, верхнеур. И/ИЛИ. */
  private parenHasTopBoolean(open: number): boolean {
    let depth = 0;
    for (let k = open; k < this.toks.length; k++) {
      const t = this.toks[k];
      if (t.type === 'eof') break;
      if (t.type === 'punct' && t.value === '(') {
        depth++;
        continue;
      }
      if (t.type === 'punct' && t.value === ')') {
        depth--;
        if (depth === 0) break;
        continue;
      }
      if (depth === 1 && (isAnd(t) || isOr(t))) return true;
    }
    return false;
  }

  /**
   * Скобка на индексе `open` обёртывает РОВНО один ВЫБОР…КОНЕЦ (первый значимый
   * токен внутри — ВЫБОР), а ПОСЛЕ её закрывающей `)` сразу идёт оператор сравнения
   * (`= <> < > <= >=`), арифметики (`+ - * / %`) или МЕЖДУ/ПОДОБНО. Используется для
   * снятия избыточной обёртки CASE-операнда (`(ВЫБОР…КОНЕЦ) <> X` → `ВЫБОР…КОНЕЦ <> X`).
   */
  private parenWrapsCaseThenCompare(open: number): boolean {
    // Первый значимый токен внутри скобки — ВЫБОР.
    const inner = this.toks[open + 1];
    if (!isCase(inner)) return false;
    // Находим закрывающую `)` этой скобки.
    let depth = 0;
    let closeIdx = -1;
    for (let k = open; k < this.toks.length; k++) {
      const tk = this.toks[k];
      if (tk.type === 'eof') break;
      if (tk.type === 'punct' && tk.value === '(') { depth++; continue; }
      if (tk.type === 'punct' && tk.value === ')') {
        depth--;
        if (depth === 0) { closeIdx = k; break; }
      }
    }
    if (closeIdx < 0) return false;
    const after = this.toks[closeIdx + 1];
    if (!after || after.type === 'eof') return false;
    if (after.type === 'punct' &&
        (COMPARE_OPS.has(after.value) || ARITH_ADD.has(after.value) || ARITH_MUL.has(after.value))) {
      return true;
    }
    if (isWord(after, 'МЕЖДУ') || isWord(after, 'ПОДОБНО')) return true;
    return false;
  }

  /**
   * Ведущий CASE-операнд сравнения, чей RHS — тоже ВЫБОР (`ВЫБОР…КОНЕЦ <op> ВЫБОР…КОНЕЦ`).
   * `tryParseSimpleCaseTrailing` такую форму бракует (вложенный ВЫБОР в хвосте), а
   * структурный CASE-узел не несёт многоклаузный CASE-RHS. Поэтому, как и зеркальный
   * случай `<лист> <op> ВЫБОР…КОНЕЦ` (который parseLeaf поглощает листом через caseDepth),
   * поглощаем весь сравнительный цепочечный CASE одним ЛИСТОМ — рендер раскладывает обе
   * (и более) ветви ВЫБОР через reindentLeafCase, печатая `КОНЕЦ <op> ВЫБОР` единой
   * строкой (сверено живым оракулом: `КОНЕЦ <> ВЫБОР` на одной строке, RHS-CASE
   * многострочно). Возвращает листовой текст ИЛИ undefined (позицию НЕ двигает).
   */
  private tryParseCaseCompareCaseLeaf(): string | undefined {
    const save = this.i;
    const from = this.peek().pos;
    let to = from;
    let caseDepth = 0;
    let chained = false; // встретился ли хотя бы один `КОНЕЦ <op> ВЫБОР`
    while (!this.atEof()) {
      const t = this.peek();
      if (isCase(t)) { caseDepth++; to = t.pos + t.text.length; this.i++; continue; }
      if (isEnd(t)) {
        to = t.pos + t.text.length; this.i++;
        if (caseDepth > 0) caseDepth--;
        if (caseDepth === 0) {
          // CASE закрыт. Если дальше `<op> ВЫБОР` — продолжаем цепочку; иначе стоп.
          const op = this.atEof() ? undefined : this.peek();
          const rhs = this.toks[this.i + 1];
          if (op && op.type === 'punct' && COMPARE_OPS.has(op.value) && rhs && isCase(rhs)) {
            chained = true;
            to = op.pos + op.value.length;
            this.i++; // съесть оператор; следующий ВЫБОР откроет CASE на новой итерации
            continue;
          }
          break; // конец цепочки CASE-сравнений
        }
        continue;
      }
      // Внутри (любой глубины) CASE — поглощаем дословно (КОГДА/ТОГДА/ИНАЧЕ/И/ИЛИ/листы).
      to = t.pos + t.value.length; this.i++;
    }
    if (!chained || caseDepth !== 0) { this.i = save; return undefined; }
    return this.leafText(from, to);
  }

  private parsePrimary(): Node {
    const t = this.peek();
    // ВЫБОР … КОНЕЦ
    if (isCase(t)) {
      // `ВЫБОР…КОНЕЦ <op> ВЫБОР…КОНЕЦ` — сравнение двух CASE: поглощаем листом (см.
      // tryParseCaseCompareCaseLeaf). Должно идти ДО parseCase, иначе CASE-узел съест
      // лишь LHS, а `<op> RHS-ВЫБОР` осиротеет (попадёт в tail дословно).
      const chainLeaf = this.tryParseCaseCompareCaseLeaf();
      if (chainLeaf !== undefined) return { kind: 'leaf', text: chainLeaf };
      const caseNode = this.parseCase();
      // Хвост сравнения после КОНЕЦ в БУЛЕВОМ/условном слоте (`ВЫБОР…КОНЕЦ = &П` как
      // операнд условия КОГДА / ГДЕ): конструктор держит CASE структурным и приклеивает
      // `= &П` к строке КОНЕЦ. Узкая форма (ровно один верхнеур. оператор сравнения,
      // листовой операнд, без вложенного ВЫБОР и И/ИЛИ) — как parseValue (фаза 6.16.65).
      if (!this.atEof() && caseNode.kind === 'case') {
        const t2 = this.peek();
        const boundary =
          isAnd(t2) || isOr(t2) || isThen(t2) || isElse(t2) || isEnd(t2) || isWhen(t2) ||
          (t2.type === 'punct' && t2.value === ')');
        if (!boundary) {
          const trailing = this.tryParseSimpleCaseTrailing(true, true);
          if (trailing !== undefined) caseNode.trailing = trailing;
        }
      }
      return caseNode;
    }
    // скобочная группа верхнего уровня — раскрываем в под-дерево ТОЛЬКО если
    // содержит верхнеуровневый булев И/ИЛИ или ВЫБОР; иначе это листовая скобка
    // (вызов/группировка арифметики) — поглощается листом дословно.
    if (t.type === 'punct' && t.value === '(' && this.parenIsStructuralGroup(this.i)) {
      // Скобка обёртывает РОВНО один ВЫБОР…КОНЕЦ (без верхнеур. И/ИЛИ внутри), а сразу
      // за закрывающей `)` следует оператор сравнения / арифметики / МЕЖДУ / ПОДОБНО:
      // `(ВЫБОР…КОНЕЦ) <> X`. Скобки вокруг CASE-операнда сравнения избыточны —
      // конструктор 1С их снимает и печатает оператор на строке КОНЕЦ (фаза 6.16.77,
      // подтверждено живым оракулом). Снимаем обёртку: разбираем CASE напрямую и
      // приклеиваем хвост через tryParseSimpleCaseTrailing (как у голого CASE).
      if (
        !this.parenHasTopBoolean(this.i) &&
        this.parenWrapsCaseThenCompare(this.i)
      ) {
        this.i++; // съесть (
        const caseNode = this.parseCase();
        if (!this.atEof() && this.peek().type === 'punct' && this.peek().value === ')') {
          this.i++; // съесть )
        }
        if (caseNode.kind === 'case' && !this.atEof()) {
          const trailing = this.tryParseSimpleCaseTrailing(true, true);
          if (trailing !== undefined) caseNode.trailing = trailing;
        }
        return caseNode;
      }
      this.i++; // съесть (
      const inner = this.parseOr();
      // закрывающая )
      if (!this.atEof() && this.peek().type === 'punct' && this.peek().value === ')') {
        this.i++;
      }
      return { kind: 'group', child: inner };
    }
    return this.parseLeaf();
  }

  /**
   * Скобка структурна, если содержит верхнеур. И/ИЛИ или ВЫБОР. Скобка с
   * верхнеуровневой ЗАПЯТОЙ — это КОРТЕЖ-операнд (`(ВЫБОР…КОНЕЦ, ВЫБОР…КОНЕЦ) В (…)`,
   * `(Поле1, Поле2) В (…)`), а НЕ группа вокруг одного выражения: его нельзя
   * раскрывать в под-дерево group/case (иначе renderBool обернёт лишь ПЕРВЫЙ элемент,
   * добавив избыточные `(`…`)` и лишний уровень отступа). Кортеж поглощается листом
   * дословно (фаза 6.16, корпус ЗастрахованныеЛицаСЭДО/ОтчётКомиссионера).
   */
  private parenIsStructuralGroup(open: number): boolean {
    let depth = 0;
    let hasStructural = false;
    for (let k = open; k < this.toks.length; k++) {
      const t = this.toks[k];
      if (t.type === 'eof') break;
      if (t.type === 'punct' && t.value === '(') {
        depth++;
        continue;
      }
      if (t.type === 'punct' && t.value === ')') {
        depth--;
        if (depth === 0) break;
        continue;
      }
      // Верхнеуровневая запятая → это КОРТЕЖ, а не группа вокруг одного выражения.
      if (depth === 1 && t.type === 'punct' && t.value === ',') return false;
      if (depth === 1 && (isAnd(t) || isOr(t) || isCase(t))) hasStructural = true;
    }
    return hasStructural;
  }

  /**
   * Лист: диапазон токенов до следующего верхнеуровневого булева И/ИЛИ, конца,
   * закрывающей скобки или КОГДА/ТОГДА/ИНАЧЕ/КОНЕЦ. Поглощает внутренние скобки,
   * вызовы, МЕЖДУ a И b (И после МЕЖДУ — не разделитель), ЕСТЬ [НЕ] NULL, ПОДОБНО.
   */
  private parseLeaf(): Node {
    const startTok = this.peek();
    const from = startTok.pos;
    let to = from;
    let depth = 0;
    let betweenPending = 0; // сколько И ждём «съесть» внутри МЕЖДУ
    // Глубина вложенного ВЫБОР…КОНЕЦ как RHS бинарного оператора внутри листа
    // (`&П = ВЫБОР… КОНЕЦ`, `A - ВЫБОР… КОНЕЦ` — операнд цепочки ИЛИ/И/арифметики):
    // без отслеживания лист обрывался на первом КОГДА, `)` охватывающей группы
    // вставлялась после ВЫБОР (`= ВЫБОР)`), а тело CASE терялось. Считаем ВЫБОР
    // открывателем CASE-уровня ТОЛЬКО когда он стоит СРАЗУ за оператором сравнения
    // или арифметики (`= ВЫБОР`, `<> ВЫБОР`, `- ВЫБОР`): узкий RHS-случай; ведущий
    // CASE (`ВЫБОР…КОНЕЦ <op> …`) идёт через parsePrimary и сюда не попадает.
    let caseDepth = 0;
    let prevSig: Token | undefined; // предыдущий значимый (не-EOF) токен

    while (!this.atEof()) {
      const t = this.peek();
      if (t.type === 'punct' && t.value === '(') {
        depth++;
        to = t.pos + t.value.length;
        prevSig = t;
        this.i++;
        continue;
      }
      if (t.type === 'punct' && t.value === ')') {
        if (depth === 0) break; // закрывающая чужой группы — стоп
        depth--;
        to = t.pos + t.value.length;
        prevSig = t;
        this.i++;
        continue;
      }
      if (depth === 0) {
        if (caseDepth > 0) {
          // Внутри вложенного RHS-CASE: КОГДА/ТОГДА/ИНАЧЕ — не границы; КОНЕЦ закрывает.
          if (isCase(t)) caseDepth++;
          else if (isEnd(t)) caseDepth--;
          to = t.pos + t.value.length;
          prevSig = t;
          this.i++;
          continue;
        }
        // RHS-CASE сравнения/арифметики открывает CASE-уровень.
        if (isCase(t) && prevSig !== undefined && isLeafCaseOpenerOp(prevSig)) {
          caseDepth++;
          to = t.pos + t.value.length;
          prevSig = t;
          this.i++;
          continue;
        }
        // границы листа на верхнем уровне
        if (isOr(t)) break;
        if (isAnd(t)) {
          if (betweenPending > 0) {
            betweenPending--; // это И из МЕЖДУ a И b
          } else {
            break;
          }
        }
        if (isThen(t) || isElse(t) || isEnd(t) || isWhen(t)) break;
        if (isWord(t, 'МЕЖДУ')) betweenPending++;
      }
      to = t.pos + t.value.length;
      prevSig = t;
      this.i++;
    }
    return { kind: 'leaf', text: this.leafText(from, to) };
  }

  private parseCase(): Node {
    this.i++; // съесть ВЫБОР
    // Селекторная форма: ВЫБОР <выражение> КОГДА <значение> ТОГДА … Если сразу за
    // ВЫБОР идёт не КОГДА — это селектор (выражение-лист до первого верхнеуровневого
    // КОГДА), который конструктор печатает инлайн на строке `ВЫБОР <селектор>`.
    let selector: string | undefined;
    if (!this.atEof() && !isWhen(this.peek())) {
      selector = this.parseCaseSelector();
    }
    const clauses: CaseClause[] = [];
    let elseNode: Node | null = null;
    while (!this.atEof()) {
      const t = this.peek();
      if (isWhen(t)) {
        this.i++; // КОГДА
        const whenNode = this.parseOr(); // булев слот
        // ТОГДА
        if (!this.atEof() && isThen(this.peek())) this.i++;
        const thenNode = this.parseValue(); // value-слот
        clauses.push({ whenNode, thenNode });
        continue;
      }
      if (isElse(t)) {
        this.i++; // ИНАЧЕ
        elseNode = this.parseValue();
        continue;
      }
      if (isEnd(t)) {
        this.i++; // КОНЕЦ
        break;
      }
      break;
    }
    return { kind: 'case', clauses, elseExpr: elseNode, selector };
  }

  /**
   * Хвост после `КОНЕЦ` value-слотового ВЫБОР: `<op> value` (`КОНЕЦ <> &П`).
   * Возвращает нормализованный текст хвоста (`<> &П`) ТОЛЬКО для узкой формы —
   * ровно один верхнеуровневый оператор сравнения, листовой операнд, без вложенного
   * ВЫБОР и без верхнеуровневых И/ИЛИ. Иначе undefined (позицию НЕ двигает).
   * Эта форма позволяет CASE идти структурным путём с приклеенным хвостом к КОНЕЦ.
   */
  private tryParseSimpleCaseTrailing(allowLeadingArith = false, boolBoundary = false): string | undefined {
    const save = this.i;
    const startTok = this.peek();
    // Хвост обязан начинаться с оператора сравнения; в булевом слоте (КОГДА/ГДЕ)
    // допускается и ведущий АРИФМЕТИЧЕСКИЙ оператор (`КОНЕЦ * НДФЛ.Сумма > 0` —
    // CASE-операнд арифметики, замыкаемой одним сравнением; фаза 6.16.74). Также
    // ведущие МЕЖДУ/ПОДОБНО — `(ВЫБОР…КОНЕЦ) МЕЖДУ &A И &B` / `КОНЕЦ ПОДОБНО &Ш`:
    // CASE — левый операнд диапазона/шаблона, скобки-обёртка лишние, оператор
    // печатается на строке КОНЕЦ без `)` (фаза 6.16.75).
    const leadBetween = isWord(startTok, 'МЕЖДУ');
    const leadLike = isWord(startTok, 'ПОДОБНО');
    const leadOk =
      (startTok.type === 'punct' &&
        (COMPARE_OPS.has(startTok.value) ||
          (allowLeadingArith && (ARITH_ADD.has(startTok.value) || ARITH_MUL.has(startTok.value))))) ||
      leadBetween ||
      leadLike;
    if (!leadOk) return undefined;
    const from = startTok.pos;
    let to = from;
    let depth = 0;
    let cmpCount = 0;
    let betweenPending = leadBetween ? 1 : 0; // И из `МЕЖДУ a И b` — не разделитель
    if (leadBetween || leadLike) { to = startTok.pos + startTok.text.length; this.i++; }
    while (!this.atEof()) {
      const t = this.peek();
      if (t.type === 'punct' && t.value === '(') { depth++; to = t.pos + t.value.length; this.i++; continue; }
      if (t.type === 'punct' && t.value === ')') {
        if (depth === 0) break; // граница чужой группы
        depth--; to = t.pos + t.value.length; this.i++; continue;
      }
      if (depth === 0) {
        // Границы value-слота / структурные ключевые слова — стоп. ТОГДА завершает
        // хвост, когда CASE — операнд УСЛОВИЯ КОГДА (`КОГДА ВЫБОР…КОНЕЦ = &П ТОГДА …`);
        // в value-слоте ТОГДА на глубине 0 не встречается, так что стоп безопасен.
        if (isWhen(t) || isThen(t) || isElse(t) || isEnd(t)) break;
        // Вложенный ВЫБОР → форма не простая.
        if (isCase(t)) { this.i = save; return undefined; }
        // И, принадлежащее ведущему/вложенному МЕЖДУ, — не булев разделитель.
        if (isAnd(t)) {
          if (betweenPending > 0) { betweenPending--; }
          // Для МЕЖДУ/ПОДОБНО-хвоста верхнеур. И/ИЛИ — ГРАНИЦА операнда (CASE —
          // левый операнд большего булева, хвост заканчивается тут); для сравнения
          // оставляем прежнее поведение — форма не простая (фаза 6.16.75), КРОМЕ случая
          // boolBoundary: CASE — операнд булевой цепочки (`ВЫБОР…КОНЕЦ <> X ИЛИ …`),
          // верхнеур. И/ИЛИ завершает хвост сравнения (фаза 6.16.77).
          else if (leadBetween || leadLike || boolBoundary) break;
          else { this.i = save; return undefined; }
        } else if (isOr(t)) {
          if (leadBetween || leadLike || boolBoundary) break;
          this.i = save; return undefined;
        }
        else if (isWord(t, 'МЕЖДУ')) betweenPending++;
        else if (t.type === 'punct' && COMPARE_OPS.has(t.value)) cmpCount++;
      }
      to = t.pos + t.value.length;
      this.i++;
    }
    // Ровно один верхнеуровневый оператор сравнения, ЛИБО ведущий МЕЖДУ/ПОДОБНО
    // (у которых 0 операторов сравнения).
    const okShape = leadBetween || leadLike ? cmpCount === 0 : cmpCount === 1;
    if (!okShape) { this.i = save; return undefined; }
    return normalizeLeafWhitespace(this.leafText(from, to));
  }

  /**
   * Селектор формы `ВЫБОР <выражение> КОГДА …` — листовое выражение между ВЫБОР и
   * первым верхнеуровневым КОГДА. Печатается инлайн; нормализуется как лист.
   */
  private parseCaseSelector(): string {
    const startTok = this.peek();
    const from = startTok.pos;
    let to = from;
    let depth = 0;
    while (!this.atEof()) {
      const t = this.peek();
      if (t.type === 'punct' && t.value === '(') {
        depth++;
        to = t.pos + t.value.length;
        this.i++;
        continue;
      }
      if (t.type === 'punct' && t.value === ')') {
        if (depth === 0) break;
        depth--;
        to = t.pos + t.value.length;
        this.i++;
        continue;
      }
      if (depth === 0 && isWhen(t)) break;
      to = t.pos + t.value.length;
      this.i++;
    }
    return this.leafText(from, to);
  }

  /**
   * Value-слот (после ТОГДА/ИНАЧЕ или поле выборки): либо вложенный ВЫБОР, либо
   * дословный текст до следующего КОГДА/ИНАЧЕ/КОНЕЦ верхнего уровня.
   */
  private parseValue(): Node {
    if (!this.atEof() && isCase(this.peek())) {
      // Значение-слот, начинающийся с ВЫБОР, — вложенный CASE-узел ТОЛЬКО если ВЫБОР
      // занимает весь слот (за его КОНЕЦ сразу граница слота: КОГДА/ИНАЧЕ/КОНЕЦ/`)`/
      // eof). Если за КОНЕЦ идёт оператор (`КОНЕЦ <> &П`), значение — это выражение
      // `ВЫБОР… <op> …`, и его нужно держать листом (КОНЕЦ несёт хвост; фаза 6.15.21,
      // MCP). Пробуем разобрать CASE; если за ним не граница — откатываемся к листу.
      const save = this.i;
      const caseNode = this.parseCase();
      if (this.atEof()) return caseNode;
      const t = this.peek();
      const boundary =
        isWhen(t) || isElse(t) || isEnd(t) || (t.type === 'punct' && t.value === ')');
      if (boundary) return caseNode;
      // За КОНЕЦ идёт оператор (`КОНЕЦ <> &П`). Если хвост — ПРОСТОЕ сравнение
      // (один верхнеуровневый оператор сравнения и листовой операнд, без вложенного
      // ВЫБОР и без верхнеуровневых И/ИЛИ), конструктор переотрисовывает CASE
      // структурно и приклеивает хвост к КОНЕЦ (`КОНЕЦ <> &П`). Берём этот путь
      // ТОЛЬКО для такой узкой формы; всё прочее (CASE внутри функции, булев хвост)
      // оставляем листом (фаза 6.15.21).
      const trailing = this.tryParseSimpleCaseTrailing();
      if (trailing !== undefined && caseNode.kind === 'case') {
        caseNode.trailing = trailing;
        return caseNode;
      }
      this.i = save; // откат: значение — лист `ВЫБОР… <op> …`
    }
    const startTok = this.peek();
    const from = startTok.pos;
    let to = from;
    let depth = 0;
    // Глубина вложенных ВЫБОР…КОНЕЦ внутри значения-листа (`ВЫБОР… КОНЕЦ <op> …`):
    // их КОГДА/ИНАЧЕ/КОНЕЦ — НЕ границы внешнего слота (фаза 6.15.21).
    let caseDepth = 0;
    while (!this.atEof()) {
      const t = this.peek();
      if (t.type === 'punct' && t.value === '(') {
        depth++;
        to = t.pos + t.value.length;
        this.i++;
        continue;
      }
      if (t.type === 'punct' && t.value === ')') {
        if (depth === 0) break;
        depth--;
        to = t.pos + t.value.length;
        this.i++;
        continue;
      }
      if (depth === 0 && isCase(t)) {
        caseDepth++;
      } else if (depth === 0 && isEnd(t)) {
        if (caseDepth === 0) break;
        caseDepth--;
      } else if (depth === 0 && caseDepth === 0 && (isWhen(t) || isElse(t))) {
        break;
      }
      to = t.pos + t.value.length;
      this.i++;
    }
    return { kind: 'leaf', text: this.leafText(from, to) };
  }
}

// --- needsFormatting --------------------------------------------------------

/** Содержит ли дерево узел OR или CASE (структуру, требующую переотрисовки). */
function treeHasStructure(node: Node): boolean {
  switch (node.kind) {
    case 'or':
      return true;
    case 'case':
      return true;
    case 'and':
      return node.operands.some(treeHasStructure);
    case 'not':
      return treeHasStructure(node.child);
    case 'group':
      return treeHasStructure(node.child);
    case 'leaf':
      return false;
  }
}

/**
 * Требует ли выражение форматирования. Консервативно: true ТОЛЬКО если в
 * структурном дереве есть OR или CASE. Чистый лист, простая И-цепочка без OR/CASE,
 * простые скобки без ИЛИ/ВЫБОР → false (чтобы принятые запросы остались байт-в-байт).
 */
export function needsFormatting(raw: string): boolean {
  const trimmed = (raw ?? '').trim();
  if (!trimmed) return false;
  let tree: Node;
  try {
    tree = new Parser(trimmed).parse();
  } catch {
    return false;
  }
  return treeHasStructure(tree);
}

/**
 * Поле выборки = верхнеуровневая БУЛЕВА цепочка (`A И B [И C] КАК алиас`, `A ИЛИ B`,
 * `A И (X ИЛИ Y)`)? Конструктор 1С такую цепочку В СЛОТЕ ВЫБОРКИ переносит: первый
 * конъюнкт на строке поля, каждый следующий И/ИЛИ — на своей строке с отступом
 * поле+1, `КАК алиас` приклеен к последнему конъюнкту (фаза 6.16.71, сверено
 * корпусом). needsFormatting для ЧИСТОЙ И-цепочки листьев даёт false (treeHasStructure
 * консервативна — бережёт принятые чистые И-условия ГДЕ/ПО), поэтому такое поле шло
 * плоским листом. Здесь — УЗКИЙ предикат ТОЛЬКО для слота выборки: корень дерева —
 * `and`/`or` с ≥2 операндами. Поведение ГДЕ/ИМЕЮЩИЕ/ПО НЕ затрагивается (предикат
 * вызывается лишь из formatSelectExpression).
 */
export function selectColumnNeedsBoolWrap(raw: string): boolean {
  const trimmed = (raw ?? '').trim();
  if (!trimmed) return false;
  let tree: Node;
  try {
    tree = new Parser(trimmed, true).parse();
  } catch {
    return false;
  }
  return (tree.kind === 'and' || tree.kind === 'or') && tree.operands.length >= 2;
}

// --- Printer (boolean) ------------------------------------------------------

/**
 * Рендер булева дерева. Возвращает массив строк; первая строка БЕЗ ведущего
 * отступа (отступ первой строки добавляет родитель/вызывающий через `firstPrefix`
 * и базовый отступ). Остальные строки — с абсолютными табами.
 *
 * `ind` — число табов первой строки узла; `andCont` — табы строк «И x»; `orLvl` —
 * глубина вложения OR. `cont` — контентный отступ секции (для CASE E).
 */
interface RenderCtx {
  cont: number; // C — контентный отступ секции
  caseBoolean: boolean; // CASE в этой позиции — булев слот (E=C+1) или value (E=C)
  stripNotParens?: boolean; // ГДЕ/ИМЕЮЩИЕ: `(НЕ поле)` → `НЕ поле` (конструктор снимает скобки)
  // Дельта отступа подзапроса `В (ВЫБРАТЬ …)` для листа на orLvl=0 (фаза 6.15.9):
  // корневое ГДЕ — 2 (`(ВЫБРАТЬ` на ind+2), условия ВНУТРИ В-подзапроса — 1.
  subDelta0?: number;
  // КОРНЕВАЯ ИЛИ-цепочка ИМЕЮЩИЕ ВНУТРИ подзапроса-операнда условия `В (ВЫБРАТЬ …
  // ИМЕЮЩИЕ A И B ИЛИ C И D)`: оракул НЕ оборачивает её во внешние скобки (в отличие
  // от ИМЕЮЩИЕ верхнего уровня запроса, где обёртка добавляется). Флаг взводится
  // только на КОРНЕВОЙ вызов renderBool такого ИМЕЮЩИЕ и снимается на первом же
  // уровне рекурсии (вложенные ИЛИ-группы скобки сохраняют). Фаза 6.16.
  rootOrNoParens?: boolean;
}

/** Дельта отступа подзапроса листа по глубине ИЛИ (см. orDelta в renderBool). */
function subDelta(orLvl: number, ctx: RenderCtx): number {
  return orLvl === 0 ? ctx.subDelta0 ?? 2 : 1;
}

function tabs(n: number): string {
  return TAB.repeat(n);
}

/**
 * В ГДЕ/ИМЕЮЩИЕ конструктор снимает скобки вокруг отрицания одиночной ссылки на
 * поле: `(НЕ Алиас.Путь[.Путь…])` → `НЕ Алиас.Путь`. Скобки сохраняются, если под
 * `НЕ` стоит что-то сложнее ссылки (сравнение, ЕСТЬ NULL, В(…), вложенные скобки,
 * вызов функции и т. п.). Лист уже включает внешние скобки дословно.
 */
// Группа `(НЕ Алиас.Путь)` в начале строки; за ней допускается дословный хвост
// (например, ошибочно захваченный парсерном `\n\nУПОРЯДОЧИТЬ ПО …`), который
// обязан начинаться с пробельного символа или конца строки — это гарантирует, что
// мы сняли скобки именно вокруг отрицания одиночного поля, а не вокруг чего-то,
// что продолжается без разрыва (`(НЕ a.X) И …` сюда не попадёт: `И` следует за
// пробелом, но это уже верхнеуровневый булев оператор, который формируется отдельной
// веткой needsFormatting и в stripNegatedFieldParens не приходит).
const NEGATED_FIELD_RE = /^\(\s*НЕ\s+([\p{L}_][\p{L}\p{N}_]*(?:\.[\p{L}_][\p{L}\p{N}_]*)*)\s*\)(\s[\s\S]*)?$/u;
export function stripNegatedFieldParens(text: string): string {
  const m = NEGATED_FIELD_RE.exec(text);
  if (!m) return text;
  return `НЕ ${m[1]}${m[2] ?? ''}`;
}

/**
 * `НЕ(Алиас.Путь)` → `НЕ Алиас.Путь` (фаза 6.15.11b, MCP): конструктор 1С снимает
 * скобки вокруг отрицания ОДИНОЧНОЙ ссылки на поле, когда `НЕ` стоит вплотную к
 * скобке-операнду (`НЕ(поле)`, в отличие от `(НЕ поле)` — это stripNegatedFieldParens).
 * Скобки сохраняются, если внутри что-то сложнее ссылки (сравнение, функция,
 * запятая, вложенные скобки) — консервативно, чтобы не задеть правила 6.14.
 * Применяется глобально по тексту листа (несколько `НЕ(поле)` в И/ИЛИ-цепочке).
 */
const NOT_FIELD_PARENS_RE =
  /(^|[^\p{L}\p{N}_])НЕ\(\s*([\p{L}_][\p{L}\p{N}_]*(?:\.[\p{L}_][\p{L}\p{N}_]*)*)\s*\)/gu;
export function stripNotFieldParens(text: string): string {
  return text.replace(NOT_FIELD_PARENS_RE, (_m, pre: string, path: string) => `${pre}НЕ ${path}`);
}

function renderBool(
  node: Node,
  ind: number,
  andCont: number,
  orLvl: number,
  ctx: RenderCtx,
  caseE: number = ind + 1,
  subInd?: number,
  // База отступа продолжения для скобочной группы, ОТКРЫВАЮЩЕЙСЯ на ведущей строке
  // этого поддерева (строка КОГДА): первый операнд печатается инлайн, поэтому `(`
  // встаёт на строке КОГДА, и продолжения (`ИЛИ`/`И`) внутри этой группы конструктор
  // отбивает на whenInd+2+глубина_скобок, а НЕ на ind+orDelta (ind=whenInd инлайна).
  // Зеркало листового правила (condParen в reindentLeafCase, фаза 6.16.44).
  leadParenBase?: number
): string[] {
  switch (node.kind) {
    case 'or': {
      // Корневая ИЛИ-цепочка ИМЕЮЩИЕ внутри подзапроса-операнда условия: оракул не
      // оборачивает её во внешние скобки. Снимаем флаг сразу — вложенные ИЛИ-группы
      // (операнды) скобки сохраняют (фаза 6.16).
      const noWrap = ctx.rootOrNoParens === true;
      ctx.rootOrNoParens = false;
      const orDelta = orLvl === 0 ? 2 : 1;
      // Скобочная ИЛИ-группа, вложенная как операнд0 И-цепочки, которая сама — операнд
      // верхнеуровневого ИЛИ (`((A ИЛИ B) И C ИЛИ D)`): конструктор выравнивает её `ИЛИ`
      // с конъюнктами `И` той же И-цепочки (andCont), а не на ind+orDelta (приоритет
      // И>ИЛИ держит группу и её соседей-`И` на одном продолжении). max — no-op, когда
      // andCont не глубже ind+orDelta (обычный верхнеуровневый ИЛИ не затрагивается).
      // Зеркало правила renderSelectBool и листового condParen (корпус СчётФактура,
      // УчётНДСУНФ).
      const iliInd = Math.max(ind + orDelta, andCont);
      const childAnd = iliInd + 1;
      const lines: string[] = [];
      // Операнд ИЛИ-цепочки — скобочная И-группа (`(A И B) ИЛИ (C И D)`) или одиночный
      // скобочный предикат-лист (`(X МЕЖДУ a И b) ИЛИ …`, `(X ЕСТЬ NULL) ИЛИ …`): обёртка
      // избыточна (И/предикат связывают крепче ИЛИ), оракул её снимает. Разворачиваем
      // `group(and)`/`group(leaf)` (фаза 6.16.78, корпус ОбработкаНовостей, ИМЕЮЩИЕ
      // СопоставлениеНоменклатуры). `group(or)` НЕ трогаем (значимая вложенная обёртка).
      const orOperands = node.operands.map((op) =>
        op.kind === 'group' && (op.child.kind === 'and' || op.child.kind === 'leaf') ? op.child : op
      );
      orOperands.forEach((op, k) => {
        if (k === 0) {
          // operand0 печатается на отступе ind; CASE-операнд → E=ind.
          // Подзапрос листа-операнда — на childAnd (выравнен с операндами ИЛИ).
          // ИСКЛЮЧЕНИЕ (фаза 6.16.51): листовой операнд0 с ВЛОЖЕННЫМ ВЫБОР
          // (`(СУММА(ВЫБОР…КОНЕЦ) <> 0 ИЛИ …)` в ИМЕЮЩИЕ/ГДЕ): охватывающая `(` ИЛИ-группы
          // стоит на строке операнда0, и конструктор отбивает его ВЫБОР на том же
          // уровне, что и ВЫБОР операндов `ИЛИ` (E=iliInd), а не на ind. Узкий гейт:
          // булев слот, операнд0 — лист с многострочным ВЫБОР. Прочие операнды0
          // (поле/подзапрос/вложенная группа) идут прежним путём (E=ind), байт-в-байт.
          // То же и для СТРУКТУРНОГО CASE-операнда0 (`(ВЫБОР…КОНЕЦ <op>/МЕЖДУ … ИЛИ …)`):
          // охватывающая `(` ИЛИ-группы на строке операнда0, и его ВЫБОР встаёт на
          // уровне ВЫБОР операндов ИЛИ (E=iliInd), а не на ind (фаза 6.16.75).
          const op0CaseE =
            ctx.caseBoolean &&
            ((op.kind === 'leaf' && /(^|[^\p{L}\p{N}_])ВЫБОР(?:[^\p{L}\p{N}_]|$)/u.test(op.text) && op.text.includes('\n')) ||
              op.kind === 'case')
              ? iliInd
              : ind;
          const sub = renderBool(op, ind, childAnd, orLvl + 1, ctx, op0CaseE, childAnd, leadParenBase);
          if (!noWrap) sub[0] = '(' + sub[0];
          lines.push(...sub);
        } else {
          // operandK на отступе iliInd; CASE-операнд → E=iliInd.
          const sub = renderBool(op, iliInd, childAnd, orLvl + 1, ctx, iliInd, childAnd);
          sub[0] = tabs(iliInd) + 'ИЛИ ' + sub[0];
          lines.push(...sub);
        }
      });
      if (!noWrap) lines[lines.length - 1] += ')';
      return lines;
    }
    case 'and': {
      const lines: string[] = [];
      node.operands.forEach((op0, k) => {
        // Скобочная И-группа в позиции operand0 И-цепочки (`(A И B) И C`) — обёртка
        // избыточна (И ассоциативен, левый conjunct сливается в родительскую цепочку),
        // и оракул её снимает. Снимаем ТОЛЬКО на operand0 (`X И (A И B)` — НЕ operand0 —
        // оракул скобки сохраняет, фаза). `group(or)` значим — не трогаем.
        const op = k === 0 && op0.kind === 'group' && op0.child.kind === 'and' ? op0.child : op0;
        if (k === 0) {
          lines.push(...renderBool(op, ind, andCont, orLvl, ctx, caseE, subInd, leadParenBase));
        } else {
          // operandK на отступе andCont; CASE-операнд → E=andCont+1 на ВЕРХНЕМ уровне
          // И-цепочки ГДЕ (склейка `И ВЫБОР`, фаза 6.15.19). Но когда сама И-цепочка —
          // ОПЕРАНД верхнеуровневого ИЛИ (orLvl>0: `A ИЛИ B И ВЫБОР…КОНЕЦ`), конструктор
          // выравнивает КОНЕЦ ВЫБОР со строкой `И ВЫБОР` (E=andCont) — корпус.
          const condCaseE = orLvl === 0 ? andCont + 1 : andCont;
          const sub = renderBool(op, andCont, andCont + 1, orLvl, ctx, condCaseE);
          sub[0] = tabs(andCont) + 'И ' + sub[0];
          lines.push(...sub);
        }
      });
      return lines;
    }
    case 'not': {
      // НЕ-блок над скобочной группой конструктор печатает `НЕ(` слитно, продолжения
      // на ind + orDelta + 1 (фаза 6.14, MCP). Это верно и для ГДЕ/ИМЕЮЩИЕ
      // (stripNotParens), и для условия КОГДА внутри ВЫБОР — оракул `И НЕ(… ИЛИ …)`
      // выравнивает ИЛИ на cont+1 и убирает пробел после НЕ (фаза 6.16.67). ПО (ON)
      // идёт другим путём (formatJoinConjunct), его это не затрагивает.
      if (node.child.kind === 'group') {
        return renderNotGroup(node.child.child, ind, orLvl, ctx);
      }
      // Структурное НЕ сдвигает подзапрос листа на +1 (как ведущее НЕ в листе). Над
      // ВЫБОР НЕ так же сдвигает CASE на +1 (`И НЕ ВЫБОР…КОНЕЦ`: КОНЕЦ = caseE+1, КОГДА
      // = caseE+2 — слово ВЫБОР печатается инлайн после `НЕ `, корпус ОстаткиТоваров).
      const si = (subInd ?? ind + subDelta(orLvl, ctx)) + 1;
      const childCaseE = node.child.kind === 'case' ? caseE + 1 : caseE;
      const sub = renderBool(node.child, ind, andCont, orLvl, ctx, childCaseE, si);
      sub[0] = 'НЕ ' + sub[0];
      return sub;
    }
    case 'group': {
      const child = node.child;
      if (child.kind === 'or') {
        // Группа, чья `(` открывается на ВЕДУЩЕЙ строке (инлайн после КОГДА), И
        // вложенная в верхнеуровневый ИЛИ условия (orLvl≥1): её ИЛИ конструктор
        // отбивает от базы продолжения условия (leadParenBase=whenInd+2), а не от
        // ind=whenInd инлайна — иначе вышло бы ind+orDelta=whenInd+1 (на 2 мельче).
        // При orLvl=0 (верх условия — чистое И) ведущая группа уже корректна через
        // orDelta=2 (ind+2=whenInd+2), поэтому НЕ подменяем. Зеркало листового правила
        // (condParen + приоритет И>ИЛИ в reindentLeafCase, фаза 6.16.44).
        if (leadParenBase !== undefined && orLvl >= 1) {
          return renderBool(child, leadParenBase, andCont, orLvl, ctx, caseE, subInd, leadParenBase + 1);
        }
        return renderBool(child, ind, andCont, orLvl, ctx, caseE, subInd);
      }
      // Скобка-ГРУППИРОВКА, охватывающая прямо ВЫБОР (`И (ВЫБОР … КОНЕЦ)`), добавляет
      // CASE один уровень отступа: КОНЕЦ = caseE+1 (КОГДА=caseE+2 …). Без этого весь
      // блок уезжал на −1 (фаза 6.16.75). Зеркало листового C1b. Иные дети группы
      // (сравнение/вызов/вложенная группа) — прежний caseE.
      const childCaseE = child.kind === 'case' ? caseE + 1 : caseE;
      const sub = renderBool(
        child,
        ind,
        andCont,
        orLvl,
        ctx,
        childCaseE,
        subInd,
        leadParenBase === undefined ? undefined : leadParenBase + 1
      );
      sub[0] = '(' + sub[0];
      sub[sub.length - 1] += ')';
      return sub;
    }
    case 'case': {
      // E задаётся вызывающим (caseE); печатаем с явным E.
      return renderCaseE(node, caseE, ctx);
    }
    case 'leaf': {
      // Внутриконъюнктный разрыв разработчика (фаза 6.16.72): разработчик разорвал
      // ОДИН конъюнкт по границе оператора (`Поле <>` + RHS `ЗНАЧЕНИЕ(…)` на след.
      // строке) или развернул список значений `В (\n a,\n b)` — конструктор 1С
      // сшивает оператор+RHS (список значений) обратно в ОДНУ строку перед раскладкой
      // отступов. Лист здесь — уже отдельный конъюнкт (верхнеуровневые И/ИЛИ его
      // расщепили), поэтому flattenMultilineLeaf безопасен: он сам отказывается
      // сплющивать лист с подзапросом (ВЫБРАТЬ), вложенным ВЫБОР или булевым
      // оператором на любой глубине — их многострочную геометрию не трогаем.
      let t = ctx.stripNotParens ? stripNotFieldParens(stripNegatedFieldParens(flattenMultilineLeaf(node.text))) : flattenMultilineLeaf(node.text);
      // Снятие избыточных скобок вокруг операндов булева/предикатного слоя (как оракул):
      // `НЕ (Поле В (…))` → `НЕ Поле В (…)`, `(Поле ЕСТЬ NULL)` → `Поле ЕСТЬ NULL`,
      // `Поле = (&П)` → `Поле = &П`. Применяем во всех булевых слотах (лист — полный
      // предикатный операнд; В-список/подзапрос НЕ затрагивается, см. stripRedundantLeafParens).
      t = stripRedundantLeafParens(t);
      // Голый операнд-приведение ВЫРАЗИТЬ(…) в сравнении — в скобках (фаза 6.15.12).
      t = wrapBareCastOperand(t);
      // Лист-членство `Поле В (ВЫБРАТЬ … ИЗ …)`, набранный ИНЛАЙН (подзапрос на одной
      // строке): reindentLeafSubquery умеет лишь сдвигать УЖЕ многострочное тело, инлайн
      // он не раскладывает. Через хук генератора перепарсиваем внутренний запрос и
      // рендерим канонически (`(ВЫБРАТЬ` на subBase, тело глубже). Гейт узкий: `В (ВЫБРАТЬ`
      // подряд (инлайн) и хук распознал лист (иначе — прежний путь). Фаза 6.16.
      if (
        inlineSubqueryReflow &&
        /(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*\(\s*ВЫБРАТЬ(?![\p{L}\p{N}_])/iu.test(t)
      ) {
        const reflowed = inlineSubqueryReflow(t, subInd ?? ind + subDelta(orLvl, ctx));
        if (reflowed) return reflowed;
      }
      // Подзапрос внутри листа — перебазировка на контекстный отступ (фаза 6.15.9).
      const rebased = reindentLeafSubquery(t, subInd ?? ind + subDelta(orLvl, ctx));
      // Вложенный в лист ВЫБОР (`(ВЫБОР …)`, `СУММА(ВЫБОР …)`) — КОНЕЦ на E,
      // равный отступу, который получил бы структурный ВЫБОР-узел в этой позиции
      // (`caseE`), плюс число ВЫЗОВ-функции скобок, остающихся открытыми к слову
      // ВЫБОР (funcParenDepth). Это согласует лист-CASE внутри условия КОГДА
      // (операнд0 / одиночный лист) с раскладкой структурного CASE: КОНЕЦ = caseE,
      // КОГДА = caseE+1, … (фаза 6.16.20, MCP-пробы `Справочник.Валюты`).
      return [appendIsNotNullTrailingSpace(reindentLeafCase(rebased, caseE, true))];
    }
  }
}

// --- Printer (КОГДА-condition) ----------------------------------------------

/**
 * Условие после КОГДА (булев слот). Особенности конструктора:
 *   - верхняя OR/группа НЕ оборачивается в скобки (границы задаёт КОГДА…ТОГДА);
 *   - продолжения (`ИЛИ x` / `И x`) — на отступе whenInd + 2;
 *   - первый операнд печатается инлайн после `КОГДА ` (первая строка без отступа).
 */
function renderWhenCondition(node: Node, whenInd: number, ctx: RenderCtx): string[] {
  const contInd = whenInd + 2;
  // Условие КОГДА вида `НЕ(группа)` конструктор печатает как НЕ-блок: `НЕ(` слитно,
  // продолжения на whenInd+3 (на один глубже обычного contInd=whenInd+2),
  // ИЛИ внутри — ещё +1 (фаза 6.15.20, MCP). Иначе вышло бы `НЕ (` с пробелом.
  if (node.kind === 'not' && node.child.kind === 'group') {
    return renderNotGroup(node.child.child, whenInd, 0, ctx);
  }
  switch (node.kind) {
    case 'group':
      return renderWhenCondition(node.child, whenInd, ctx);
    case 'or': {
      const lines: string[] = [];
      // Операнд ИЛИ-условия КОГДА — скобочная И-группа или одиночный скобочный
      // предикат-лист (`(X МЕЖДУ a И b) ИЛИ …`): обёртка избыточна, оракул её снимает
      // (фаза 6.16.78, корпус ОбработкаНовостей). `group(or)` сохраняем.
      const orOps = node.operands.map((op) =>
        op.kind === 'group' && (op.child.kind === 'and' || op.child.kind === 'leaf') ? op.child : op
      );
      orOps.forEach((op, k) => {
        if (k === 0) {
          // Подзапрос операнда0 выравнивается с операндами ИЛИ: contInd+1 (MCP, 6.15.9).
          // ВЫБОР как операнд0 верхнеуровневого ИЛИ КОГДА-условия: его КОНЕЦ конструктор
          // выравнивает со строками ИЛИ (E = contInd = whenInd+2), а НЕ на whenInd+1, как
          // у ВЫБОР, целиком составляющего условие (фаза 6.15.28, MCP). Это верно и когда
          // ВЫБОР не голый, а ВЛОЖЕН в листовой вызов операнда0 (`ЕСТЬNULL(ВЫБОР…)`):
          // лист-CASE так же выравнивается на contInd (фаза 6.16.20, MCP).
          const op0HasCase = op.kind === 'case' || (op.kind === 'leaf' && leafHasCase(op.text));
          const op0CaseE = op0HasCase ? contInd : whenInd + 1;
          lines.push(...renderBool(op, whenInd, contInd + 1, 1, ctx, op0CaseE, contInd + 1, contInd));
        } else {
          // Операнд-продолжение `ИЛИ ВЫБОР…КОНЕЦ`: слово ВЫБОР печатается ИНЛАЙН после
          // `ИЛИ `, поэтому КОНЕЦ вложенного ВЫБОР конструктор выравнивает СО строкой
          // `ИЛИ ВЫБОР` (E = contInd), а не на contInd+1. Зеркало операнда0 (op0CaseE) и
          // continuation-операнда И-цепочки условия КОГДА (фаза 6.16.62).
          const opHasCase = op.kind === 'case' || (op.kind === 'leaf' && leafHasCase(op.text));
          const opCaseE = opHasCase ? contInd : contInd + 1;
          const sub = renderBool(op, contInd, contInd + 1, 1, ctx, opCaseE, contInd + 1);
          sub[0] = tabs(contInd) + 'ИЛИ ' + sub[0];
          lines.push(...sub);
        }
      });
      return lines;
    }
    case 'and': {
      // OR-конъюнкты внутри КОГДА-условия используют orDelta=1 (orLvl=1), КРОМЕ
      // ВЕДУЩЕГО операнда-группы `(… ИЛИ …)`: его ИЛИ конструктор выравнивает с
      // И-конъюнктами на contInd (orDelta=2, orLvl=0) — `КОГДА (НЕ A\n\t\tИЛИ НЕ B)
      // \n\t\tИ C` (фаза 6.15.20, MCP).
      const lines: string[] = [];
      node.operands.forEach((op, k) => {
        if (k === 0) {
          // ВЫБОР (голый или вложенный в лист `ЕСТЬNULL(ВЫБОР…)`) операнда0 И-условия
          // КОГДА конструктор выравнивает на contInd, как и в ИЛИ-условии (E=contInd
          // плюс число вызов-скобок; фаза 6.16.20, MCP).
          const op0HasCase = op.kind === 'case' || (op.kind === 'leaf' && leafHasCase(op.text));
          const op0CaseE = op0HasCase ? contInd : whenInd + 1;
          lines.push(...renderBool(op, whenInd, contInd, 0, ctx, op0CaseE, contInd + 1, contInd));
        } else {
          // Операнд-продолжение `И ВЫБОР…КОНЕЦ` — см. ИЛИ-ветку выше: КОНЕЦ на contInd
          // (строка `И ВЫБОР`), а не contInd+1 (фаза 6.16.62).
          const opHasCase = op.kind === 'case' || (op.kind === 'leaf' && leafHasCase(op.text));
          const opCaseE = opHasCase ? contInd : contInd + 1;
          const sub = renderBool(op, contInd, contInd + 1, 1, ctx, opCaseE, contInd + 1);
          sub[0] = tabs(contInd) + 'И ' + sub[0];
          lines.push(...sub);
        }
      });
      return lines;
    }
    default:
      // Одиночный лист условия КОГДА: подзапрос на whenInd+2 (MCP, 6.15.9).
      return renderBool(node, whenInd, contInd, 1, ctx, whenInd + 1, whenInd + 2);
  }
}

// --- Printer (CASE) ---------------------------------------------------------

/**
 * Рендер ВЫБОР. `cursorInd` — табы строки `ВЫБОР` (она печатается инлайн родителем,
 * поэтому возвращаемая первая строка = 'ВЫБОР' без отступа). `boolean` — слот
 * (true → E=C+1, false → E=C). Возвращает строки; первая — 'ВЫБОР'.
 */
function renderCase(node: Node & { kind: 'case' }, cursorInd: number, ctx: RenderCtx, boolean: boolean): string[] {
  // E — отступ КОНЕЦ. В value-слоте E=cursorInd, в булевом E=cursorInd+1.
  return renderCaseE(node, boolean ? cursorInd + 1 : cursorInd, ctx);
}

/**
 * Рендер ВЫБОР с явным отступом КОНЕЦ = E. Раскладка:
 *   КОГДА=E+1, ТОГДА=E+2, ИНАЧЕ=E+1, КОНЕЦ=E. Первая строка = 'ВЫБОР' (инлайн).
 * Вложенный ВЫБОР после ТОГДА@t/ИНАЧЕ@t → его E = t+1 (value-слот).
 */
/** Текст value-узла (после ТОГДА/ИНАЧЕ). parseValue даёт только leaf или case. */
function valueText(node: Node): string {
  return node.kind === 'leaf' ? node.text : '';
}

/**
 * Строки значения ветки ТОГДА/ИНАЧЕ листового value-узла. Базовый случай —
 * `<keyword> <значение>` одной строкой (подзапрос/В-список переотступаются
 * reindentLeafSubquery). Особый случай — листовой вызов функции с ВЛОЖЕННЫМ
 * СЕЛЕКТОРНЫМ ВЫБОР (`ЕСТЬNULL(…, ЕСТЬNULL(ВЫБОР sel КОГДА … КОНЕЦ, …))`):
 * конструктор сплющивает аргументы и рефлоит встроенный CASE построчно
 * (reflowLeafSelectorCase, фаза 6.15.26). Первая строка рефлоу приклеивается к
 * ключевому слову ветки, остальные — как есть.
 */
/**
 * Однострочное значение ветки ТОГДА/ИНАЧЕ с ВЕРХНЕУРОВНЕВЫМ ИЛИ конструктор 1С
 * раскладывает многострочно: операнд0 инлайн после ключевого слова, каждый
 * следующий — `ИЛИ <операнд>` на отступе kwInd+2; ОХВАТЫВАЮЩИЕ скобки операнда
 * (`(НЕ ЕСТЬNULL(…))`, `(Поле)`) снимаются как избыточная группировка (фаза
 * 6.15.28, MCP). Возвращает null, если значение НЕ является однострочной
 * верхнеуровневой ИЛИ-цепочкой (узкий триггер — иначе раскладку даёт fallback).
 */
/**
 * Снимает ровно одну ОХВАТЫВАЮЩУЮ пару скобок, если она оборачивает ВСЁ выражение
 * (`(НЕ ЕСТЬNULL(…))` → `НЕ ЕСТЬNULL(…)`, `(Поле)` → `Поле`). Если первая `(` не
 * парна последней `)` (скобки лишь частичные, напр. `(a) + (b)`) — текст без
 * изменений.
 */
function stripEnclosingParens(text: string): string {
  const t = text.trim();
  if (!t.startsWith('(') || !t.endsWith(')')) return t;
  let depth = 0;
  let inStr = false;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '(') depth++;
    else if (ch === ')') {
      depth--;
      // Закрылась стартовая скобка не на последнем символе — она не охватывающая.
      if (depth === 0 && i !== t.length - 1) return t;
    }
  }
  return depth === 0 ? t.slice(1, -1).trim() : t;
}

function renderOrValueLines(keyword: 'ТОГДА' | 'ИНАЧЕ', value: string, kwInd: number): string[] | null {
  let tree: Node;
  try {
    tree = new Parser(value.trim(), false).parse();
  } catch {
    return null;
  }
  // Верхнеуровневый ИЛИ конструктор раскладывает многострочно (фаза 6.15.28); такой
  // же раскладке (операнд0 инлайн, продолжения на kwInd+2) подчиняется и
  // верхнеуровневый И — значение ветки ТОГДА/ИНАЧЕ, являющееся булевой И-цепочкой
  // (`ТОГДА A\n\t\tИ B`, delta=2 от ТОГДА; корпус, 17/17). Для ИЛИ значение может
  // быть однострочным в исходнике (конструктор сам переносит); для И — только уже
  // многострочный исходник (однострочное `ТОГДА A И B` конструктор оставляет инлайн).
  // Однострочное значение конструктор переносит сам только для ИЛИ; однострочную
  // И-цепочку (`ТОГДА A И B`) он оставляет ИНЛАЙН. Поэтому И раскладываем лишь когда
  // исходник УЖЕ многострочный (delta=2 от ключевого слова, корпус 17/17). ИЛИ —
  // в любом случае (однострочный исходник тоже).
  if (tree.kind === 'and') {
    if (!value.includes('\n')) return null;
  } else if (tree.kind !== 'or') {
    return null;
  }
  // Вложенный ВЫБОР как операнд (`ИНАЧЕ ВЫБОР…КОНЕЦ И ВЫБОР…`) этой раскладке не
  // подчиняется — его геометрию (E = отступ ключевого слова + 1) даёт основной путь
  // renderCaseE; здесь обрабатываем только листовые/скобочные/НЕ-операнды.
  if (tree.operands.some((op) => op.kind === 'case' || (op.kind === 'group' && op.child.kind === 'case'))) {
    return null;
  }
  const op0Word = tree.kind === 'or' ? 'ИЛИ' : 'И';
  const ctx: RenderCtx = { cont: 1, caseBoolean: false };
  const contInd = kwInd + 2;
  const lines: string[] = [];
  tree.operands.forEach((op, k) => {
    // Снять охватывающие скобки операнда (избыточная группировка). Структурную
    // группу (`(a ИЛИ b)`) разворачиваем через child; листовой операнд, целиком
    // обёрнутый в скобки (`(НЕ ЕСТЬNULL(…))`, `(Поле)`) — снимаем строкой.
    // ИСКЛЮЧЕНИЕ: ИЛИ-группа как операнд И-цепочки (`A И (B ИЛИ C ИЛИ D)`) — скобки
    // ОБЯЗАТЕЛЬНЫ (И связывает крепче ИЛИ), оракул их СОХРАНЯЕТ; не разворачиваем
    // (фаза 6.16.77, корпус УчетНДФЛ). Для самой ИЛИ-цепочки и для И-операнда той же
    // ассоциативности (`A И (B И C)`) обёртка остаётся избыточной — разворачиваем.
    const keepOrGroup = tree.kind === 'and' && op.kind === 'group' && op.child.kind === 'or';
    const bare = keepOrGroup ? op
      : op.kind === 'group' ? op.child
      : op.kind === 'leaf' ? ({ kind: 'leaf', text: stripEnclosingParens(op.text) } as Node)
      : op;
    // ВЛОЖЕННАЯ ИЛИ-группа как операнд И-цепочки значения (`ИНАЧЕ (A ИЛИ B) И C`)
    // выравнивает свой `ИЛИ` с конъюнктами `И` цепочки (на contInd), поэтому ей
    // передаём andCont=contInd (iliInd=max(ind+1, contInd)=contInd; корпус
    // КарточкаУчетаПоСтраховымВзносам). Прочие операнды (плоская И-цепочка `A И B`,
    // листья) — andCont=contInd+1, чтобы их собственные конъюнкты `И` шли на contInd+1
    // (корпус РаботаСБонусами `ТОГДА A И B ИЛИ C`).
    const opAndCont = keepOrGroup ? contInd : contInd + 1;
    const sub = renderSelectBool(bare, k === 0 ? kwInd : contInd, opAndCont, 1, ctx, contInd + 1);
    sub[0] = k === 0 ? `${tabs(kwInd)}${keyword} ${sub[0]}` : `${tabs(contInd)}${op0Word} ${sub[0]}`;
    lines.push(...sub);
  });
  return lines;
}

function renderBranchValueLines(keyword: 'ТОГДА' | 'ИНАЧЕ', value: string, kwInd: number): string[] {
  const orLines = renderOrValueLines(keyword, value, kwInd);
  if (orLines !== null) return orLines;
  const reflowed = reflowLeafSelectorCase(value, kwInd + 2);
  if (reflowed !== null) {
    const parts = reflowed.split('\n');
    return [tabs(kwInd) + keyword + ' ' + parts[0], ...parts.slice(1)];
  }
  // Вложенный ВЫБОР, открытый бинарным оператором на ВЕРХНЕМ уровне скобок значения
  // ветки (`ТОГДА Расчеты.Сумма * ВЫБОР … КОНЕЦ`): reflowLeafSelectorCase его не ловит
  // (требует ВЫБОР на глубине скобок > 0, внутри вызова функции). reindentLeafSubquery
  // ниже его не трогает (нет подзапроса (ВЫБРАТЬ) — возвращает текст как есть, оставляя
  // авторский отступ). Конструктор раскладывает такой CASE построчно с E (КОНЕЦ) =
  // отступ ТОГДА/ИНАЧЕ + 1: КОГДА=E+1, ТОГДА=E+2, ИНАЧЕ=E+1, КОНЕЦ=E (фаза 6.16.56).
  // Гейт узкий: значение многострочное, открывающий ВЫБОР стоит на глубине скобок 0
  // (хвост строки `… <oп> ВЫБОР` вне всякой группы), нет подзапроса. reindentLeafCase
  // сам откатывается (возвращает вход), если геометрия нестандартная (несбалансированы
  // скобки, опустошён стек) — тогда падаем в общий путь ниже без изменений.
  // То же и для ЦЕПОЧКИ верхнеуровневых CASE-арифметики (`ВЫБОР…КОНЕЦ - ВЫБОР…КОНЕЦ`):
  // значение многострочное, без подзапроса, и ОТКРЫВАЕТСЯ верхнеуровневым ВЫБОР (первая
  // структурная строка — голое слово `ВЫБОР` на глубине скобок 0). reindentLeafCase
  // раскладывает несколько ВЫБОР-блоков и сам бракует нестандартную геометрию (корпус
  // УчётСтраховыхВзносовУНФ: `ИНАЧЕ ВЫБОР…КОНЕЦ - ВЫБОР…КОНЕЦ`).
  if (value.includes('\n') && (isSingleTopLevelCaseValue(value) || opensWithTopLevelVybor(value) || opensWithVyborInCall(value))) {
    // opensWithTopLevelVybor (открыватель — хвост `… <вызов>( … / ВЫБОР`, ЦЕПОЧКА
    // `ВЫБОР…КОНЕЦ - ВЫБОР…КОНЕЦ`, или CASE внутри вызова без селектора) считает глубину
    // CASE ТОЛЬКО по ВЫЗОВ-функции скобкам (funcParenDepth=true): скобка-ГРУППИРОВКА
    // арифметики (`(Цена / (ВЫБОР`) уровня НЕ добавляет — корпус Ценообразование. Путь
    // isSingleTopLevelCaseValue сохраняет прежнюю effectiveDepth-семантику (байт-в-байт).
    const useFuncParen = !isSingleTopLevelCaseValue(value);
    const reCase = reindentLeafCase(value, kwInd + 1, useFuncParen);
    if (reCase !== value) {
      const parts = reCase.split('\n');
      // Голый ВЫРАЗИТЬ-операнд в голове значения (`ТОГДА (ВЫРАЗИТЬ(…)) * ВЫБОР …`) —
      // в скобках (фаза 6.16.69); строка-голова не открывает свой ВЫБОР до оператора.
      return [tabs(kwInd) + keyword + ' ' + wrapBareCastOperand(parts[0]), ...parts.slice(1)];
    }
  }
  // Избыточные охватывающие скобки вокруг ЦЕЛОГО значения ветки конструктор снимает
  // (`ТОГДА (a - b)` → `ТОГДА a - b`; фаза 6.16.37). Строго консервативно: только
  // полностью охватывающая пара без ВЫРАЗИТЬ/ВЫБОР/булева оператора внутри.
  const flat = flattenMultilineLeaf(value);
  // Голый ВЫРАЗИТЬ-операнд сравнения/арифметики в значении ТОГДА/ИНАЧЕ — в скобках
  // (`ТОГДА (ВЫРАЗИТЬ(…)) - X`; фаза 6.16.69), как и в верхнеуровневом сравнении.
  // reprintLeafArithmetic дополнительно ловит унарный `-ВЫРАЗИТЬ(…)` → `-(ВЫРАЗИТЬ(…))`.
  // reprintLeafComparison снимает избыточную обёртку арифм. операнда сравнения
  // (`(A - B) > 0` → `A - B > 0`; фаза 6.16.78), пасует на булевой/предикатной логике.
  const bare = reprintLeafComparison(reprintLeafArithmetic(wrapBareCastOperand(stripRedundantCaseClauseParens(flat))));
  // Значение ветки — членство `Поле В (ВЫБРАТЬ …)` с подзапросом, чьё тело конструктор
  // переотрисовывает (напр. оборачивает верхнеуровневую ИЛИ-цепочку ГДЕ в скобки), тогда
  // как reindentLeafSubquery лишь равномерно сдвигает авторский текст. Через хук генератора
  // (reflowInlineMembershipSubquery) перепарсиваем подзапрос и рендерим канонически: поле
  // на kwInd, `(ВЫБРАТЬ` на kwInd+2. Хук сам решает (узкий гейт), нужен ли ре-флоу — иначе
  // возвращает null, и мы идём прежним (дословным) путём байт-в-байт. Фаза 6.16.
  if (
    inlineSubqueryReflow &&
    /(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*\(\s*ВЫБРАТЬ(?![\p{L}\p{N}_])/iu.test(bare)
  ) {
    const reflowed = inlineSubqueryReflow(bare, kwInd + 2);
    if (reflowed) {
      const head = reflowed[0].replace(/^\t+/u, '');
      return [tabs(kwInd) + keyword + ' ' + head, ...reflowed.slice(1)];
    }
  }
  return [tabs(kwInd) + keyword + ' ' + reindentLeafSubquery(bare, kwInd + 2)];
}

function renderCaseE(node: Node & { kind: 'case' }, E: number, ctx: RenderCtx): string[] {
  const lines: string[] = [node.selector ? 'ВЫБОР ' + node.selector : 'ВЫБОР'];
  for (const cl of node.clauses) {
    const whenInd = E + 1;
    const whenLines = renderWhenCondition(cl.whenNode, whenInd, ctx);
    whenLines[0] = tabs(whenInd) + 'КОГДА ' + whenLines[0];
    lines.push(...whenLines);
    const thenInd = E + 2;
    if (cl.thenNode.kind === 'case') {
      const sub = renderCaseE(cl.thenNode, thenInd + 1, ctx);
      sub[0] = tabs(thenInd) + 'ТОГДА ' + sub[0];
      lines.push(...sub);
    } else {
      // Подзапрос значения ТОГДА — на thenInd+2 (MCP, 6.15.9). Многострочный
      // не-подзапросный операнд `В`/`В ИЕРАРХИИ` (одиночный параметр, список
      // значений, `ЗНАЧЕНИЕ(…)`-список) конструктор печатает ИНЛАЙН — сплющиваем
      // (фаза 6.15.11c); подзапрос flattenMultilineLeaf не трогает (стоп-слово ВЫБРАТЬ).
      lines.push(...renderBranchValueLines('ТОГДА', valueText(cl.thenNode), thenInd));
    }
  }
  if (node.elseExpr) {
    const elseInd = E + 1;
    if (node.elseExpr.kind === 'case') {
      const sub = renderCaseE(node.elseExpr, elseInd + 1, ctx);
      sub[0] = tabs(elseInd) + 'ИНАЧЕ ' + sub[0];
      lines.push(...sub);
    } else {
      // Подзапрос значения ИНАЧЕ — на elseInd+2 (MCP, 6.15.9). Не-подзапросный
      // многострочный операнд `В` — ИНЛАЙН (фаза 6.15.11c, см. ТОГДА выше).
      lines.push(...renderBranchValueLines('ИНАЧЕ', valueText(node.elseExpr), elseInd));
    }
  }
  lines.push(tabs(E) + 'КОНЕЦ' + (node.trailing ? ' ' + node.trailing : ''));
  return lines;
}

// --- public formatExpression ------------------------------------------------

/**
 * Признак мис-парса «вложенный ВЫБОР как ОПЕРАНД СРАВНЕНИЯ внутри условия КОГДА».
 * AST-парсер не строит узел сравнения, чьим операндом служит голый ВЫБОР:
 *   (а) `КОГДА X <= ВЫБОР … КОНЕЦ ТОГДА …` — parseLeaf поглощает слово ВЫБОР в текст
 *       условия (стоп-слова isCase в листе нет) и тормозит на ВНУТРЕННЕМ КОГДА;
 *   (б) `КОГДА ВЫБОР…КОНЕЦ > ВЫБОР…КОНЕЦ ТОГДА …` — parseCase разбирает левый ВЫБОР
 *       узлом, а хвост `> ВЫБОР…` не складывается в простое сравнение
 *       (tryParseSimpleCaseTrailing бракует вложенный ВЫБОР).
 * В обоих случаях ветка ТОГДА условия пустеет / вложение сбивается. Для таких CASE
 * надёжнее построчный текстовый reindentLeafCase (корректно вкладывает внутренние
 * ВЫБОР), чем сломанный AST.
 *
 * Распознаём ТЕКСТОВОЙ сигнатурой: есть строка, ОКАНЧИВАЮЩАЯСЯ голым словом ВЫБОР,
 * непосредственно перед которым (БЕЗ скобки) стоит оператор СРАВНЕНИЯ (`= <> < > <= >=`)
 * или АРИФМЕТИКИ (`+ - * /`). Это «CASE — операнд сравнения/арифметики условия КОГДА»
 * (`X <= ВЫБОР`, `КОНЕЦ > ВЫБОР`, `X - ВЫБОР`).
 *
 * Исключения (там штатный AST-рендер renderCase корректен, а текстовый путь даёт
 * регрессию off-by-one по отступу):
 *   — ВЫБОР в ВЫЗОВЕ функции (`КОНЕЦ > СУММА(ВЫБОР`): перед ВЫБОР скобка, а не оператор —
 *     не матчится регэкспом;
 *   — АРИФМЕТИКА внутри открытой скобки (`ТОГДА ВЫРАЗИТЬ(Сумма * ВЫБОР`): CASE — операнд
 *     арифметики ВНУТРИ вызова (funcParenDepth-геометрия). Для арифметических операторов
 *     требуем нулевой баланс скобок на строке ДО оператора (CASE на верхнем уровне).
 *     Сравнение скобочной защиты не требует — оно всегда граница условия.
 */
function caseHasNestedVyborInWhen(text: string): boolean {
  const COMPARE = new Set(['<=', '>=', '<>', '=', '<', '>']);
  for (const line of text.split('\n')) {
    const m = /(^|[^\p{L}\p{N}_])(<=|>=|<>|=|<|>|\+|-|\*|\/)\s+ВЫБОР\s*$/u.exec(line);
    if (!m) continue;
    if (COMPARE.has(m[2])) return true;
    // Арифметический оператор: фиксируем ТОЛЬКО когда строка — само условие КОГДА
    // (`КОГДА X - ВЫБОР…`), где ВЫБОР открывает CASE-операнд арифметики условия.
    // Прочие `<op> ВЫБОР` (`КОНЕЦ + ВЫБОР` — CASE-АРИФМЕТИКА соседних ВЫБОР; `ТОГДА
    // ВЫРАЗИТЬ(… * ВЫБОР` — CASE в значении ветки) обрабатывает штатный путь, а
    // текстовый дал бы off-by-one. Дополнительно требуем нулевой баланс скобок ДО
    // оператора (CASE на верхнем уровне строки).
    if (!/^[\t ]*КОГДА(?![\p{L}\p{N}_])/u.test(line)) continue;
    const before = line.slice(0, m.index + m[1].length);
    let depth = 0;
    let inStr = false;
    for (const ch of before) {
      if (ch === '"') inStr = !inStr;
      else if (!inStr && ch === '(') depth++;
      else if (!inStr && ch === ')') depth--;
    }
    if (depth === 0) return true;
  }
  return false;
}

/**
 * Печатает выражение в каноническом виде конструктора для указанного слота.
 * Первая строка БЕЗ ведущего отступа (его добавляет вызывающий, прибавляя базовый
 * таб слота); продолжения — с абсолютными табами.
 */
export function formatExpression(raw: string, slot: ExprSlot, rootSubDelta?: number): string {
  const trimmed = raw.trim();
  // Сплющивание многострочных листьев в одну строку — только для полей выборки
  // (слот select); в ГДЕ/ИМЕЮЩИЕ/ПО структура исходника сохраняется дословно
  // (там конструктор переотрисовывает булевы операторы и внутри скобок листа —
  // отдельный механизм; сплющивание дало бы регрессии).
  const parser = new Parser(trimmed, slot === 'select');
  const tree = parser.parse();

  // Дословный хвост: то, что парсер не потребил (например, ошибочно захваченные
  // парсером SDBL `\n\nУПОРЯДОЧИТЬ ПО …` / `\nИТОГИ ПО …` после КОНЕЦ/скобки).
  // Сохраняем как есть (с исходными пробелами), чтобы не терять текст.
  const tail = parser.tail();

  let body: string;
  if (slot === 'where' || slot === 'having') {
    const ctx: RenderCtx = { cont: 1, caseBoolean: true, stripNotParens: true, subDelta0: rootSubDelta };
    // ИМЕЮЩИЕ: верхний OR использует orDelta=1 (ИЛИ на отступе 2), в отличие от
    // ГДЕ (orDelta=2, ИЛИ на 3) — эмулируем стартовым orLvl=1. ГДЕ ВНУТРИ подзапроса-
    // операнда условия `В (ВЫБРАТЬ … ГДЕ …)` конструктор тоже отбивает группу OR на
    // один уровень мельче (как блок подзапроса в целом, фаза 6.16.71): признак —
    // переданная rootSubDelta (взводится только для condition-subquery).
    const startOrLvl = slot === 'having' || rootSubDelta !== undefined ? 1 : 0;
    if (tree.kind === 'case') {
      // Отдельный ВЫБОР-конъюнкт ИМЕЮЩИЕ (парсер дробит `A <> X И ВЫБОР…КОНЕЦ` на два
      // условия; второе — голый ВЫБОР, конъюнкты склеивает renderHaving хвостовым ` И`)
      // конструктор печатает на отступе условия: КОНЕЦ = cont, КОГДА = cont+1 (а НЕ
      // в булевом слоте cont+1/КОНЕЦ). В ГДЕ конъюнкты склеиваются префиксом `И ВЫБОР`,
      // и там ВЫБОР остаётся в булевом слоте (E = cont+1) — фаза 6.15.19, MCP.
      // ВНУТРИ подзапроса-операнда условия (`В (ВЫБРАТЬ … ГДЕ ВЫБОР…КОНЕЦ <> X)`)
      // конструктор печатает CASE-сравнение ГДЕ в НЕ-булевом слоте: КОНЕЦ = cont
      // (вровень с ВЫБОР), КОГДА = cont+1 — а НЕ в булевом (КОНЕЦ = cont+1), как на
      // ВЕРХНЕМ уровне запроса (сверено живым оракулом validate_query: вложенный
      // `ГДЕ ВЫБОР…КОНЕЦ <> 5` даёт КОНЕЦ вровень с ВЫБОР). Признак подзапроса —
      // rootSubDelta задан. Фаза 6.16.
      const caseBoolean = slot === 'where' && rootSubDelta === undefined;
      body = renderCase(tree, ctx.cont, ctx, caseBoolean).join('\n');
    } else if (tree.kind === 'not' && tree.child.kind === 'group') {
      // НЕ-блок целиком (`НЕ (…)`): конструктор печатает `НЕ(` слитно и держит
      // скобки независимо от наличия ИЛИ внутри (фаза 6.14, MCP).
      body = renderNotGroup(tree.child.child, 1, startOrLvl, ctx).join('\n');
    } else {
      // ИМЕЮЩИЕ ВНУТРИ подзапроса-операнда условия (`В (ВЫБРАТЬ … ИМЕЮЩИЕ A И B ИЛИ C
      // И D)`): корневую ИЛИ-цепочку оракул печатает БЕЗ внешних скобок (на верхнем
      // уровне запроса — со скобками). Признак — слот ИМЕЮЩИЕ + condition-subquery
      // (rootSubDelta задан). Флаг подхватывает renderBool на корневом `or`/`group(or)`
      // и снимает после первого уровня. Фаза 6.16.
      if (slot === 'having' && rootSubDelta !== undefined) {
        const root = tree.kind === 'group' ? tree.child : tree;
        if (root.kind === 'or') ctx.rootOrNoParens = true;
      }
      body = renderBool(tree, 1, 1, startOrLvl, ctx).join('\n');
    }
  } else if (slot === 'select') {
    const ctx: RenderCtx = { cont: 1, caseBoolean: false };
    // Мис-парс «вложенный ВЫБОР как RHS сравнения в условии КОГДА» (см.
    // caseHasNestedVyborInWhen): AST сломан — внешний CASE закрывается на КОНЕЦ
    // ВНУТРЕННЕГО ВЫБОР, остаток (`ТОГДА … ИНАЧЕ …`) уходит в tail, ветка ТОГДА
    // условия пустеет. Исходный текст CASE уже канонически структурен — отдаём его
    // построчному reindentLeafCase, который корректно вкладывает внутренний ВЫБОР.
    // Проверяем ДО tail-ветки (она перехватила бы выражение раньше). Если
    // reindentLeafCase не справился (вернул вход) — падаем в штатные ветки ниже.
    if (tree.kind === 'case' && caseHasNestedVyborInWhen(trimmed)) {
      const flat = flattenMultilineLeaf(trimmed);
      const reindented = reindentLeafCase(flat, ctx.cont);
      // reindentLeafCase ПЕРЕОТРИСОВЫВАЕТ все отступы от ctx.cont по структуре
      // ВЫБОР/КОГДА/ТОГДА (от входных отступов не зависит) — берём его результат
      // безусловно: альтернативный AST-рендер для этой сигнатуры заведомо сломан.
      // Требуем лишь, чтобы reindentLeafCase реально РАЗЛОЖИЛ CASE (его выход
      // начинается строкой `ВЫБОР` и содержит переносы) — иначе он забраковал
      // нестандартную геометрию (вернул вход без \n-структуры), и безопаснее
      // штатный путь ниже.
      if (reindented.includes('\n') && /^ВЫБОР(?:[^\p{L}\p{N}_]|$)/u.test(reindented)) {
        return appendIsNotNullTrailingSpace(reindented);
      }
    }
    if (tree.kind === 'case' && tail.trim() !== '') {
      // ВЫБОР — часть арифметики поля (`ВЫБОР…КОНЕЦ + ВЫБОР…КОНЕЦ`): булев парсер
      // забирает только первый ВЫБОР, остаток уходит в tail дословно. Несколько
      // соседних ВЫБОР раскладывает построчный reindentLeafCase (фаза 6.15.19);
      // он переотбивает все КОНЕЦ/КОГДА на E=cont. Если он не справился (вернул
      // вход без изменений) — откатываемся на старую склейку первого ВЫБОР + tail.
      const flat = flattenMultilineLeaf(trimmed);
      // funcParenDepth=true: вложенный ВЫБОР внутри ВЫЗОВ-функции значения ветки
      // (`ТОГДА ВЫРАЗИТЬ(A / (100 + ВЫБОР…КОНЕЦ) …)`) глубину CASE считает по числу
      // открытых ВЫЗОВ-скобок, а скобка-ГРУППИРОВКА арифметики уровня не добавляет —
      // иначе вложенный КОНЕЦ уезжал на −1 (корпус КорректировкаРеализации). Плоская
      // цепочка `ВЫБОР…КОНЕЦ + ВЫБОР…КОНЕЦ` (без скобок) от флага не зависит.
      const reindented = reindentLeafCase(flat, ctx.cont, true);
      body =
        reindented !== flat
          ? reindented
          : renderCase(tree, ctx.cont, ctx, false).join('\n') + tail;
      return body;
    }
    if (tree.kind === 'case') {
      body = renderCase(tree, ctx.cont, ctx, false).join('\n');
    } else {
      // Поле выборки = булево выражение (OR/AND/НЕ): value-слот, orDelta=1, без
      // оборачивающих скобок. operand0 @ base 1, ИЛИ @ base+1. Продолжения
      // верхнеуровневой И-цепочки поля — на base+1 (andCont=2), как у плоской
      // цепочки reindentLeafBool (фаза 6.15.19) и по MCP (фаза 6.15.20).
      body = renderSelectBool(tree, 1, 2, 0, ctx).join('\n');
    }
  } else {
    // join
    const ctx: RenderCtx = { cont: 2, caseBoolean: true };
    body = renderJoin(tree, ctx);
  }

  // Квирк `ЕСТЬ НЕ NULL` (хвостовой/двойной пробел) действует на КАЖДУЮ строку любого
  // структурного вывода (ВЫБОР-ветки, OR/AND-конъюнкты, КАК-псевдоним) — применяем
  // построчно ко всему телу. Хвост (`tail`) — дословный.
  let result = appendIsNotNullTrailingSpace(body) + tail;
  // Хвост-СПИСОК ЗНАЧЕНИЙ оператора `В` после структурного CASE (`ВЫБОР…КОНЕЦ В (\n a,\n
  // b)`): парсер кладёт `В (…)` в дословный tail, разбитый разработчиком по строкам.
  // Конструктор печатает такой список ИНЛАЙН на строке КОНЕЦ — сплющиваем (подзапрос
  // `В (ВЫБРАТЬ …)` flattenInlineValueLists не трогает). Гейт узкий: tail открывает
  // список значений (` В (` с переносом, без ВЫБРАТЬ внутри).
  if (/(?:^|[^\p{L}\p{N}_])В\s*\(\s*\n/u.test(tail) &&
      !/(?:^|[^\p{L}\p{N}_])ВЫБРАТЬ(?![\p{L}\p{N}_])/u.test(tail)) {
    result = flattenInlineValueLists(result);
  }
  return result;
}

/**
 * НЕ-блок в условии ГДЕ/ИМЕЮЩИЕ: `НЕ (…)` (фаза 6.14, MCP). Раскладка:
 *   - первая строка `НЕ(` слитно с первым операндом;
 *   - продолжения (`И x` / `ИЛИ x`) — на отступе cont = ind + orDelta + 1
 *     (корень ГДЕ: 4 таба, корень ИМЕЮЩИЕ: 3, вложенный НЕ: ind + 2 — на один
 *     глубже строк ИЛИ обычного ИЛИ-блока на той же глубине);
 *   - вложенные скобочные ИЛИ-группы и НЕ-блоки внутри операндов — рекурсивно
 *     (ИЛИ на cont+1);
 *   - внешние скобки сохраняются всегда (НЕ синтаксически требует скобок),
 *     даже когда внутри нет ИЛИ.
 * `ind` — отступ строки, на которой начинается `НЕ(` (первая строка без отступа,
 * его добавляет вызывающий).
 */
function renderNotGroup(child: Node, ind: number, orLvl: number, ctx: RenderCtx): string[] {
  const cont = ind + (orLvl === 0 ? 2 : 1) + 1;
  let lines: string[];
  if (child.kind === 'or' || child.kind === 'and') {
    const word = child.kind === 'or' ? 'ИЛИ ' : 'И ';
    lines = [];
    // Когда НЕ(-блок — это OR-цепочка с И-конъюнктами в операндах, конъюнкты `И`
    // ВЕДУЩЕГО операнда конструктор кладёт на тот же отступ, что и `И` прочих
    // операндов — cont+1, на +1 глубже строк `ИЛИ` (приоритет И>ИЛИ; фаза 6.15.21,
    // MCP). Для одиночного операнда (нет верхнеур. ИЛИ) сдвига нет — andCont=cont.
    const op0And = child.kind === 'or' ? cont + 1 : cont;
    child.operands.forEach((op, k) => {
      if (k === 0) {
        // Подзапрос операнда НЕ(-блока — на cont+1 (выравнен по операндам, 6.15.9).
        lines.push(...renderBool(op, ind, op0And, orLvl + 1, ctx, ind + 1, cont + 1));
      } else {
        // CASE-операнд (`ИЛИ ВЫБОР…КОНЕЦ`) выравнивает свой КОНЕЦ со строкой `ИЛИ`
        // (E=cont), как и в основной ветке OR (operandK → E=iliInd) — не на cont+1
        // (корпус КнигаПокупок). Прочие операнды — прежним caseE=cont+1.
        const opCaseE = op.kind === 'case' ? cont : cont + 1;
        const sub = renderBool(op, cont, cont + 1, orLvl + 1, ctx, opCaseE, cont + 1);
        sub[0] = tabs(cont) + word + sub[0];
        lines.push(...sub);
      }
    });
  } else {
    lines = renderBool(child, ind, cont, orLvl + 1, ctx, ind + 1, cont + 1);
  }
  lines[0] = 'НЕ(' + lines[0];
  lines[lines.length - 1] += ')';
  return lines;
}

/**
 * Корень выражения — НЕ над скобочной группой (`НЕ (a И b)`)? Такое условие
 * конструктор переотрисовывает (`НЕ(` слитно, продолжения на фикс. отступе),
 * даже когда внутри нет ИЛИ/ВЫБОР и needsFormatting возвращает false (фаза 6.14).
 */
export function isRootNotGroup(raw: string): boolean {
  const trimmed = (raw ?? '').trim();
  if (!trimmed) return false;
  let tree: Node;
  try {
    tree = new Parser(trimmed).parse();
  } catch {
    return false;
  }
  return tree.kind === 'not' && tree.child.kind === 'group';
}

/**
 * Рендер булева выражения в value-слоте поля выборки. Отличия от ГДЕ:
 *   - OR не оборачивается в скобки;
 *   - orDelta = 1 (а не 2): operand0 @ ind, строки `ИЛИ x` @ ind+1.
 * Листья и НЕ — как обычно (НЕ инлайн).
 */
function renderSelectBool(node: Node, ind: number, andCont: number, orLvl: number, ctx: RenderCtx, subInd?: number): string[] {
  switch (node.kind) {
    case 'or': {
      // Скобочная ИЛИ-группа, ВЛОЖЕННАЯ как операнд0 И-цепочки, которая сама —
      // операнд верхнеуровневого ИЛИ (`(A ИЛИ B) И C ИЛИ D`): её `ИЛИ` конструктор
      // выравнивает с конъюнктами `И` той же И-цепочки (andCont), а не на ind+1 —
      // приоритет И>ИЛИ держит группу и её соседей-`И` на одном продолжении
      // (корпус УчетСтраховыхВзносов*: `((A ЕСТЬ NULL` / `»»»ИЛИ B)` / `»»»И C`).
      // Узкий гейт: andCont уже глубже ind+1 (т.е. эта OR — продолжение И-блока).
      const iliInd = Math.max(ind + 1, andCont);
      const childAnd = iliInd + 1;
      const lines: string[] = [];
      // Операнд ИЛИ-цепочки — скобочная И-группа (`(A И B) ИЛИ (C И D)`) или одиночный
      // скобочный предикат-лист (`(X МЕЖДУ a И b) ИЛИ …`): обёртка избыточна, оракул её
      // снимает. Разворачиваем `group(and)`/`group(leaf)` (фаза 6.16.78). `group(or)`
      // сохраняем (значимая обёртка).
      const orOperands = node.operands.map((op) =>
        op.kind === 'group' && (op.child.kind === 'and' || op.child.kind === 'leaf') ? op.child : op
      );
      orOperands.forEach((op, k) => {
        if (k === 0) {
          // CASE-операнд0 ИЛИ-цепочки value-слота (`ВЫБОР…КОНЕЦ ИЛИ …`) — булев CASE
          // (КОНЕЦ=ind+1, корпус Документооборот). Прочие операнды0 — прежним путём.
          if (op.kind === 'case') { lines.push(...renderCase(op, ind, ctx, true)); }
          // Подзапрос операнда0 выравнен с операндами ИЛИ: childAnd (MCP, 6.15.9).
          else lines.push(...renderSelectBool(op, ind, childAnd, orLvl + 1, ctx, childAnd));
        } else {
          const sub = renderSelectBool(op, iliInd, childAnd, orLvl + 1, ctx, childAnd);
          sub[0] = tabs(iliInd) + 'ИЛИ ' + sub[0];
          lines.push(...sub);
        }
      });
      return lines;
    }
    case 'and': {
      const lines: string[] = [];
      node.operands.forEach((op, k) => {
        if (k === 0) {
          // CASE-операнд0 И-цепочки value-слота (`ВЫБОР…КОНЕЦ И …`) оракул вкладывает
          // на +1 (КОНЕЦ=ind+1), как булев CASE (корпус НастройкиУчетаСтраховыхВзносов).
          if (op.kind === 'case') { lines.push(...renderCase(op, ind, ctx, true)); }
          else lines.push(...renderSelectBool(op, ind, andCont, orLvl, ctx, subInd));
        } else {
          const sub = renderSelectBool(op, andCont, andCont + 1, orLvl, ctx);
          sub[0] = tabs(andCont) + 'И ' + sub[0];
          lines.push(...sub);
        }
      });
      return lines;
    }
    case 'not': {
      const sub = renderSelectBool(node.child, ind, andCont, orLvl, ctx, (subInd ?? ind + 1) + 1);
      sub[0] = 'НЕ ' + sub[0];
      return sub;
    }
    case 'group': {
      const sub = renderSelectBool(node.child, ind, andCont, orLvl, ctx, subInd);
      sub[0] = '(' + sub[0];
      sub[sub.length - 1] += ')';
      return sub;
    }
    case 'case':
      // Достигается для НЕ-ПЕРВОГО операнда булевой цепочки (`И ВЫБОР`/`ИЛИ ВЫБОР`):
      // слово И/ИЛИ печатается ИНЛАЙН перед ВЫБОР, и КОНЕЦ выровнен с этой строкой
      // (E=ind, boolean=false; корпус ЗагрузкаВыписки). CASE-операнд0 (где `(`/слово
      // на той же строке) обрабатывается в ветках or/and явно (boolean=true).
      return renderCase(node, ind, ctx, false);
    case 'leaf':
      // Избыточная обёртка операнда булевой цепочки поля выборки (`A И (B = 0)` →
      // `A И B = 0`, как оракул): лист здесь — целый предикатный операнд (верхнеуровневые
      // И/ИЛИ его уже расщепили), поэтому stripRedundantLeafParens безопасен — он
      // отказывается от многострочного листа (подзапрос/CASE), В-списка/подзапроса и
      // конструкций, где скобка меняет приоритет. Зеркало leaf-ветки renderBool.
      // Подзапрос поля выборки — на ind+1 (MCP, 6.15.9).
      // Голый операнд-приведение ВЫРАЗИТЬ(…) в сравнении конструктор оборачивает
      // обратно (wrapBareCastOperand) — зеркало leaf-ветки renderBool, иначе снятая
      // выше обёртка `(ВЫРАЗИТЬ(…)) <> …` потерялась бы.
      return [reindentLeafSubquery(wrapBareCastOperand(stripRedundantLeafParens(node.text)), subInd ?? ind + 1)];
  }
}

// --- Printer (join ПО) ------------------------------------------------------

/**
 * Условие соединения ПО (составное / со структурой). База — контентный отступ 2.
 * Конструктор трактует условие как И-цепочку конъюнктов и переотрисовывает только
 * отступы/переносы; текст каждого конъюнкта (в т.ч. наличие/отсутствие скобок)
 * сохраняется ДОСЛОВНО из исходника. Первый конъюнкт — на строке `ПО ` (вызывающий
 * уже напечатал `ПО `); каждый следующий — `И <конъюнкт>` на отступе base+1.
 *   - конъюнкт-лист → дословный текст (скобки из исходника НЕ добавляются и НЕ
 *     снимаются);
 *   - конъюнкт с OR/CASE → структурная переотрисовка (ИЛИ на отступе +1).
 */
function renderJoin(tree: Node, ctx: RenderCtx): string {
  const base = ctx.cont; // 2
  const conjuncts: Node[] = tree.kind === 'and' ? tree.operands : [tree];
  const lines: string[] = [];
  conjuncts.forEach((c, k) => {
    const ind = k === 0 ? base : base + 1;
    // Первый конъюнкт сидит на base — его OR использует orDelta=2 (ИЛИ на base+2);
    // OR внутри последующего И-конъюнкта — orDelta=1 (ИЛИ на ind+1).
    const orLvl = k === 0 ? 0 : 1;
    const sub = renderJoinConjunct(c, ind, ctx, orLvl);
    if (k > 0) sub[0] = tabs(ind) + 'И ' + sub[0];
    lines.push(...sub);
  });
  return lines.join('\n');
}

/**
 * Печатает ОДИН конъюнкт условия `ПО` (фаза 6.15.5: поконъюнктный рендер сложных
 * конъюнктов вместо отката на legacy-путь всего условия). Геометрия идентична
 * `renderJoin`: первый конъюнкт — ind=2/orLvl=0 (его ИЛИ на отступе 4), последующий
 * И-конъюнкт — ind=3/orLvl=1 (ИЛИ на 4). Первая строка без ведущего отступа (как у
 * `formatExpression`); префикс `И ` добавляет вызывающий.
 */
export function formatJoinConjunct(raw: string, first: boolean, base = 2): string {
  // flattenLeaves: многострочные листья внутри конъюнкта (`В (\n a,\n b)` в
  // ИЛИ-операнде) конструктор сплющивает в одну строку (корпус: ВариантыОтчетов
  // bsl_27/28); листья с подзапросом/булевыми операторами не трогаются.
  // `base` — отступ строки ПО (2 + глубина вложенного дерева, фаза 6.15.8).
  const parser = new Parser(raw.trim(), true);
  const tree = parser.parse();
  const tail = parser.tail();
  const ctx: RenderCtx = { cont: base, caseBoolean: true };
  const ind = first ? base : base + 1;
  const orLvl = first ? 0 : 1;
  // Произвольный ВЫБОР-конъюнкт конструктор печатает в скобках (корпус: 6/6 в
  // скобках, голых нет) — скобки исходника сняты классификатором, восстанавливаем
  // раскладкой скобочной группы (`renderCaseE` + внешние скобки).
  if (tree.kind === 'case') {
    // Хвост после КОНЕЦ (`ВЫБОР…КОНЕЦ + ВЫБОР…КОНЕЦ = X`) — это арифметическое/
    // сравнительное выражение из нескольких ВЫБОР, а не одиночный CASE: рендерим
    // весь текст листом (reindentLeafCase раскладывает `КОНЕЦ + ВЫБОР` и хвост на
    // последнем КОНЕЦ), оборачивая в скобки. КОНЕЦ — на base+1 (фаза 6.15.21, MCP).
    if (tail.trim() !== '') {
      const leaf = reindentLeafCase(
        reindentLeafSubquery(raw.trim(), base + 2),
        base + 1
      );
      return appendIsNotNullTrailingSpace('(' + leaf + ')');
    }
    // Восстановленная внешняя скобка `(ВЫБОР … КОНЕЦ)` фиксирует КОНЕЦ на base+1
    // (КОГДА=base+2) НЕЗАВИСИМО от позиции конъюнкта: первый конъюнкт стоит на
    // base, последующий `И …` — на base+1, но скобка выравнивает КОНЕЦ обоих на
    // base+1 (фаза 6.15.9b, MCP/корпус: bsl_14 первый, bsl_195 второй).
    const sub = renderCaseE(tree, base + 1, ctx);
    sub[0] = '(' + sub[0];
    sub[sub.length - 1] += ')';
    return appendIsNotNullTrailingSpace(sub.join('\n')) + tail;
  }
  return appendIsNotNullTrailingSpace(renderJoinConjunct(tree, ind, ctx, orLvl).join('\n')) + tail;
}

/**
 * Один конъюнкт условия ПО. Лист — дословно (скобки как в исходнике). Структурная
 * скобочная группа с OR — раскрывается с сохранением внешних скобок и отступом
 * ИЛИ = ind+1. CASE — раскладка булева слота.
 */
function renderJoinConjunct(node: Node, ind: number, ctx: RenderCtx, orLvl: number): string[] {
  switch (node.kind) {
    case 'leaf': {
      // Внутриконъюнктный разрыв разработчика (фаза 6.16.72): оператор+RHS (или
      // развёрнутый список `В (\n a,\n b)`) одного конъюнкта ПО конструктор сшивает в
      // одну строку. flattenMultilineLeaf сам пропускает листья с подзапросом
      // (ВЫБРАТЬ), вложенным ВЫБОР и булевым оператором — их геометрию не трогаем.
      const flat = flattenMultilineLeaf(node.text);
      // Лист-членство `Поле В (ВЫБРАТЬ … ИЗ …)`, набранный ИНЛАЙН: канонический ре-рендер
      // подзапроса через хук генератора (`(ВЫБРАТЬ` на том же отступе, что и обычный
      // подзапрос конъюнкта ПО). reindentLeafSubquery инлайн не раскладывает (фаза 6.16).
      if (
        inlineSubqueryReflow &&
        /(?:^|[^\p{L}\p{N}_])В(?:\s+ИЕРАРХИИ)?\s*\(\s*ВЫБРАТЬ(?![\p{L}\p{N}_])/iu.test(flat)
      ) {
        const reflowed = inlineSubqueryReflow(flat, ind + subDelta(orLvl, ctx));
        if (reflowed) return reflowed;
      }
      // Подзапрос конъюнкта ПО — на base+2 для любого конъюнкта: первый (ind=base,
      // orLvl=0 → +2) и И-конъюнкт (ind=base+1, orLvl=1 → +1) дают один отступ (MCP).
      // Вложенный в лист ВЫБОР (`(ВЫБОР …)`) — КОНЕЦ на ind + число обрамляющих
      // скобок перед ВЫБОР (фаза 6.15.9b).
      return reindentLeafCase(reindentLeafSubquery(flat, ind + subDelta(orLvl, ctx)), ind).split('\n');
    }
    case 'case':
      return renderCase(node, ind, ctx, true);
    case 'not': {
      const sub = renderJoinConjunct(node.child, ind, ctx, orLvl);
      sub[0] = 'НЕ ' + sub[0];
      return sub;
    }
    case 'group': {
      // Скобочная группа в исходнике (например `(a ИЛИ b)`). Если содержимое — OR,
      // оно само оборачивается в (…) — не дублируем скобки.
      const child = node.child;
      if (child.kind === 'or') {
        return renderBool(child, ind, ind + 1, orLvl, ctx);
      }
      if (child.kind === 'case') {
        // `(ВЫБОР … КОНЕЦ)` в ПО: внешняя скобка фиксирует КОНЕЦ на base+1 независимо
        // от позиции конъюнкта. Здесь base восстанавливается из ind: первый конъюнкт
        // (orLvl=0) ind=base → КОНЕЦ=ind+1; последующий `И …` (orLvl=1) ind=base+1 →
        // КОНЕЦ=ind (фаза 6.15.9b; корпус: bsl_14 первый, bsl_195 второй).
        const caseEnd = orLvl === 0 ? ind + 1 : ind;
        const sub = renderCaseE(child, caseEnd, ctx);
        sub[0] = '(' + sub[0];
        sub[sub.length - 1] += ')';
        return sub;
      }
      const sub = renderBool(child, ind, ind + 1, orLvl, ctx);
      sub[0] = '(' + sub[0];
      sub[sub.length - 1] += ')';
      return sub;
    }
    case 'or':
      return renderBool(node, ind, ind + 1, orLvl, ctx);
    case 'and':
      return renderBool(node, ind, ind + 1, orLvl, ctx);
    default:
      return [''];
  }
}
